window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20010525-6","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"区民委員会","time":"午後１時５８分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2294#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":460,"voices":5}},{"id":"h13-20010525-7","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"厚生委員会","time":"午後 ２時００分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/723274?Template=document&Id=2986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":471,"voices":5}},{"id":"h13-20010525-8","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"建設委員会","time":"午後１時５９分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/428096?Template=document&Id=3688#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":464,"voices":5}},{"id":"h13-20010525-9","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"文教委員会","time":"午後１時57分～午後２時05分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/605950?Template=document&Id=4404#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":464,"voices":5}},{"id":"h13-20010525-13","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"清掃・リサイクル特別委員会","time":"午後２時２０分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/301337?Template=document&Id=5638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":563,"voices":7}},{"id":"h13-20010525-5","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"総務委員会","time":"午後１時５７分～午後２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/517525?Template=document&Id=1546#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":470,"voices":5}},{"id":"h13-20010525-14","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"行財政改革特別委員会","time":"午後２時２１分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503251?Template=document&Id=5684#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":492,"voices":6}},{"id":"h13-20010525-16","meetingId":"h13-cm05","date":"2001年5月25日","dateIso":"2001-05-25","committee":"街づくり特別委員会","time":"午後２時２０分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路副委員長","kind":"意見","question":"１年間、委員長を中心に活発な議論が展開できる委員会にしていきたいことを決意しております。どうぞ１年間よろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/506587?Template=document&Id=6206#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":2931,"voices":41}},{"id":"h13-20010605-6","meetingId":"h13-cm06","date":"2001年6月5日","dateIso":"2001-06-05","committee":"区民委員会","time":"午後１時０５分～午後５時０５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"産業振興課の７ページの勤労者生活資金融資あっ旋についてお伺いしますが、融資率が１3.９６％しかないですよね。この実績の３件という少なさについて、何か理由があれば教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"福利厚生が行き届かない中小企業の従業員に対して一定の小口の金融をあっ旋するというこの制度本来の趣旨のベースになる事情が大分変わってきている…したがって、今年度の推移を見て、この事業自体の存否について検討をしてまいりたいということで考えてあります。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"多重債務者というのが１番で、カードローンとかをどんどん借りていっちゃうと、逆にまた多重債務者になっちゃうわけですよね。区としてはというお考えはあると思うんですけれども、平成１１年度で２１件、平成１２年度で２２件しかこなかったんか尋ねました。","respondent":"市川産業振興課長","answer":"先ほど一部説明に適切さを欠いたかもしれないんですが、総体的に申し込みの数が減っているという状況認識ということで申し上げたつもりです。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１点だけお伺いしますが、特別区税の件でご質問したいんですけれども、特別徴収１００％にならない。すばらしいご説明があったんですが、特別徴収が１００％いかないのはちょっと疑問なので、そこだけ教えてほしいと求めました。","respondent":"松崎税務課長","answer":"大きく分けると、この２つがあるかと思います。そのほか細かいものはいろいろあると思いますが、これが１００％にならない一番大きな理由だというふうに考えております。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問・要望","question":"斎場用地が２万2,５００m2ですか、これが有償だという話も聞いてはいるんですけれども、現時点でどうなっているのかというのが１点。５０ＣＣバイクの1,０００円徴収にかなりのコストがかかっているというお話も伺っておりますが、どう思っておりますかというのが１点。","respondent":"宮地区民課長、松崎税務課長","answer":"全然回答がございませんで、４区の区長と、その件について回答をいただくことになっております。７日はそういう姿勢で行くということで、それで最終的に回答をいただくということになっているのが、現状の段階です。その中でいろいろ新税について検討をしておりますが，再々区長が答弁していますように、新税については現在のところ検討をしていないというか。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問・要望","question":"事業概要の説明ですから、確かに５区の一部事務組合をつくっての報道にはなっておりますけれども、本来２３区全体の問題だと私は思っているんです。ですから、当初の方針どおり無償提供するように、７日ということですから、どういう回答が出るのか期待をして、見守っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"原委員","kind":"提案","question":"事務事業概要ですから、確認を二、三させてほしいと求めました。申し込み方法をもう少し簡略したらというよう提案をさせていただいて、現状ですね、ちょっと確認をさせてほしいと求めました。","respondent":"宮地区民課長、長田地域活動課長","answer":"品川荘が２０人ほど昨年より少ないんですけれども、今のところ考えておりますが、いろいろと様子を把握していきたいと考えています。今年いろいろと検討できるところを着手しまして、もうちょっと様子を見ていただければと思います。 昨年の４月１日、地域事務にも目を向けると、こういう形で実施をしてきたところです。事業の周知の効果の度合いも高いというようなことの認識の中から、やはり周知度の問題から言っても、継続はしていきたいと考えています。","id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"町会のほうも、今お話がありましたけれども、町会が大変なことになっているところがあるんです。だから、地域センターの中での対応、あるいは地区委員の対応等、要するに環境を整えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"金高委員","kind":"質問","question":"順番待ちですから、その辺のところをどういう形で仕切りをして、どの程度までご本人たちが納得いくだけの相談まで踏み込んでしているのか。その辺の実態というものをちょっとお聞かせ願えればと思います。","respondent":"宮地区民課長","answer":"警察のほうからも問い合わせが、またこちらのほうに戻ってきまして、結果としてどうなったかというのも出てあります。相談員が悪くて対応をしてくれないという相談は今のところございませんので、やっぱりきちんと対応していると今の段階では思っております。","id":"exchange-008"},{"speaker":"金高委員","kind":"質問","question":"一部事務組合ですから、これらの方々の報酬というのはあり得るんですか、ないんですか。派遣職員ですから出向ですけれども、報償費が支払いされているのかどうか、その辺のことを１点お伺いいたします。","respondent":"宮地区民課長","answer":"予算的には管理者等の費用弁償１回8,０００円の４回分の５人ということで、２万９１３円は一応挙げておりますが、今のところゼロでやっております。","id":"exchange-009"},{"speaker":"金高委員","kind":"質問","question":"そうしますと、区より派遣という場合には、職員の方はあくまで一部のほうからの給与負担という形で、いわゆる民間で言えば出向という形と同じですから、その間は管理組合のほうからはそれに見合うだけのものが支給されると。","respondent":"宮地区民課長","answer":"そのとおりです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"２点だけお伺いをしたいと思います。もう１点は、国民健康保険７万2,０００世帯余りですか、世帯数の人数で分かりましたらお知らせ願えればと思います。","respondent":"市川産業振興課長、太田保険年金課長","answer":"平成１３年度の予算事業ということでスタートしているものもありますが、公表をしていくという、このような段取りで考えてあります。その時期等については、なるべく早期にということで努力をします。 普通徴収であれば１カ月でも遅れれば滞納という状況になりますので、私どもで把握していますのは世帯数だけですけれども、ここのところ１万3,０００件から4,０００世帯です。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"いろいろつくってこられたんだと思いますけれども、最終的には、そういうところとの詰めなども行ってからということですか。それとも区と日本総合研究所の詰めが終わってから進めていくということか尋ねました。","respondent":"市川産業振興課長","answer":"計画事業のプランニングに当たっては、産業界の関係部署と意見交換などをしてまいりました。表現というか、内容について、最終的に産業界と調整をするということは考えてございません。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"実質的に私の望みから言えば、一日も早く議会に出てきて、実際に議論ができればいいなというふうな思いがあるんですけれども、詰めのところで進行性が求められるということであれば、それはそれで仕方がないことなんですけれども、一日も早く中身が出てくるようお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"学校がせっかく避難所と明確になっているわけですから、区の意向を汲んで、その辺のところの状況を教えていただきたいのが１点。この表上で見ると、なかなか思うように進んでいないのかなと思うので、その辺はどうなんか尋ねました。","respondent":"辻田防災課長","answer":"均一化して、当然私どもの仕事だという具合に考えていますけれども、その辺がなかなか難しいということが１点あります。連絡会議の開催、何しろ取り組みが少ないところについて重点的に実施させていくということで考えて、これは学校のほうの取り組みと。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"なおかつ避難所としての機能も充実させていくという、ですから、一応何かあればそこでみんなが来る体制になる。その辺もやっぱり大変なことだと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田副委員長","kind":"質問","question":"こんなことを聞いていいのかどうかわかりませんが、書式のことでちょっとお聞きをしたいんですが、課ごとで書式がばらばらですよね。せっかくここで事業部制を引いたときに、統一をしてやろうという話がなかったのかどうか、ちょっとお聞きしたいと思います。","respondent":"宮地区民課長","answer":"事務事業概要をつくるための検討会もつくりまして、各課の取り組みのまとめ方がどうしても崩せなくて、本当に申し訳ありませんでした。次回、きちんとしたフォーマットでやっていかれればというふうに思っていますので、もうちょっと時間をいただきたいと思います。","id":"exchange-016"},{"speaker":"石田副委員長","kind":"意見","question":"６ページ、これだと0.８８ですが、こんなはずはないはずなんですね。長く事業をやってきたことに対して一つメスを入れるのか、そういうところをどういうふうにお考えなのか、これを聞きたいなと思いますとの意見を述べました。","respondent":"宮地区民課長","answer":"１０本近い本数を各課が挙げまして、それについては、本当にそれが効果のある事業になっているかというのはきちんと検証できるというふうに思います。そういう視点で事務事業概要をどこまでまとめていかれるかというのもあるんですけれども、課題として考えていきたいと思います。","id":"exchange-017"},{"speaker":"石田副委員長","kind":"質問・要望","question":"最後に、保険年金課の前納の差額ですけれども、これの考え方だけは教えていただきたいんですが、前納分の割引がありますよね。ここは前納をやめる方向なのかどうか、教えてほしいと求めました。","respondent":"小野年金制度担当課長","answer":"私のほうでこれがどういうふうな根拠に基づいてというところまで、現在のところまだ勉強不足で、把握をしておりません。これを廃止するのか、現在のところは廃止をするという方向での情報は得ておりませんで、引き続きこの形でというふうに考えております。","id":"exchange-018"},{"speaker":"南委員長","kind":"質問","question":"私も、今説明してなかったところは読んだんですけれども、なおわからなかったので、改めてお伺いしたいなと思ったんです。","respondent":"野本環境清掃事業部長","answer":"簡単にご説明をしますと、５５０ｔぐらいしか燃やせないぐらいじゃないと、ちょっとしたブレで日最高値で針がピョッと触れることがあるんです。それは、長期のものについては見ていくというようなぐらいでご理解をいただければよろしいのではないかなというふうに考えております。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"その辺の見通しというか、考え方というか、ちょっと説明を求めました。","respondent":"金井環境課長","answer":"さらに、低公害車の導入等々も、これは行政が積極的に進めなさいと。それをいきなりというわけになかなかまいりませんけれども、できるだけ導入に向けて私どもも努力をしていくと、こういう姿勢で現在進めてあります。","id":"exchange-020"},{"speaker":"原委員","kind":"意見","question":"コストは今はかなり高めだそうですけれども、その辺は、例えば品川区内にある同業組合とか、化学業界のところがとりわけ利用があるわけですが、東京都絡みのところもありますけれども、そういったところでは、情報的にはどういうふうな情報をつかんでいらっしゃるのかとの意見を述べました。","respondent":"金井環境課長","answer":"私どもには特に値段も含めまして、今後どういった方向で、どのような方針で進めていくのかというような問い合わせは直接的にはきてございません。国も都もそういった制度を考えているようですけれども、その辺の情報しか私どもはつかんでおらないという状況です。","id":"exchange-021"},{"speaker":"石田副委員長","kind":"意見","question":"これを見て、環境というのはこんなものかなと思うんですけれども、規制ばかりですね、まず。例えば２９ページみたいな自然環境調査で、これから環境を考えていく上にはよくないんじゃないのかなと思うんだけれども、その辺との意見を述べました。","respondent":"金井環境課長","answer":"そういった緑関係も積極的に進めるようになっておりますので、環境システムの中に、検討の中に私どもも公園等も含めて入れていきたい。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"本年度はどういうことをやるのかということが書いてないんですけれども、その後は悪臭がなかなか消えないと、こういうことを繰り返しているわけです。周りの住民の皆さんに協力を求めるのか、そういうことをちょっとお聞かせほしいと求めました。","respondent":"金井環境課長","answer":"悪臭の原因の効果というのが原因究明がなかなか難しい。これが一番大きな目標です。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問","question":"あれは使われているんですか、どうなんですかということと、全体としての運動にすることが私は必要じゃないかなと。構造上、立会川の枝管というんですか、これは所管外になってしまうのかな。","respondent":"金井環境課長","answer":"申し訳ありません、明確にお答えできませんけれども、下水道河川課で調査をしないと。一部どこかが入っているようなことはちらっと聞いたことがあります。","id":"exchange-024"},{"speaker":"本田委員","kind":"質問・要望","question":"小・中学生を含めまして、全区民挙げて、そういう観点というものが今求められている。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問・要望","question":"ディーゼル車というか、そういうのもこの中に入っているんですか。仮にあるとすれば、東京都は一斉強化するわけですから、清掃事務所のほうでも対応を考えていかなければならないですね。","respondent":"金井環境課長","answer":"先ほどご説明しましたように、平成１５年１０月から走れなくなりますので、排出物の低減装置であるＤＰＦを付けます。ここに書いてあるようなことで実施をして、あるいは広報しながわのページですとか、こういうことで抑制のための要請をしています。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問","question":"２年ですよね。その２年間の間に、これから始まるわけですけれども、装置を付けてもだめだということなんか尋ねました。","respondent":"金井環境課長","answer":"いずれにしましても、低減の何％というのが決まっておりますので、そういう装置を付けるか、低公害車に買い替えないと走れないです。基準がありますので。","id":"exchange-027"},{"speaker":"堺委員","kind":"質問","question":"そういう面で低公害車の４３台、６種類もあるんですかね。冬期は３台使用して、２台は使用してはいけませんよと、それは。","respondent":"金井環境課長","answer":"全体という考え方ですけれども、具体的にこれから出てまいりますので、今車の調査もやっております。そういったことも含めて、これから、冬期だけでなくて、普段からきちっと取り組むような方式を考えていきたいというふうに思ってあります。","id":"exchange-028"},{"speaker":"原委員","kind":"意見","question":"これ、急に集まってくださいという連絡を電話か何かでしたわけですよね。どういう形で皆さんは招集してきたのか、時間的なものとの意見を述べました。","respondent":"辻田防災課長","answer":"ところが、遠い人もありますので、どうしても２時間近くかかってしまう。何しろ早く来いということで指示を出しておりますので、みんないろいろな工夫をしながら、自転車、バイクというようなことで参集しております。","id":"exchange-029"},{"speaker":"本田委員","kind":"意見","question":"どう区民の期待に応えて、時々の問題点等を設けながら、全般にわたって審議をしていくということでいくべきではないか。特別特定のものを区民委員会でこの１年間重点的にテーマにするということではなくて、意見としてそのように考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"原委員","kind":"意見","question":"そういう中で課題を持っていこうというふうに考えるならば、２つの事業部を入れると、みんなで１０の課がありますね。例えば地域活動の中では、そういったことで我々も勉強、あるいは努力をしていきたいというふうに思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"菊地委員","kind":"意見","question":"区内の中小企業、振興を含めたところにある程度的を絞った形で考えることはできないかなというふうな希望は持っておりますので、それだけちょっとお伝えをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"石田副委員長","kind":"質問","question":"もちろん今理事者の方もいらっしゃって、委員の８名で１年間これをやっていこうという中で、非常に範囲が広い。じゃ、自分で調査をして、逆に理事者の方がいらっしゃる前でそういう形でやっていきたいということを言ったほうがいいんじゃないですかということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、いろいろ工夫されたものが各所管課でもあるわけですから、効果的になっているのかどうなのかというような議論をさせていただきたいと。ただいきなり今課長のところで何かあるかという進め方は、それはちょっと、今の中でまずいんじゃないですかということを１点申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"その辺のすり合わせをされて、区民委員会としてどこかで目標を持っていかなければいけないでしょうから、そういうすり合わせをしてください。その中で幾つか課題を出されて、我々もこの辺については意見を出しましょう、相談しましょうというような形になると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"ですから、課の中でもいろいろな形で出てくるはずですから、どこの場所が合致するのかということを調べて行かれる。上の話ですから、何人にしてくれという話ではないと思うので、１人なら１人で結構じゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"本田委員","kind":"意見","question":"そういう方法というのがいいのではないかなというふうに思います。それから、同行者の問題については、私は、１人で全部できるのか、２人がどうしても必要なのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"本田委員","kind":"質問","question":"１人でできるなら１人でもいいし、２人がどうしても必要だというのであれば、２人だっていいのではないかなというふうに思います。ですから、完璧な報告書をつくっていただければ、それはそういうことでよろしいんじゃないかなというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"堺委員","kind":"質問","question":"これは向こうで決めていただいていいわけですから、２名にするか、向こう側の考え方でいいと思います。これは当然そういうことで行われるわけですから、今すぐどうこうというのではなく、視察地の候補をしっかりと決めていけばいいのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"菊地委員","kind":"提案","question":"こういうところに行ってみたいという提案を、するわけですから、自分でもなかなか提案できない。２回行ってきただけですから、皆さんが今まで出されている意見も含めて、単純に１名にすればいいというものではないような気もしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"金高委員","kind":"質問","question":"費用の平準化ですか、私は一番最初北海道に行かせていただいたんですけれども、北海道は一番遠いわけですから当然費用がかかる。それぞれ委員会の目的、行く場所によって大きく変わってくるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"石田副委員長","kind":"意見","question":"理事者の方と、書記と、我々との出てくる費用が違う。それの標準化をどうするかということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"金高委員","kind":"質問","question":"そっちのほうですか。ですから、まず今回はどれをテーマにするかというのを踏み込んでいけばいいんじゃないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤原委員","kind":"意見","question":"随行の書記については、経費という形だけ見ちゃうと、１人のほうがとなっちゃうと思うんですが、２名必要であるならば、私は２名でもいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"原委員","kind":"意見","question":"なぜかというと、５常任委員会がある中で、この委員会は視察をしない、この委員会は視察をするということになると、ばらつきの問題も出てくる。やはりある意味のマイナス思考だと思うし、もしそれを論議するならば、違う時点で論議をしなければならないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"石田副委員長","kind":"確認","question":"全体で取り組んで、みんなで割って、それでいいかなという確認だけは。そういうことでいいかどうかという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"原委員","kind":"質問","question":"話を明らかにしておけばいいんじゃないですか。どうするかは、２人で。","respondent":"南委員長","answer":"以上をもちまして、今日の予定はすべて終了しましたので、区民委員会を閉会します。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2296#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":68779,"voices":166}},{"id":"h13-20010605-7","meetingId":"h13-cm06","date":"2001年6月5日","dateIso":"2001-06-05","committee":"厚生委員会","time":"午後 １時０７分～午後 ５時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鶴副委員長","kind":"意見","question":"委員長ともども、一生懸命、実りある論議がこの１年間できますように念じつつ、また理事者のご協力を心からお願いして、ごあいさつとしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"最初に、途中で中座されちゃうということなんだけど、何時ごろまで大丈夫なんでしょうか。とりあえずは、何時までいられるのか。","respondent":"新美保健高齢事業部長","answer":"大変申しわけございません、３時ごろを目途に。権利擁護の検討委員会が、途中で退席しますが、３時ごろを目途に考えております。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"福祉のほうで４３ページ、そのまま若い年寄りというか、ヤングオールドという言葉がどういうことになるのかなというような思いがちょっとあります。５１ページに同じように管理人（ワーデン）とか、お年寄り等に説明するのには、その辺の考え方を教えてほしいと求めました。","respondent":"田中健康課長、小林品川区保健所保健サービス課長、青山品川区保健センター所長、野田口高齢事業課長","answer":"実は、これは廃止の予定で、現在、この次の６月の第２回定例会に条例の廃止を提案させていただこうと思って準備を進めしています。… では、続きまして、２６ページの結核の入所命令についてのご質問にお答えします。大体治療を開始して３カ月しますと、排菌されている方でも… おおむね４カ月児健診については９６％、それから１歳６カ月、３歳については８６％ぐらいの受診率を確保できております。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"でも、この実績はすごいものですから、例えば衛生試験所の中で３万９,０００件なりを実際に検査していらっしゃるのかということ。これはすべての小学校、中学校のプールを検査しないんでしょうかということを説明を求めました。","respondent":"田中健康課長、大沢衛生課長、早津高齢福祉課長","answer":"私も最初に行ったときに、あれっと思ったんですけども、実際にはかなり頑張ってやってあります。わからないものですからいろいろなことを聞いてやっており… １６ページに「届出（学校）プール（延）３３件」と書いてありますが、ふだん、子どもたちだけのための検査等は学校の管理の中でやっております。これは… 私どものほうでも、布団乾燥事業の件数減につきまして、今年度、内容等を分析をして、場合によっては必要な見直し等を行っていこうと思ってあります。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"計算することはできませんけど、１,０００件近くになるんでしょうか。これだけのことを１日にやっていらっしゃるということですから、ぜひ頑張ってくださいということを言っておきます。","respondent":"大沢衛生課長","answer":"こちらのほうから、それぞれの時期に出向いてやっております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どんどん減っていくという状況にはなると思うんですけど、平成１１年度と１２年度の差というのは、亡くなられた方ということで考えていいのかどうか。無料だった方で５,０００円となった方がどれぐらいいらっしゃるのかについて、ちょっと人数がわかったら説明を求めました。","respondent":"青山品川区保健センター所長、早津高齢福祉課長、野田口高齢事業課長","answer":"平成７年に予防接種法が改正されましたときに、健康状態のいいときに、原則的に個別接種に移行いたしました。学校保健会等を通じまして… 高齢福祉手当の減の理由ですが、件数は具体的に把握してございません。ただ、人数で減っておりますのは、死亡の方、転出をされた方… 説明いたしましたように、そういった意味で、現状はわかりません。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"受診率については、後で結構ですので、数字は説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと教えてほしいんですけど、まち方では、この１０月から介護保険料は２倍取られるんだと、そういうふうに言っている某政党の議員もいる。当初、算定された額を納めてもらうことになるんだということなのか、わからない人にわかるように説明していただけませんか。","respondent":"中川原介護保険担当課長","answer":"その内容というのは、平成１２年４月から９月までは、保険料は徴収しない。平成１２年１０月から平成１３年９月までは半額、本則どおりの保険料をいただくのは平成１３年１０月からということで、国から出されたものです。","id":"exchange-008"},{"speaker":"鶴副委員長","kind":"意見","question":"本来は６,０００円のところが１,０００円で済むようになった、そしてシルバーパスというのが存続された。謀略的に言っているのかもしれないけれども、正しく知らしめる必要があると思うんですよとの意見を述べました。","respondent":"野田口高齢事業課長","answer":"対象者ですけども、現在、無料パス所持者で、区市町村民税が非課税の者については、１,０００円ということです。年額１万円、平成１４年度については年額１万５,０００円というような形で、急激に負担にならないようにといったような措置をとったものです。","id":"exchange-009"},{"speaker":"鶴副委員長","kind":"質問","question":"この手数料というのは、どういう使われ方をされているわけですか。あるいは、どういうふうな使われ方をしているとご理解なさっているわけか尋ねました。","respondent":"新美保健高齢事業部長","answer":"平成１２年度、高齢者の社会参加の支援策として、都全体としてはかなりの高額の経費が要るということで見直されました。そのように、今後、運用されていくものと理解しております。","id":"exchange-010"},{"speaker":"鶴副委員長","kind":"質問","question":"もう１点、お伺いしておきたいんですけど、ショートステイです。ショートステイを利用するときの手続上の問題ですが、どういうことが必要なんか尋ねました。","respondent":"早津高齢福祉課長","answer":"ショートステイを利用するに当たりましては、お申込みの際に、身体状況についての医師の診断書等を添えてお申し込みをしていただくというような手続になってあります。","id":"exchange-011"},{"speaker":"鶴副委員長","kind":"質問","question":"介護保険制度がスタートしてから、この１月から利用回数が増えたんですかね。でも、いろいろ緩和していただいて、介護保険制度がスタートしてからはどういう流れになっているんですか、どのぐらいまで利用できるんか尋ねました。","respondent":"早津高齢福祉課長","answer":"要支援ですと、６カ月で何日というようなもので、その日数がかなり低かったわけです。ちなみに、１回に使える最高というのは、要介護度５の方の場合ですと、１月で３０日というように変わってあります。","id":"exchange-012"},{"speaker":"鶴副委員長","kind":"意見","question":"そうしますと、３０日というのは、ショートステイというよりもミドルステイに。３０日と言われると、今、どういう検討になっているのだろうかとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"品川区の場合には、１カ月に１回、１週間程度を定期的に利用される方というのが一つのオーソドックスな利用パターンになっているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事実だけちょっと確認させていただきたいんですが、シルバーパスのところで、非課税者の１,０００円というのは、事務手数料というのが条例、あるいは規則か何かで書かれていることがあるのかどうかだけ聞かせてください。","respondent":"野田口高齢事業課長","answer":"手数料１,０００円の部分がそれ相当じゃなくて、一般的に、その程度の事務費というのはかかります。しかも、なおかつ人件費もかかりますので、そういった意味では大変な経費がかかるというものです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"条例、あるいは規則に、事務手数料として１,０００円ということが明記されていることがあるでしょうかということについて、お答えいただきたいんですが。","respondent":"野田口高齢事業課長","answer":"１,０００円を取るということにつきましては。〔「１,０００円を受益者負担としているか、していないか」と呼ぶ者あり〕 手数料の使途については、何々ということは載ってませんけども、１,０００円ということについては記載されてあります。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問・要望","question":"あれだけ立派なものが配備されているわけですから、もっと有効な活用方法を検討されたらいかがかと思いますが、いかがでしょうか。四つぐらいを質問しましたでしょうか、答弁をお願いいたします。","respondent":"日下部障害者福祉課長、黒田生活福祉課長、金子保育課長","answer":"私どもとしましては、率直に申し上げて、乗車の時点で、この利用についての厳密な取り扱いをするのはなかなか難しいところがあります。先ほど… 昨年度から２３区で共同実施ということで、東京都と共同で実施していますけれど、その方たちは自立支援センターということで利用しています。ただ… この４月から、いわゆる献立を庁舎の保育課でつくりまして、それを各園に送る。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、品川区だけでなくて、いろいろなところと連携をしながら、今は研究をしていってください。今すぐやっていただきたいんですが、すぐに答えはできないでしょうから、検討していただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１１年度から１２年度に、１６３世帯ぐらい減っているんですけど、なぜこんなに減っているのかということについて教えてほしいと求めました。その料金の２分の１を入浴券で支給しますというのが、どうしてこういうふうに減ってきているのかということについて教えてほしいと求めました。","respondent":"上川内福祉改革担当課長、日下部障害者福祉課長、黒田生活福祉課長","answer":"身体障害の方等が、契約に対して、十分にそれを理解して遂行できる能力というものも支援する仕組みづくり。支援費支給ということになりますが… 次の１８ページに出てまいります(1)の医療費の助成の関係、基本的には、そのような制度の変更が影響したということで承知をしております。… ほとんど６０枚のところが大半ということになってありますので、ほかに比べて品川区はまだ多いです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どういうふうな理由でこういうことを出していて、理由をどういうふうに説明して、こういうふうに減らしていくということになるのかということ。それ以外のところでも、そういうことで検討している部分というのはあるのかどうかについて、説明を求めました。","respondent":"上川内福祉改革担当課長、黒田生活福祉課長","answer":"契約のほうに移行するのは主に平成１５年度からです。 他区が説明している中でも、６０枚のところでも、説明事項には書いてございました。法外援護というのは、あくまでもプラスの援護というところですの… 細かい政省令等が、国のほうからまだ出されておりませんので、それが出てからということになろうかと思います。 すみません、答弁漏れがございました。入浴券以外の法外援護につきましては、社会情勢に応じて検討してまいりたいと思います。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問","question":"それと、障害者の放課後対策みたいなものが、品川区のこれからの事業の中にどう展開をされているのか、わかっている範囲でお聞きをしたいと思います。もしわかれば、そういう情報を障害者の方たちに教えてあげれらるんですが、もしわかりましたら説明を求めました。","respondent":"金子保育課長、日下部障害者福祉課長","answer":"緊急一時保育のお尋ねですけれども、まず、年齢ですが、あくまで就学前ということで対象を考えております。このケースにつきましては、保育奉仕員の自宅で保育するということを前提として考えている制度です。その辺の活用も含めまして、障害児の放課後対策等についての取り組みを進めてまいりたい、そのような検討を進めていくということで考えております。","id":"exchange-020"},{"speaker":"嶋委員","kind":"質問・要望","question":"私も１カ所だけ見つけて、感動して見せていただいたところがあるんです。褒めていただきたいと思う部分がありますので、情報を教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須藤委員","kind":"意見","question":"それぞれの事業部制がどういうことを目的にするかというのは、これからの委員会で表示してくれる機会があるのか、ないのか。それに対してどうだという方向性が、課なりでできてくるのかどうか、その辺をお聞かせ願いたいと思いますとの意見を述べました。","respondent":"日下部障害者福祉課長、上川内福祉改革担当課長、小沼福祉事業部長","answer":"ところが、現実の実態の問題としては、お１人で１,０００世帯ぐらい抱えていらっしゃる地区もあります。ただ、そういうことで、かなり調整の努力は… 委員のご認識のとおりでございまして、名前も変えまして、利用者主体の福祉サービスを提供するとの観点から見直されたものです。あるいは課題の設定等、そういう点では当然報告をしてまいると、私のほうでは考えてあります。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいことは、東京都とか、品川区がこの保育園に対してどのようにかかわりを持っていくのか。それからあと運営費を出すわけですから、その使用目途の明確化をどのようにされていくのかということ。","respondent":"金子保育課長","answer":"それについては、今後、検討していきたいと思います。指導検査の項目は、委員、ご指摘のとおり、厳密に考えていかなければならないと考えています。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"もしくは民間の方が手を挙げてくるでしょうから、品川区の責任として要綱を定めて、ある程度しばりをかけていく。それから、ＰＲをしていっていただければと思うんですが、あわせてその答弁をお願いいたします。","respondent":"金子保育課長","answer":"障害者福祉課長から説明があったと思いますが、東京都は考えていまして、きちっと提供していくということが一つの要件として定められています。従前、認証保育所が設置された暁には、認可保育園ともども十分なＰＲはしていかなければならないと考えております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区で、現在、開設されている未認可保育園などで、このＡ型、Ｂ型の対象になる園というのがどれぐらいあるのか教えていただきたいのが一つ。２分の１ずつ、なぜ公立保育園や認可保育園なんかと同じような保育料の設定にならないで、説明を求めました。","respondent":"金子保育課長","answer":"無認可保育所ではなくて、４月に設置されました日本音楽学校の保育室がありますけれども、これについて検討されているというふうにお聞きしています。ですが、検討の結果、これが難しいという判断もお聞きしているところです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都と区市町村が２分の１ずつ補助するということで、それでもどうして公立保育園と同じような保育料にならないで、わかったら教えていただきたいんです。","respondent":"金子保育課長","answer":"前提として、それの２分の１ずつを負担するということですので、それ以上経費がかかるだろうということが一つ想定されることだろうと思います。その点で、ご理解いただければと思います。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"実際に開設されていて、対象になる園で、日本音楽学校が検討したけれども、実際には難しいということなんですけれども、そういうところで言えば、平米数とかいうところで、なかなか現在の保育園はこれを満たしていないという状況だというところなんか尋ねました。","respondent":"金子保育課長","answer":"平成１３年度の予定数が１０施設となっているんですが、７月の第１回が締め切れられるということで、かなり厳しい条件であるわけなんです。その２点から、難しいというふうに判断していると聞いております。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問","question":"今の１０施設、１００施設というのは、２３区トータルでこれだけということでいいのかということ。その辺のところが、わかりましたら説明を求めました。","respondent":"金子保育課長","answer":"Ａ型１０施設、Ｂ型１００施設というのは、品川区だけではなくて、東京都全体でこの数だという説明です。あくまでも区の意向というか、区が補助をするという前提があって初めて認証保育所を指定するという話をされております。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問","question":"部長、いかがですかね、この辺は素直に「はい」と言うようになれますかね。いきなりぽんと来てというと、なかなか難しいんじゃないかなという感じがするんですけども、いかがか尋ねました。","respondent":"小沼福祉事業部長","answer":"保育課長が申し上げましたけれども、詳細的な説明は別として、大きなところでは、東京都が認証保育所制度ということを出発させた経過があります。そういう考え方であれば、要所要所で申し入れいく、あるいは伝えていくということで臨んでいきたいと考えています。","id":"exchange-029"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"その人たちの要望にどうこたえていくかということが、今、大きな行政課題になっているわけです。これは要望でございまして、私のほうからも、ぜひお願いをしておきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"須藤委員","kind":"意見","question":"見直す必要があるかないか、皆さんで検討ですけども、これは我々のやり方によってだと思うんです。皆さん方でやるということであれば、私は、ゼロでも行けるという考え方を持っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"質問","question":"区長と前議長でそういう状態ですから、書記を１人にすることについては、書記の負担がすごく増えると思います。そういう方法もあろうかと思うし、そういう方法を委員会として一緒に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"伊藤委員","kind":"意見","question":"私は１人で十分いけると思うし、私は、１名のほうがいいと思います。意見でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"鶴副委員長","kind":"意見","question":"１名にするんでしたら、今度は委員会で、例えば行政視察とはいかがなものかと、こういうことにまでなってくると思うんですよ。でも、１名というのは、準備を私たちができるかなと、それが心配ですよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、その辺については、同等の場所で対応できます。ですから、切符の手配から旅館からぱっとやってくれて、あとは我々がしっかり動けばいいことだろうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"須藤委員","kind":"質問","question":"僕はゼロでいいです。自分たちでやれというんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"事前に私たちがやるべきことをやるとか、報告を整えるとかというのは、私たち議員でできると思うんです。私たちが何をどうすれば、１人でも大丈夫なのかというあたりが、ちょっといま一つ見えないところなんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"部屋割から、あなたのお部屋はここでどうですかって。部屋がどうの、何がどうの、みんな書記にお願いをしたのが事実だと思うんでね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高木委員","kind":"質問","question":"緊急的でもなくて、まだ余裕がありますから、今ここでそんなに議論を深めなくても、ややおおむね意見が出れば、調整をはかりつつ。状況は改革の方向ですから、お任せいたしますから、ひとつよろしく頼みます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"船波委員","kind":"意見","question":"その委員会の視察を継続する大切な一つの要素だと思うので、書記１人で、私たちができることは担うというスタイルでやってみてはどうかと思います。〔「やらなきゃだめだよ、やることはやらきゃ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問","question":"議員同士でできない部分も当然あるでしょうから、もしかしたらゼロという可能性が出てくるかもしれないけど、１人にすることも十分可能だと思います。ですから、正副委員長にお願いしたいのは、１人というふうにまとめていっていただければという気がします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鶴副委員長","kind":"意見","question":"要するにその１人の書記が行政視察に当たってやるべきことは、今、委員会によって書記にいろいろ負担の偏りが出てきたら申しわけないと思うんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"嶋委員","kind":"意見","question":"一応、項目を全部出すので、いわゆる地元の地域の、品川区の特徴との比較から、ある程度決まっていると思うんです。そういうことなので、ぜひまた今年も、自分のいろいろなものの考え方とか勉強になりますので、報告書を作成していきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須藤委員","kind":"質問","question":"この人はこの間に居眠りしたんじゃないかなというのが、後で書かれた文章を読ませていただくと、ちょっとわかったということもありました。ですから、やり方は、品川区議会としてどうだろうということで、今度、正副委員長会で整理をされたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"船波委員","kind":"質問","question":"では、去年の建設委員会のように分担されたときには、皆さん希望を出し合って、分担されたんですか。じゃあ、私はここを書きたいという希望が偏ってしまったりしたようなところはないんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"嶋委員","kind":"意見","question":"やっぱりそれぞれ同じものを見ても感じるものが違うので、それを文章化するのは箇条書きでも、何でも。でもやっぱりそれぞれその人の自分のものの見方、考え方とか、興味を持ったところとかあると思うので、私はやっぱり自由にやりたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"嶋委員","kind":"意見","question":"眠っていたのかなと思われちゃうぐらいに文章が少ないかもしれないけど、そういうときは、きっとそこに興味を持たなかったのか。逆に、次の項目のときには、すごく長く書くとか、それぞれあっていいのではないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"須藤委員","kind":"意見","question":"ただ、全部が同じことを書いてくると、同じ文章がずっと３人も４人も並んできちゃうんですよ。極端に言うと、そういう文章をＡさんも、Ｂさんも、Ｃさんも書いたというのが出てきちゃう可能性もあるんですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/723274?Template=document&Id=2988#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":73523,"voices":194}},{"id":"h13-20010605-8","meetingId":"h13-cm06","date":"2001年6月5日","dateIso":"2001-06-05","committee":"建設委員会","time":"午後１時０７分～午後４時０８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"意見","question":"日本共産党の上山です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"本日の予定表はお手元に配布の通りですが、事務事業概要の説明から報告事項まで、大変多岐にわたっております。できれば事務事業概要の説明を簡略にお願いいたします。…","agenda":"本日の予定表はお手元に配布の通りですが、事務事業概要の説明から報告事項まで、大変多岐にわたっております。できれば事務事業概要の説明を簡略にお願いいたします。…","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"２１ページ、雨水流出抑制事業でやるということで書いてありますが、どんなようなことを計画されてているのか教えていただきたいのが１点。あるいはそういう住民のほうからの要望が出ていたように思うんですが、そこら辺、大きく２つお尋ねしたいんです。","respondent":"松代道路公園課長、岩田管理工事課長、北村下水道河川課長","answer":"区道に１万8,０００余の街路灯を設置しています。照度も調べ、適切な照度が保たれるような対応をしてまいりたいと考えておりますので… ２点目の大崎公園の件ですが、今年大崎公園の全面改修を予定しておりまして、あわせて公園便所も一緒に改築をするというものです。工事の契約のほうが結ばれまして、これから６月中に工事着手ということで、概ね１年程度の工事期間を予定しています。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"具体的な、こんなものをつくるとか何か、もし予定みたいなものがあればお聞かせいただければと思ったんです。例えば一般的に言えば，浸透桝を入れるんだとか、そういう何か具体的なことがあればお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"私ども公園における雨水浸透対策は、まず基本的には、底抜けしている桝ですね。穴があいているような管を設置しまして、そういう形で、できるだけ公園に降った雨は地下に涵養するというようなことをやっております。","id":"exchange-003"},{"speaker":"築舘委員","kind":"質問","question":"３つあったところが１つになるということなので、その次長の役割といいますか、大きいと思うんです。住宅というと、ある意味では総合的に今後大きなまちづくりの核ですから、そこのところを説明を求めました。","respondent":"中谷まちづくり事業部長","answer":"先ほどご説明しましたが、こういうものにつきましては、私のほうで一括して行うということで部全体としてはコントロールします。そして従来３部といいますと、今回の事業部制の私どもまちづくり事業部の使命だと考えていますので、よろしくご理解のほどお願いいたします。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"今、部長からもご説明があったように、従来、それぞれの課がやっているということで、重複するような形の部分もあったような感じもするんです。それぞれの設計、それから、ほかの課との兼ね合いというのもしっかりと位置付けられているのかなという部分がちょっと心配なものですから。","respondent":"岩田管理工事課長","answer":"狭い４km四方の区ですので、管理部隊は１個にまとめて、道路も公園もそれぞれの部隊がきちっと管理をするという基本で今回改正をいたしました。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"何か周知だとか、そういうシーズンを迎えるに当たって、何か具体的な方策を考えていることがあればお尋ねしたいことが一つ。既に終わったものがあるんじゃないかと思うんですが、そこらは現状としてどうなっているのか、まず教えてほしいと求めました。","respondent":"北村下水道河川課長","answer":"クイックプランですけれども、区内では３つの地区が指定されてございまして、大規模なものは順次工事を進めているという状況です。区のほうと連携して浸透桝の設置ですとか、そういうような形で取り組んでいるものもありますが、大きなものはまだできていない状況です。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"例えば水害がもし出ちゃった場合に、こういうところに連絡したり、こういう機関がこういうものをやるとかというのは書かれているんでしょうか。契約の内容によっては、できないわけはないと思うんですが、そこらをあわせて教えていただけますか。","respondent":"北村下水道河川課長","answer":"中期的な取り組み、ほかの道路管理者との連携がありますけれども、きちっと各管理部所のほうで対応を進めているというような状況です。この辺が概ね１年という予定ですので、そこら辺が第１号ぐらいになってくるのかなというような認識で捉えているところです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"国と地方自治体のマンション管理に対する支援を義務付けている初めての法律が出て、それを受けて区はどうしようとしているのか。あるいは今までの延長線なのか、ちょっとその考え方だけ教えてほしいんです。","respondent":"田村住宅課長","answer":"前回の住宅マスタープランにもマンション管理の関係を私はご説明したんですが、マンション管理の適正化指針というものが国のほうから公表される。あわせて６月の中旬頃、あくまで予定ですけれども、今後の取り組みについて検討をしていきたいというふうな考えです。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"マンション住民の要求をどうサポートできるかというのではなくて、地方自治体として貧弱なんじゃないかというふうに私は思えてならないんです。７、品川区として先取りして、相談窓口を機能させていく問題については先手を打ってやっていただきたいということだけ要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"築舘委員","kind":"質問","question":"多目的広場の場合、サッカーとか、ソフトボールとか、そういうスポーツはできないものでしょうか。「などの」と書いてありますが、「など」は、どの程度の「など」か。","respondent":"岩田管理工事課長","answer":"なお、多目的広場の周りにつきましては、球技等も使う関係で、４ｍから５ｍぐらいのネットフェンスで周りをすべて囲うというふうに考えてあります。なお、夜間照明施設も検討をしています。","id":"exchange-010"},{"speaker":"築舘委員","kind":"質問・要望","question":"多目的ということですので、なるべくいろいろな形のスポーツができるような工夫をしてほしいと求めました。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"横山副委員長","kind":"意見","question":"２００ｍのグラウンドを持っていますので、どういう貸し出し方というか、管理の方法を考えているのか。今もちょっとお話があったんだけれども、どういう使い方をしようとしているのか、イメージだけとの意見を述べました。","respondent":"岩田管理工事課長","answer":"それから、多目的広場の、いろんな球技やスポーツに対応できるような施設をまずつくっていこうという考えで今のところ設計に入っております。","id":"exchange-012"},{"speaker":"横山副委員長","kind":"質問・要望","question":"ですから、要望が出てきて、使ってほしいと求めました。これまたがっかりしちゃう部分があるし、そこら辺のところ事前にしっかりしておかないといけないと思うので、有料ということも考えていいのか。","respondent":"岩田管理工事課長","answer":"まだこれから検討をする段階ですけれども、当然のことながら、原則有料で考えていきたいと考えております。有料を原則としながら、一般区民の利用については特別な考え方も頭に入れながら、いろいろ検討をさせていただきたいと思います。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"近隣の館とのバランスという話があったんですが、参考のために、他の館ではどんな料金設定をしているのか、教えていただけますか。","respondent":"松代道路公園課長","answer":"その中で料金等を詳しく説明したものはなかなかございませんで、その中で比較的分かりやすいものを２０館ほど出しました。近隣の関東近辺の大洗水族館、葛西水族館、サンシャイン水族館等を拾い上げまして、そういったところの入園料等を比較検討しました。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"今度シャークを入れて、どのぐらい魅力か増えるかわからないけれども、これだけの不況ですからね、その中で値上げを、これは２２％ぐらいですね。大変難しい選択だとは思うんですけれども、私は今上げる時期じゃないというふうに思うけど、感想だけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"築舘委員","kind":"質問・要望","question":"かなりお金もかけているわけですけれども、売店はどういう形で、売り上げなどが区のほうに影響してくるのか。どういった形に売店関係がなっているのか、ちょっと教えてほしいと求めました。","respondent":"松代道路公園課長","answer":"従前から館内ではなく、今回、図面のほうの既存レストランの正面に外付けで売店を設置しました。入館料と合わせて、売店等の売り上げがあれば、そういった形の収支が出てくるというふうに考えてあります。","id":"exchange-016"},{"speaker":"横山副委員長","kind":"質問・要望","question":"定期的にやってあげるべきものだと思うんだけれども、前に１回やってから何年か経っているという、そんな印象しかない。来館者の声というか、どういう評判をもらっているか、その辺をちょっとお聞かせほしいと求めました。","respondent":"松代道路公園課長","answer":"そういった関係で実施したいというふうに考えてあります。私どももその辺考えてございまして、今後いろいろと検討の中に入れていきたいと考えています。","id":"exchange-017"},{"speaker":"築舘委員","kind":"質問","question":"区民住宅に関しては、最近の傾向としてはどんな具合になっているか、ちょっと説明を求めました。","respondent":"田村住宅課長","answer":"その時点では出る予定がなかったのが、８割なので、なかなかそういう状況をつかめないという実態が現実にはあります。５戸程度なので、今後空くだろうという見込みのものも含めての募集ですので、何とか本来の募集で対応できるというふうに考えております。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"応募団地数というのは、どういうことなんですか。というと、大体どれぐらいになっているのか、傾向を教えてもらえますか。","respondent":"田村住宅課長","answer":"昨年ですと１地区ということで設定しておりますし、西大井等を２番ということで、そこに登録してもらうという形で考えております。上は１９万2,０００円、４万9,３００円から８万2,０００円ということで、それ以外にかかるという内容です。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"前に住んでいた人の家賃を引き継ぐというのは、国庫補助の関係があるので難しいのかもしれないけれども、何とかならないんですか。3.５％ずつ上がって、５年以降３％で上がったら、そこは全然考えていないんか尋ねました。","respondent":"田村住宅課長","answer":"２０年間トータルで換算しておりますので、入るか、入らないかという考えに待たざるを得ないと思います。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"要望だけ言って、終わります。国の補助制度を使っていますから分かるんだけれども、何とかしてほしいということだけ要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"辻委員","kind":"質問","question":"１８団地で、１７４人、これは都営住宅の場合もそうなんですか。昨年の場合はどうだったんか尋ねました。","respondent":"田村住宅課長","answer":"単身者向も入れまして５７世帯ということで，実際のあっ旋率で申し上げますと、大体３０％から４０％です。あるいは転勤等で、登録されているけれども、特に希望はしませんというようなこともあったというふうに聞いております。","id":"exchange-022"},{"speaker":"辻委員","kind":"意見","question":"応募数１７４人というのは、１７４件申し込みがあったということでしょう。リストに載っているのは何名だったのか、そのうち実際に１年間で入ったのは何名で、辞退も含めてという、この辺をもう一回お願いいたしますとの意見を述べました。","respondent":"田村住宅課長","answer":"それで実際に区民住宅で応募者数については、先ほども申し上げたとおり、１７４名の応募者があります。実際に空きがあったりする場合のあっ旋をした数が合計５７世帯というのが、何らかの形であっ旋して、ご紹介したのが１７４件のうちの５７世帯です。","id":"exchange-023"},{"speaker":"辻委員","kind":"質問","question":"都営の空き家というのは違いますね。当たった人は１年間待っているということがあるんですけれども、それがそのまま全部リストになって、順位だけを決めるということなんか尋ねました。","respondent":"田村住宅課長","answer":"２０団地とか１８団地でやると、柔軟な対応をしているので、その部分では都営住宅と若干仕組みが異ります。区民だけですから、どうしてもそういう形に弾力的に対応していくというのが一つあります。","id":"exchange-024"},{"speaker":"辻委員","kind":"意見","question":"１人だったら、同じことだし、テーマとしては、２人で行くか、１人かというんだったら、２人。１人にしても、２人にしても同じ、その充てる費用は自分持ちをしなければいけないというような話になったのでは申し訳ないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"無理なのに１人に絞って、できるのか、できないのかというのをやってもらったほうがいいんじゃないか。理事者は２名から１名、それは妥当だと思うけれども、書記を１名にするというのは大変なんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"横山副委員長","kind":"意見","question":"１人は、書記はいつもうしろで、後ろ前をガードしていなくちゃできない。どの程度お手伝いというか、協力できるかでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"築舘委員","kind":"質問","question":"今まで２名で、議員がそれが当たり前のような感じでやっていたものですから、それが集中しちゃう恐れがあると思うんです。ちょっと可哀相だなという感じがするものですから、２名が１名でできるのかという仕事量をしっかりとやって、それでするならいいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"横山副委員長","kind":"質問","question":"６月の時点だからね。ですから、今から経費を足しての話じゃないから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"横山副委員長","kind":"質問","question":"気持ちがあるようですから、だけど、一部できない部分があるやにちょっと聞いているのね。現在３日間で5,７００円の落差に縮小するということですから、１日にしてみると、2,０００円足らずですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"内容をどう調整するのか、分からないから説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"横山副委員長","kind":"意見","question":"「調整の認められる範囲で同一行動を保障していきたい」ということなんです。金額的には、数字は固定されちゃっているけれども、調整の範囲が区長にあるんじゃないのかなとの意見を述べました。","respondent":"事務局","answer":"事務局よりご説明いたします。内容としては、雑費等ということになりますので、そういうものに関しましては差額が残るということになります。","id":"exchange-032"},{"speaker":"沢田委員","kind":"意見","question":"僕は、１年間なら１年間の総務委員会の全活動を通じてその施策が実際に役立ったり、血肉になったりするために視察をやるんだと思うんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"横山副委員長","kind":"質問","question":"少なくとも１０項目ぐらいあったから、それに１人１項目か２項目ずつ受け持ったから、書記はある程度去年のほうが楽だったと思う。みんな我々が資料をもらってきたものを全部清書して、一定の書式ですから、そこに出させてもらって、それをまとめ上げた部分があるのでね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"築舘委員","kind":"意見","question":"全員が項目全部のところで。そこだけに集中しちゃって、あとはどうでもいいとはならないと思いますけれども、それぞれのを全体で意見を聞いていくというのもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"横山副委員長","kind":"質問","question":"みんなが感じたままに十何人のがボーンと集まっちゃって、それを一つの報告書にしろといったって、とても作業できないんですよ。ですから、担当を決めて、報告者に責任を持たせて、あとほかの委員が感じたことを一言そこに付け加えるような形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"上山委員","kind":"質問","question":"例えば前回で言えば、去年の区民委員会で行った視察先のいろんな感想などを出してもらって、もちろん項目はありますよね。それは記録に残るわけですから、私もうまく言えませんけれども、これが一番だと言えませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"横山副委員長","kind":"質問","question":"やっぱり書記が一番苦労されちゃうんでね。ですから、それがいいのか悪いのかあれだけれども、事務局の中では評判がよかったみたいで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"沢田委員","kind":"意見","question":"総論的な、なぜそこを選んだかだとか、そういうのは、例えば委員長なり副委員長なりで、あとは項目別にそれぞれ担当して、帰って、その項目別に個人の意見も書けるスペースをつくっておくとすれば、みんなでつくったことになるとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"沢田委員","kind":"意見","question":"この１年間どういう委員会活動をするのかというのを、次回か、どこかで設けてもらえるとありがたいなと思います。そうすると、それが一つの視察のテーマにもなってくるんじゃないかなと思うので、ちょっと検討をしていただけるとありがたいんですけどとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/428096?Template=document&Id=3690#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":48008,"voices":148}},{"id":"h13-20010605-9","meetingId":"h13-cm06","date":"2001年6月5日","dateIso":"2001-06-05","committee":"文教委員会","time":"午後１時０７分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼副委員長","kind":"意見","question":"副委員長になりました飯沼です。委員長とともに力を合わせて頑張って運営してまいりますので、どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"松澤委員","kind":"意見","question":"委員長、副委員長の言うことをよく聞きたいと思います。どうぞよろしくとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"山路委員","kind":"意見","question":"公明党の山路です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"桜井委員","kind":"意見","question":"日本共産党の桜井恵子です。どうぞよろしく、お手柔らかにお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"桜井委員","kind":"提案","question":"この辺の理由というんでしょうか、定員３０名のところをプラス４８だったか、ちょっとそこを。予算的には考えたらという提案があったりしたので、ちょっとお知らせいただきたいなというのが、学校選択制にかかわる点ですとの意見を述べました。","respondent":"久保田学務課長、青木指導課長、富田教育改革担当課長","answer":"６０名の中の３０、３０の中にも、大体私立に行かれたようです。ただ、正確なところはあれですけれども、大体そんな形で… 特色ある学校づくりのことについてお答えいたします。学校のほうからまた要望等もこちらのほうに上げていただきながら… すまいるスクールの実施につきましては、第２学期からということで、現在検討調整を重ねているところです。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"検討の内容というんですか、そういう辺の関係をちょっと教えていただきたいのと、教えていただきたい。数字はそういう数字ではっきりしているわけですから、その理由というんでしょうか、もしわかっていたら教えていただきたいというふうに思います。","respondent":"富田教育改革担当課長、久保田学務課長","answer":"４時１５分から５時までが休息、６時間目が終わってからの児童の一番多い時間にそういったことがありまして、検討しているというようなことです。運営の柔軟性の問題、また教員の参加… 一つには、今年はそういう傾向が来年またこのままいくかどうかというのは、非常に難しいものがあります。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"保護者にどのように求められているのかという問題提起で、常に検証していくことが私は大事だというふうに思っているんですね。すっきりしたところで、現場の声もきちっと支援を受けられる体制にとっていただきたいという、これは要望しておきます。","respondent":"久保田学務課長","answer":"今年もそういうふうには考えております。私どもが意見なり、あるいは要望を吸い上げてやっている、こういう状況です。","id":"exchange-007"},{"speaker":"川西委員","kind":"質問・要望","question":"そういう立場から言いますけれども、子どもたちの声はどうなのか、１回お聞きしたい。それで、区の権限になるということの見通しはどうなんか尋ねました。","respondent":"富田教育改革担当課長、久保田学務課長、青木指導課長","answer":"今回モデル実施するのは第二延山小学校ですが、第二延山小学校の学校長の先生のほうの理解がございまして、こちらで実施ということになったものです。… それから６年生の移動教室、特に５年生のときにはキャンプファイヤーを中心にした集団生活というようなものを強調した形でやっております。それはその都度… ２点目ですが、学校はそれぞれ担任や養護教諭などが中心になって対応していますが、児童委員がそこに入ってくるというケースもあります。","id":"exchange-008"},{"speaker":"川西委員","kind":"質問","question":"そういうのだけでは形式的になってしまうというふうに思いますので、こういう制度があるのかどうかというふうに伺いたい。その辺をシステム上の問題とか、実施して、教育委員会が受け持って、システムが変わってからの問題点があるのかどうか、お伺いします。","respondent":"南生涯学習課長","answer":"基本的には施設を利用される方の駐車場は無料が原則というふうに私は理解しておりますが、まだちょっと２カ月で、不十分な部分もありましたらお許しいただきたいと思います。","id":"exchange-009"},{"speaker":"川西委員","kind":"質問","question":"ちょっと参考までに。何人ぐらい登録者がいるのか伺いたい。","respondent":"南生涯学習課長","answer":"学校支援ボランティアにつきましては、ページで申し上げますと。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１４ページのところの教職員住宅の維持管理に関してなんですけれども、ゆたかと伊藤にありますけれども、これで１４戸、１２戸、６戸、６戸、全部で３８戸、これは現在全部ふさがっている状況ですか、その辺の管理状況を教えていただけますか。","respondent":"鷹倉庶務課長","answer":"ゆたか教職員住宅は、１戸ないし２戸空いてたかというふうに把握しています。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう全部ふさがっている状況ということで、これは教職員の方、品川区が管理しているということは、教員の方は品川区内にいらっしゃる教員ということでとっていいんか尋ねました。","respondent":"鷹倉庶務課長","answer":"原則的には区の職員ということでやってありますけれども、例外的に他区の方がいらっしゃる場合もあろうかと思ってあります。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"教員利用が。先生が大体品川区の方が多いということか尋ねました。","respondent":"鷹倉庶務課長","answer":"原則的に、９０％位が区に勤務する職員です。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。これは都から来るお金では、財源としては違う、区の独自の財源ということか尋ねました。","respondent":"鷹倉庶務課長","answer":"基本的には特定財源として使用料があがるわけですけれども、それはすぐ一般財源のほうに。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"数字的なことなんですけれども、９ページ。各学年の数字を教えていただきたいというのと、ちらっと聞いたものですから、その辺の真偽をお伺いしたいと思います。","respondent":"久保田学務課長","answer":"それで４名の方は、当然区内の方と、それから引っ越しされて、こちらに入られたという方もいらっしゃいます。そんなところです。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"例えば４０人いたら、ここが９０人いたのが６０人になるわけですから、３分の１が減ったということになる。あるいは議会答弁を聞いているんですから、複式学級ですか、今後どのように考えていくのか。","respondent":"久保田学務課長、青木指導課長","answer":"やはり、この小規模校の取り組みということで、厳然たるところで継続しているというところがあるだろうということなんです。これからの先々については地域の方も含めて… 少人数学習というのは主流になってまいりまして、生活集団と学習集団を分けて指導しようというような考え方も出てきて、実際に始めているところです。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"３年ですか、もう１０年たちますので、その辺の考え方。あれはある程度もう終わりなんか尋ねました。","respondent":"久保田学務課長","answer":"もう数校しか品川区の場合はないわけですので、その辺の考え方について、やはり一定程度これからの検討は必要だというふうには思っております。","id":"exchange-017"},{"speaker":"山路委員","kind":"質問・要望","question":"大丈夫でしょうかねということと、その辺まで一応到達した上で、展開はどういうふうになっていくのかをちょっと説明をしてほしいと求めました。もう１点は、４５ページのＰＴＡ研修会の研修事業についての内容と、目的というのをお聞かせほしいと求めました。","respondent":"南生涯学習課長","answer":"まだ十分予定が立たない方もいらしたりというような事情があるのではないかと考えていますが、ただ、４回実施していく予定ですので。お互いの経験からさまざまないい刺激を受けて、ＰＴＡの運営に生かしていくことができる、そういった目的で実施しています。","id":"exchange-018","title":"議員研修会の内容と所要時間"},{"speaker":"山路委員","kind":"質問","question":"非常にもし欠席した場合に圧力をかけられるとか、いろいろ言われるとか、そういうことがあるんでしょうか。それはそれで、要するに先生とかは研修ですから、自由というんでしょうか、その辺についての実情をちょっと説明を求めました。","respondent":"南生涯学習課長","answer":"ただ、２回目、３回目と実施してまいりますので、初回の実施の状況を把握し、それを踏まえて問題点の改善等に努めていきたいと考えています。ＰＴＡ連合会、ご都合が悪ければ、そのようにお申し出いただいているところです。","id":"exchange-019"},{"speaker":"山路委員","kind":"質問","question":"情報格差をなくしてだれでもがというのがこれの目的でしょうから、役員の方も、あくまでもフォロー体制のほうをよろしくお願いしたいと思います。今まで実績は幾つかあるでしょうから、できればどういう研修をして、どういうところに泊まっているということをちょっと説明していただけますか。","respondent":"南生涯学習課長","answer":"ただいまお尋ねの研修は４５ページの宿泊研修会という部分ですが、小・中のＰＴＡ連合会合同で実施しております。例年、教育長のほうからお話をさせていただいた後、各ＰＴＡの交流を図るというような形をとっているところです。","id":"exchange-020"},{"speaker":"山路委員","kind":"質問・要望","question":"ほかはないですか。聞いていないですか、例えばこれも地域に大きないい影響力が出るための研修会だと思いますので、充実させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021","title":"議員研修会の内容と所要時間"},{"speaker":"高星委員","kind":"質問・要望","question":"ここの関係が、多分前任の文教委員会の中でも議論をされたんだろうというふうに思うんですけれども、最終的にどうなっているのかをお聞きしたいなと。そのことが最終的に現段階の結論ではどうなっているのか、簡単にお聞きしたいと思います。","respondent":"青木指導課長、指田教育次長","answer":"２点目ですが、直接教育委員会の指導下で対応していく問題ではございませんけれども、それにふさわしい教育をするという。そういうことで、当然教育委員会と連絡をとり合って… 私のほうの中で、一応私のほうで各委員長等を含めまして、お話に回って説明に歩いたという内容です。","id":"exchange-022"},{"speaker":"高星委員","kind":"意見","question":"いわゆるわからないという意味でつけたのかどうか、その生徒という名前をつけたのかどうか、その辺がちょっとわからないので。今後そういった共催、後援、支援等々についての考え方を一言だけ聞いて終わりたいと思いますとの意見を述べました。","respondent":"指田教育次長","answer":"当然のことながら、ここは後援名義です。そういうふうなところでもって、区民のために使えるものであればというところでもって整理していきたいというふうに思ってあります。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問","question":"１点だけ。予算が３２万なので小さい部分なんですが、今後どういうふうに計画が進んでいくのかというところと、わかる範囲で説明を求めました。","respondent":"鷹倉庶務課長","answer":"３２万円については事務費ということで、予算特別委員会でも説明させていただいています。この予定ですけれども、あるいはその前のプレス発表の説明もありますけれども、この辺をつくっていくです。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひ使う側の児童・生徒の声を十分に反映してほしいなと思うのと、ぜひ広げて新しいものをつくっていただきたいなと思うことを希望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"桜井委員","kind":"質問","question":"教育委員会で１０回ですか、やっていることは、教育委員会としては公開しますよね。審議というんですか、どういうふうなやり方で研究されたのか、そのあたりはどうなんか尋ねました。","respondent":"青木指導課長","answer":"その調査研究会とか、検討委員会とか、そういうようなところでの公開はしておりません。そういう意味で客観性の高い調査研究をベースにした教科書採択にしたいというふうに考えて、そういう考えです。","id":"exchange-026"},{"speaker":"桜井委員","kind":"質問","question":"実際には、一定程度の基準を持って先生たちが選んだわけですから、教科書の採択および教育方法の適用にあたってと書いてあるわけですよ。あるいは人権問題にしてもどうなのかとか、モデル地区になったというのなら、もうちょっとその辺というのは検討の余地がなかったんか尋ねました。","respondent":"青木指導課長","answer":"２点目ですが、いろいろとお伺いしたいことがあれば、そういうふうな形で連絡をとっていただきたいと思います。ですから、この研究会、検討委員会の資料の中には、当然この地域性にふさわしい研究資料として、内容が上がってきております。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"さっき言った憲法、教育基本法に沿ったものかどうか、非核品川都市宣言でどうなのかという、幾つか具体的に聞いたんですけれども、その点についての視点はどうか尋ねました。","respondent":"青木指導課長","answer":"検討委員会も、そういう基本理念は変わりがありませんので、ご理解いただきたいと思います。","id":"exchange-028"},{"speaker":"桜井委員","kind":"質問","question":"どうして言及を避けるんでしょう、私は学習指導要領って聞いたことがないんだけれども。憲法、教育基本法に沿ったものでないんか尋ねました。","respondent":"青木指導課長","answer":"ですから、当然憲法や教育基本法や学習指導要領、それぞれのそういうものをクリアした形であそこに並んでいたわけです。ですから、それを選ぶわけですから、あの教科書はすべてそういう形でクリアしたものだというふうに考えておりますので。","id":"exchange-029"},{"speaker":"桜井委員","kind":"質問","question":"いいですか。そういうことの感想だけ申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問・要望","question":"６月１日にやれば、６月１０日ごろは公開できるのですか、ちょっと教えていただきたい。その時点で伺えば、また別に公表されるのか。","respondent":"青木指導課長","answer":"２点目ですが、終わったらすぐにですけれども、採択というのが８月の上旬に行われますので、採択まではこの内容が公開できない。それから３点目ですが、８月１５日以降はということですが、そうした手続があれば、こちらのほうでは公開するです。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問","question":"これから勉強するわけなんですけれども、こういう教育に関する問題というのは、密室政治みたいにそういう必要性があるのか、諸外国においてはどうなんか尋ねました。","respondent":"指田教育次長","answer":"最終的に今の予定では８月７日ごろ最終的に採択する予定ですので、そういうものについては、このように考えてあります。公明正大にやっていきたいというふうに。","id":"exchange-032"}]},{"id":"topic-02","title":"改めて行政視察","agenda":"改めて行政視察","exchanges":[{"speaker":"松澤委員","kind":"提案","question":"〔「じゃあ、１人１人意見を言わなくても、みんなの提案で」と呼ぶ者あり〕だから僕は２人でいいと思うんですよ。その中でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"松澤委員","kind":"意見","question":"できるだけ、こっちのほうで自主的にいろんなことをやっていくという、何時に集まってと言ったらそうやって早く行くというんじゃなくて、点呼なんかも自分たちでやってみんないれば、書記さん行こうよって引っ張っていくようなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"桜井委員","kind":"意見","question":"行ってどういう事実というところの記録は私のほうで原案をつくって、資料集めとかはもちろん書記に、ちょっとやっぱり資料集めはお願いいただけると。だから、もう少しいろいろ検討していけば、これでいいというのはなかなかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問","question":"ただ、評価の部分って難しいじゃないですか。どういう形でどうしたとして、どういう形という、私は事実でいいと思うんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"松澤委員","kind":"意見","question":"だから、その辺逆に、正副とかそういう議運とかの中で、報告書の一つのパターン化じゃないけれども、決めておかないと。〔「ガイドラインをつくる」と呼ぶ者あり〕何か決めておかないと大変だろうと思うねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"桜井委員","kind":"質問","question":"何かそこに時間を費やしてというよりも、むしろ行って、そこで学んだことというのは、１年間とか何年間にわたって、必ず生きるじゃないですか。だから、何か報告書に力を入れることには、私はちょっと疑問に思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"山路委員","kind":"意見","question":"そういうパターンとか、今言われた緊急のパターンとか考えますと、２人必要じゃないかというような感じですよね。それと、報告書は、記録をそれぞれ書いて、それをまとめるという形で主体的にやっていこうと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"川西委員","kind":"意見","question":"いろいろあるかもしれないけれども、１行や２行ならば、そんなに強力な意見にならなくてもいいんじゃないか。それをまとめるので書記はちょっと大変な思いもするかもしれないけれども、全部自分で書くよりは、ずっと内容があるものになるというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、行って、ものすごく有効だったと思っています。ですから、今言ったように当面はお二人必要かもしれないけれども、１人にすることもできていくんではないかなとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"松澤委員","kind":"意見","question":"２人より１人のほうがあれだけれども、やはり書記としては、１人じゃ大変だと思うね。議員を２泊するのを１人じゃねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"松澤委員","kind":"意見","question":"１人だったら、２人のほうが話し相手してくれるしね。１人遊んでいるんじゃないかというぐらいの状態に我々の意識が高まったら、それは１人でいいんだということになるけれども、当面は無理だねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"高星委員","kind":"質問・要望","question":"全部１人でやるということになるとかなり酷な仕事だろうというふうに、入れると後で支障があるんでしょうからしようがないからあれだけれども。それから、逆にこっちのほうから要望したいのは、書記の中で、この間、某議会事務局長と折衝した折に、１人しかいないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"高星委員","kind":"質問・要望","question":"その違いは明確なので、あったほうがいいかなと。どうしようもない、２人でも大変な仕事であるわけだから、従来どおり頑張っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"書記の負担、体の面の負担と同時に、宿泊費とかという負担の問題もあるんじゃないですか。ここの辺ももうちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/605950?Template=document&Id=4406#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":58207,"voices":152}},{"id":"h13-20010605-5","meetingId":"h13-cm06","date":"2001年6月5日","dateIso":"2001-06-05","committee":"総務委員会","time":"午後１時０６分～午後４時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井副委員長","kind":"意見","question":"副委員長の土井洋一です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"単純なのを一つお聞きしますけれども、企画部の２ページの数字なんです。広報広聴課が１７人となっているんだけれども、足し算の仕方を説明を求めました。","respondent":"山田広報広聴課長","answer":"失礼しました。広報と広聴それぞれ１名ということで、２に直していただいて１７名になりますので、よろしくお願いいたします。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"数字的には合うんだけれども、広報課と広聴課ということではなくて、広報広聴課の中の総括係長が１名ずつということなんですか、仕事を説明しながら……。","respondent":"山田広報広聴課長","answer":"いわゆる苦情等を含めて受ける窓口のところに総括係長が１名おりますので、そういった意味で総括係長が２名いるということで分けてあります。広報関係はそれぞれ担任主査制という形で広報紙のグループ、パブリシティのグループというような形をとっているです。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"３ページから４ページまで、職員の方々が区政、行政に対して企画を立てていくという場所ね。そういう区政とか行政、新しい事業、施策ということは企画課の仕事ではないんか尋ねました。","respondent":"市岡企画財政課長","answer":"このプランニングについては企画担当がいわば卵をかえすところまでやって組織を整備して、そこで実施をするという形があります。それは実施計画、個別の計画もまさに企画担当の仕事というふうに考えておりまして、かつ実際にやっていっているつもりです。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"区長１人なのかは別としても、こういうものはどうだろうとやってくるほうが多いと考えたほうがいいわけで、個別的な事業ということに関しては。教育委員会も含めてだけれども、そういう中の職員の方々が企画をされるというのか、そういうふうなことと考えていいんか尋ねました。","respondent":"市岡企画財政課長","answer":"事業部制の最大の特色の一つはそこにありまして、いわば企画機能がそれぞれの事業部の中にあると。我々のほうはむしろ企画財政課として各事業部の立ち上げをサポートしていくという組織体制を目指しています。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"全体の機器管理ではなくて、１台１台のパソコン自体の管理はどういうふうにされていくのかお考えになっているのかどうか。撤去命令を出すというのは、違反と断定を選管でしないと命令は出せないと思うんだけれども、その辺の選管としての役割を知らせていただきたい。","respondent":"田中情報システム課長、木下選挙管理委員会事務局長","answer":"うちのパスワードを入れない限りは、ほかからウィルス等が入ったフロッピーをパソコンに入れるというようなことがないようにしております。そういういろはのところを含めまして… 政治活動に関する問題で、この問題について言うと、警察と連携し悪質なケースがあれば選管として撤去命令を出す権限があるということです。それに従わなければ、当然警察としては一定の罰則の適用を行うです。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、違反したという判断は選管ではなくて警察当局という、この文章だと選管でやれるような意味合いにとってしまうんだけれども、そうじゃなくて違反という判断をくだすのは警察で、その判断に基づいて選管が動くというか、命令を出すというふうに考えればいいんか尋ねました。","respondent":"木下選挙管理委員会事務局長","answer":"今、委員がおっしゃったのが基本の流れだろうと考えています。要は警察とうまく連携をしながら、悪質なケースについて判断して、撤去命令につなげることができるです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、企画と各事業部がそれぞれ案件が出てきたときに会議をするという、個別にするというですか。それとも一挙にやっちゃうのか、それからどのぐらいの頻度でやっているのか、出てきたときの事業部の構成メンバーはどの辺までいっているのか。","respondent":"市岡企画財政課長","answer":"これは年間を通じた事業の調整ですので、それは年間を通じて行いますが、それ以外については案件が出てきた都度開催をするというものです。メンバーは当然四役と各事業部長、そして事務局が企画財政課ということになっております。","id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"財布のひももやりたいも両方一遍に判定しちゃうということのデメリットも必ずあるわけなんですけれども、その辺はどういうふうに考えているのか。もちろんメリットもあるんだろうけれども、改めてその辺をとの意見を述べました。","respondent":"市岡企画財政課長","answer":"４月以降ある行政課題があったときに、企画担当と財政担当が政策選択の検討と、こういう検討を両面から行う。企画と財政というのは、あるいは判断をしていけるというメリットのほうが生かせるのではないかと、そういうことで運営をしていきたいと考えています。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"改めてそこからチェックを入れるということのよさというのが必ずあるはずですから、お金のこととか仕事の手順みたいなことも度外視したような企画。もちろん、こういうことをやると、そういうことが生まれる可能性があるということだけを指摘しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"財政担当の方が積み上げたものに対して、行財政改革の観点から、そういう財政の組み立ては問題あるのではないかという指摘もなされていくものなのか。同じ課の中に執行する部分と改革をするということは、新設された課の役割を改めてお伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"端的に申し上げますと、新しい動きに対して新しい政策課題を２人の担当課長がそれぞれ専任で担当してもらおうという、機能強化のための担当課長です。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"新たに積み上げていくということの、いわゆる財政改革というよりは財政立案担当課というイメージでとらえていいのでしょうか、あえて改革を盛り込んだ意味合いが少し理解できない。","respondent":"市岡企画財政課長","answer":"具体的なプロセスでご説明します。切り口を変えて、こういうことで形にしていく、こんなようなイメージでご理解いただければよろしいかと思います。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"確認","question":"三つほど聞きたいんですけれども、今の件で確認したいんですけれども、ラインというのはどういうふうになっているのかよくわからない。企画部副参事だとか、それぞれスタッフの関係なのかなと思うんですけれども、その辺のラインとスタッフの関係をお願いします。","respondent":"市岡企画財政課長","answer":"この体制の図だけではわかりませんが、もう少し具体的にご説明しますと、企画財政課という一つのラインがあります。あるいは長期的な課題、それから先ほどの分権のような大きな仕組みそのものを変えるような課題に対応しにくいので、こういう形態を取っているです。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"質問は変わりますけれども、４ページの一番下の行政評価制度の実施の件なんですけれども、その前にもいろいろ話題になったところかなと思うんです。今までの説明ですと、そういう説明だったかなと理解していたんですけれども、このところをもうちょっとわかりやすくご説明ほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"二つのラインが分かれてありまして、実際には事務事業評価というのは事業を執行している行政側が最後まで責任を持ってずっと評価をしていく。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"政策評価、それぞれ具体的にどういう形で評価をしていくのか、もうちょっとわかりやすく説明していただればと思います。それと、またいろいろ微妙なことがあろうかと思うんですけれども、その辺のところはどんな感じか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"政策評価のほうなんですけれども、まだ中身については検討中でありまして、これからある程度検討が進む段階で明らかにしていきたいと思います。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"大体こういう方向だということが出てきたら、ぜひ教えていただければなと思いますので、ひとつよろしくお願いします。もう１点なんですけれども、選管のことで伺いたいんですけれども、一定規模の病院だとかで投票できるんか尋ねました。","respondent":"木下選挙管理委員会事務局長","answer":"３０カ所の病院を指定して、投票所として設置しております。この際に、選挙の期日から少なくとも５日前に、その投票所を告示しなければならないということになっております。","id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"病院での投票の秘密保持については、どうなんだろうかということで心配されている方からご意見を伺ったことがあるんですが、その辺については。","respondent":"木下選挙管理委員会事務局長","answer":"今、お尋ねのようなことが現実に行われているとすると、やはり選挙の適正な執行という点では問題があろうかと思います。そういうことがないとは思うんですけれども、その辺については私どものほうに情報提供していただければ、確認はさせていただきたいと考えています。","id":"exchange-017"},{"speaker":"北野委員","kind":"質問・要望","question":"区民の方に意見とかをお願いするわけですけれども、そのときに品川区が何を求めているのかという方針的なことが見えないという声をお伺いしたんです。そういうところについて、やはり具体的な意見を求めるほうがよろしいのではないかなと思いますけれども、この辺についてはお伺いしたいと思います。","respondent":"山田広報広聴課長","answer":"すぐ実施しますのは、現在行われている実施の状況のご説明をして、具体的な反映ができるということが１点あります。施設がどういう状況にあるかというのをご理解をしていただいた上に、その中から新たな提言という部分を期待して区政モニター制度を設けているです。","id":"exchange-018"},{"speaker":"北野委員","kind":"質問・要望","question":"自分が区政に出して、こういう形を求めているというものもあるけれども、ぜひその点についてはよろしくお願いしたいと思います。それから、都議選の看板が立っていますけれども、すごい単純な質問なんですけれどもわからないので教えていただきたいなと思います。","respondent":"木下選挙管理委員会事務局長","answer":"ポスター掲示板の中に何人分載せられるかという部分については、あれは決まりは特にございませんで、選挙管理委員会としてある程度つかんでいる情報をもとに、多少のゆとりを持って一応製作するということになっております。","id":"exchange-019"},{"speaker":"北野委員","kind":"質問","question":"ゆとりを持ってと言うんですけれども、今回１２名ということで、ゆとりはどのぐらいあるのかなと思ったので、あえてお伺いさせていただきました。","respondent":"木下選挙管理委員会事務局長","answer":"一応、法律上は掲示上については１２面になっておりますけれども、右側の説明欄も予備欄ということになっておりまして、実質的には１４面あるという制度になっております。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問","question":"広報広聴課の概要の中なんですが、広報しながわは、豊島区でコンビニで配布されるということで、この点をもう一度区としての見解をお願いします。","respondent":"山田広報広聴課長","answer":"大分前のときにもご指摘をいただいてありますけれども、コンビニについて、区の中で調べましたところ３００カ所ぐらいかなりの数があります。お願いをするとなれば、それなりの経費もかかってまいりますので、それも含めて総合的に判断してまいりたいというふうに考えてあります。","id":"exchange-021"},{"speaker":"中島委員","kind":"質問・要望","question":"駅はなかなか──若い方だったら駅でぽっと取るということも考えられるんですが、もう一度ご検討をいただけたらと思って発言させていただきました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど聞くのを忘れたんですけれども、選管のほうの３０カ所と言っておられたんですけれども、投票がそれぞれの施設でできると。例えば病院ですと、ベッドが幾つ以上とか、基準がどういうふうになっていましたか、改めて教えてくださいますか。","respondent":"木下選挙管理委員会事務局長、本多委員長","answer":"指定病院等になるのは、それぞれの施設の申請によりまして東京都で指定をするという形になってあります。各施設において、確か何ベッド以上という形の決まりはなかったというふうに思います。 ほかにないようでしたら、前段に関する質疑を終了いたします。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"２ページの、また数字のところで恐縮なんですけれども、さっきの企画のところと書き方が違うんですね。統一していただくと、どのぐらいの職員の方がどういう形の中でどういうふうに諸事業にあたっているというのが見えるんだけれども、いかがか尋ねました。","respondent":"太川総務課長","answer":"確かに、企画部と総務部と比較してみましたら、企画部のほうがよりきちっとしている、わかりやすいと思いました。企画のとおりにするかどうかは別ですけれども、全庁的に統一するように次回から徹底してまいりますので、よろしくお願いします。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"全体を見たときとか、そういうことでいいのかなと。それから、人事課長は秘書課長を兼ねるというのは、組織としてこれからずっとそういう形を取るのか尋ねました。","respondent":"中尾根企画部長","answer":"従来の人事課は人事課としてありますので、この事務事業概要では２ページ、これはずっと来年以降も引き続いてこういう組織でいくということです。組織のあり方とすれば、秘書は秘書、人事は人事として今後も必要だということで、継続して設置するという考え方です。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"７ページの秘書課の仕事でいくと、いわゆる秘書の仕事が、秘書課の仕事として書いていないんですね。これからどういう仕事をされるのか、まさかこれだけじゃないと思うので、その辺を説明していただきたい。","respondent":"古川秘書課長","answer":"本文の７ページの説明につきましては、いわゆる秘書業務がこの中に入っていないというご指摘です。これは事務分掌の１ページの中で、区長および助役の秘書に関すること、本文の中では特にこの部分については取り上げていなかったです。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"一番最後のページで、施設課に関することで、この表なんですけれども、これは１２年度のものを５月末までの数字でいくから書いてあるのか、右側の１３年度受任額というのは、１３年度分ということで考えればよろしいんですか、この表の説明をしてください。","respondent":"岡田施設課長","answer":"そういう意味では２９億３,０００万余になっていますけれども、最終的には結構数字が増えてくるという部分もあります。そういう意味で、５月１５日現在までの受任額がこの額だという表し方です。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、予算でもないし、実績でもないし、施設課にお話があったという言い方がいいかどうかわからないけれども、例えば今年の予算からいくと、１３年度予想額というのがあると思うんですが、そういうものはつかまないでいいんか尋ねました。","respondent":"岡田施設課長","answer":"１２年度の段階で予算は、工事費の予算の依頼を受けまして、そして大体のところを各所管に送ります。そういう意味で、今までもこのような表し方をしてございました。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"意見","question":"では、企画財政課にお尋ねしたほうがよさそうなので、１２年度の実績、これはもう既にこれだけ仕事をしたよと。１３年度の予算でいくと、ここに数字が企画財政課としては持っていると思うんですけれども、ここに数字を当てはまりませんかとの意見を述べました。","respondent":"市岡企画財政課長","answer":"おそらく７７億円程度だと思いますが、施工管理する工事として行われるか、この辺は少し今後の推移を見ないと決定的なことは言えないと思います。予測はその程度です。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"決定的に言ってくれなくても結構ですから、予測で予算というのを立てるわけじゃないですか。施設課のほうでもそれがあったほうが１年の見通しというのか、施設課で待っている、必要ないんか尋ねました。","respondent":"岡田施設課長","answer":"というのは、大体４月、５月ぐらいで大物というのは全部来ちゃうわけです。主だったものは４月、５月で把握しておりまして、つかみとしてはこれがメインという形で言い切れるのかなと考えています。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"予算額をここにいわゆる予算として入れてもらえれば、１年間こういう数字なんだなというのが見れると思ってお話しをさせていただきました。可能でなければ来年、また予算委員会や決算委員会でお願いするような形になるかと、そんな気持ちをくんでいただけないか尋ねました。","respondent":"中尾根企画部長","answer":"考え方は述べさせていただきたいんですが、実際どういう数字をどういうふうに載せるのかと、非常に難しい面がありました。考え方はそういうことです。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"同和対策のほうでお伺いしたいんですけれども、９ページの一番上のところに「各種研修会、研究集会に参加・学習」と書いてありますけれども、どういう研修会と研究集会があって、どのぐらいの参加をしているのかというのをお知らせほしいと求めました。","respondent":"阿部人権啓発課長","answer":"数なんですけれども、申し訳ございません。詳しくは持ってございませんけれども、全区大会のようなものも幾つかありますので、そういうものにも参加しているです。","id":"exchange-032","title":"議員研修会の内容と所要時間"},{"speaker":"宮崎委員","kind":"質問","question":"以前も１回質問したことがあるんですけれども、予算だったか決算だったか、そのときなかなか内容というのははっきりしなかったですね。こういう研修会、研究集会というのはここに何人とかというのを後で教えていただけますか。","respondent":"阿部人権啓発課長","answer":"各種研究集会の件ですけれども、その年の予算の状況によりまして参加人数が変わっていますので、すべての集会に参加しているということではございませんので、その辺はご理解をお願いします。","id":"exchange-033","title":"議員研修会の内容と所要時間"},{"speaker":"宮崎委員","kind":"質問","question":"昨年だったら昨年で結構ですから、そこのところは当然つかんでおられると思いますので、これは改めてお願いをしておきます。「同和行政の現状を把握するための視察研修」というのは、例えば、昨年は大体どの辺に行かれましたか。","respondent":"阿部人権啓発課長","answer":"主に、その部分については管理職が行ってありますけれども、去年は４区につきましては奈良に行きました。視察につきましては、徳島のほうに研修で行ってあります。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"毎回聞くと同じ地名が出てくるような気がするんですけれども、そういう意味では毎回行くところは同じみたいなことでいいかなと感じます。それから、3)で差別事象の処理となっておりますけれども、差別事象というのは大体昨年ですと、実質的には何件ぐらい発生しておりますかとの意見を述べました。","respondent":"阿部人権啓発課長","answer":"それにつきましては、去年はございません。ただ、例えば東京都でも就職の場合の身元調査とか、そういうものは現にあります。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"意見","question":"２名が１名になってもそのぐらいですとあまり影響がないのかなという感じがするんですけれども、実際にここのところは混乱とか起きておりますか。それと、昨年度の件数、大体いつも聞くと延べ件数なんですけれども、実質的な件数はわかりますかとの意見を述べました。","respondent":"阿部人権啓発課長","answer":"１名体制ですけれども、相談員の２人で十分やっていただいておりますので、影響ば少ないというふうに思っております。件数ですけれども、大体２４０件が実数だろうというふうに思っております。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"これも以前も実数かどうかということで聞いたことがあるんですけれども、そのときも実数でつかんでいないということだったんですけれども、実数ではつかまないんか尋ねました。","respondent":"阿部人権啓発課長","answer":"実数はつかんでおりません。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"例えば、こういう相談も、実態がどうなっているかというのをきちっとつかむということから始まってくるんじゃないのかなと思うんです。意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"ちょっと気になっていたところなんですが、３ページの区議会議員待遇者会というのがあります。会や事務を行う」とあるんですが、どういった内容のものが行われているのか、またそれがどのように区民の方に反映されているのか説明を求めました。","respondent":"太川総務課長","answer":"どういう反映があるのかですが、８年以上区議会議員をやられている方ですので、地域の中でもいろいろな係わりが多いと思います。そういう中で、日常いろいろやられる部分で、この研修を通してフィードバックされていくと、そのように考えております。","id":"exchange-039"},{"speaker":"中島委員","kind":"質問・要望","question":"できれば先輩議員の方たちですので、いろんなご意見が出ると思うんですが、そういう会の中で出たご意見を、私たちにそれを何らかの形でお知らせいただければ参考になるのではないかなと思いますので、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040","title":"議員研修会の内容と所要時間"},{"speaker":"北野委員","kind":"質問","question":"「きんだぁくらぶ」と「とどらぁるうむ」なんですけれども、この保育料というのは保育園と同じなんか尋ねました。","respondent":"太川総務課長","answer":"「きんだぁくらぶ」は７園実施していますけれども、非常にきめ細かく、そういう中でいろいろとバリエーションをもって金額が出され決めてあります。そのほかミルク代、おやつ代等を含むということでなっております。","id":"exchange-041"},{"speaker":"北野委員","kind":"質問","question":"私も実際に調べていないので、高いのか安いのかという判断が難しいんですけれども、幼稚園だったら幼稚園のサービスというのがあるんだと思うんです。それによって決められているのかなとは思うんですけれども、幼稚園独自で決めているということなので、その点についてはどうなんか尋ねました。","respondent":"太川総務課長","answer":"ご説明が若干足りなかったんですけれども、例えば「とどらぁるうむ」につきましては、基本的に区の未認可の保育所と同じ基準の中でやってあります。","id":"exchange-042"},{"speaker":"北野委員","kind":"質問","question":"区の職員の方というのは、基本は給与は振り込みですね。振り込みでない方はいらっしゃるんか尋ねました。","respondent":"古川人事課長","answer":"昭和６０年に一定の必要性がありまして、これは本人の意思を確認した上でということで、給与振込制度を実施しています。現時点で１００％ではない部分は若干ありますけれども、この部分については１００％を目指していくと、このように考えております。","id":"exchange-043"},{"speaker":"中島委員","kind":"質問","question":"不在者投票の件なんですけれども、不在者投票をする理由を書く用紙をインターネットで聞けるというのを伺ったんですが、それはあるんか尋ねました。","respondent":"山田広報広聴課長","answer":"インターネットのホームページで今回都議選が始まるということで、ホームページに都議選が始まりますというお知らせと同時に、電子申請の申請用紙を請求すれば取り寄せるようにということで、それも今回選管と打ち合わせをいたしまして、出せるように手はずをしているです。","id":"exchange-044"},{"speaker":"中島委員","kind":"質問","question":"そこからプリンターするということではないんですか、プリントアップできるんですか。そこにバーコードがあると伺ったんですが、そういうものがついているんか尋ねました。","respondent":"木下選挙管理委員会事務局長","answer":"インターネットでプリントアウトして行う場合については、バーコードで計算することはできないということになります。これは私どものほうの集計上の問題です。","id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"二つの選挙がある場合、２枚一緒に投票券を渡されてしまうと、どっちがどっちだかわからないという年配の方からよく言われるんです。分けて出してもらえないかということがあるんですが、それは今回も同じやり方か尋ねました。","respondent":"木下選挙管理委員会事務局長","answer":"そのときに担当からきちんと説明をしていますので、私どものほうでもご案内をしますので、よろしくお願いしたいと思います。","id":"exchange-046"},{"speaker":"中島委員","kind":"意見","question":"その際、不在者投票に行ったとき、候補者の名前がきちっと出ていない場合があって、とても迷うと言われたんですね。最初のほうは登録をするとか、ある一定期間が過ぎれば、あそこに掲示されてもいいのではないかという声もあるんですがとの意見を述べました。","respondent":"木下選挙管理委員会事務局長","answer":"告示日５時まで受付けですので、今度は並べる順番のくじを６時からやりまして、それをそろえることは物理的に無理なわけです。ですから、なるべく速やかに張る努力はいたしますけれども、現実的には難しい、つまり告示日は難しいということでご理解をいただきたいと思います。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"任期切れから逆上って、いついつまでに決めなければいけないとか、そういう決まりがあるんですか。いつが選挙という、最終的にいつ決まるというのは見通しというか、法的に何かないんか尋ねました。","respondent":"木下選挙管理委員会事務局長","answer":"でも、それはすごく我々としては不安なので、できれば６月２０日ぐらいまでには決めてほしいなということはあります。そういうことは東京都に言ってあるわけですけれども、一応そういうような状況にあるです。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"意見","question":"一つは、この時期ちょうど各地域で地区まつりが、夏休みに入って８月の１週目ぐらいにあって、地域センターをいろいろ利用というか必要なんです。わからない中でもこうして資料を出せるから、それを対応してくれますか、してほしいとの意見を述べました。","respondent":"木下選挙管理委員会事務局長","answer":"そういう中で、地区まつりも７月２９日だったものが１週前になったり、現実にはそういう対応をしていただいている地区もあります。","id":"exchange-049"},{"speaker":"土井副委員長","kind":"意見","question":"一応即日開票になったということの中で、開票事務、投票事務等々に係わる数の問題と、それから職員だけで全部できるというわけにいかないだろうと思いますから、どんな形で人の確保の部分がされるようになっているのか、何人ぐらい確保する予定になっているのかを聞かせてくださいとの意見を述べました。","respondent":"木下選挙管理委員会事務局長","answer":"大量に職員を必要とする部分について、なるべくその日のうちにあげるためには、なるべくたくさん動員しなければ難しいということです。一応、アルバイトも含めて６３９人の体制でいきたいというふうに考えております。","id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ぜひ、正副委員長で日取り等も調整してやっていただきたい。今、委員長が説明されたとおりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"提案","question":"聞くところによると減らすような提案もされているということなんですけれども、そういうことなのかどうなのか確認したいということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"本多委員長","kind":"質問・要望","question":"従来の２名から１名にということで、その方向性で進もうということで、まずこちらは最大で１名ということを考えていただければと考えています。報告書につきましては、その辺についても各委員のご意見をいただきたいと思いまして、今日は皆さんに聴取をさせていただいているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"塚本委員","kind":"提案","question":"宮崎委員から一律でどうかという話ですけれども、まだまだそれぞれ独自にいろんな取り組みをして、まだそういう段階ではないかと私は認識いたします。そういう提案をなさったんでしょうけれども、その段階ではないというふうに、私たちは判断しておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"提案","question":"私も随行書記を減らすという提案があったというのは、私もかなりお願いしていたのがあったものですから、その辺が不安になります。もう一つ、報告書なんですけれども、実は去年報告書の書き方はどういうふうにすべきかとか、かなり議論したんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"林（宏）委員","kind":"提案","question":"自治体の基本理念みたいなものを伺いながらやられているソフト的なものを視察するということなので、一つの提案としては同じことをＡ市、Ｂ市。ですから、できるだ議員それぞれが汗をかくという部分を多くしていかなきゃいけないのかなというふうに思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"田中委員","kind":"意見","question":"そうすると内容を充実に向けての対応がどうなのかということもありますので、さらに内容を充実を図っていけたらなと思います。なるべく早い時期に視察をしたほうが、より議会活動に活用できるんじゃないかなという、これは意見として述べておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"土井副委員長","kind":"確認","question":"この問題はどうなったのか、なるのかというところを確認をしておかないといけない部分じゃないかと思うんです。それが今まで旅費の関係があるものですから、別なホテルに泊まらなければいけないとかといういろんな問題等々があったというようなことですから。","respondent":"福田区議会事務局長","answer":"旅費でありますけれども、分けて考えますと、例えば鉄道賃と言われているものにつきましては、実費です。このような運用上の問題で何とか解決することができるだろうと考えていますので、昨年のような問題点は発生しないだろうというふうに思っております。","id":"exchange-058"},{"speaker":"土井副委員長","kind":"確認","question":"その運用ができれば、少なくとも我々と同じホテルの屋根の下にいるほうが安全確認、確保等のためにはやりいいという話になります。ですから、本年は少なくとも同様に２人にしていただくような形で運用して、その実績を見ると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"その前に教えてほしいんですけれども、中でも総務委員会が先行して事例を開いたという経過があるんですが、８月末でしたね。今６月の頭で、その辺のことをちょっと教えていただければ、「実際に大変だったよ」とか……。","respondent":"中尾根企画部長","answer":"むしろ、実際上国民の皆さんがちょうどいろんな行くときにあたるほうが、むしろ大変です。そのところについては何とかできるのではないかと、あんまり参考になるかどうかわかりませんが、そのようなことです。","id":"exchange-060"},{"speaker":"林（宏）委員","kind":"意見","question":"８月に行ったんですけれども、やっぱり今言われた夏休み中であるというのが一つ心配で、意外に大丈夫だったということ。時期についてはこちらがきちんとした誠意を持った視察をすれば、とにかくこっちの視察の姿勢をきちんとしておくということじゃないのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"土井副委員長","kind":"質問","question":"自由な発想で意見を言い合う場のようですから、そんな形でちょっと言います。後でもよかったら皆さんとあまりかけ離れていないところでやればいいということになるわけですから、これがまず大事だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"田中委員","kind":"意見","question":"北海道の中で札幌市と拓銀との関係が、ものすごく密接なつながりがあったんじゃないかなと、推測なんですけれども。そういうものがつかんでこれるんじゃないかなと、まだ漠然としている段階ですけれども、今私自身はその二つを思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"そういう質問があったので、去年も多治見市に行かれているということだったので、どうかなと思っていますけれども。そういうお話もあったので、去年もやったんですけれども同じ場所じゃないですけれども、行政評価もあるかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"塚本委員","kind":"意見","question":"それから、やっぱり自立性に欠ける自治体が多いという〔「失礼だよ」「問題発言だ」と呼ぶ者あり〕ふうに私は思います。そういう意味からも、違った意味での参考になるんでしょうけれども、もっと積極的なやつを見るべきではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"林（宏）委員","kind":"質問","question":"どのぐらいこういう状況でいくのかわかりませんけれども、まだ中途採用というのは公務員はなかなか難しい段階ですから、これからなんだろうけれども。去年も競馬は若松がどうしようもなくならない寸前のところへ行ったんだけれども、内容的にはそんなようなことが視察できればなという気がします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/517525?Template=document&Id=1548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":53514,"voices":192}},{"id":"h13-20010606-13","meetingId":"h13-cm06","date":"2001年6月6日","dateIso":"2001-06-06","committee":"清掃・リサイクル特別委員会","time":"午後１時１４分～午後４時３４分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）副委員長","kind":"意見","question":"よろしくどうぞ。身近な問題ですので、１年間有意義な委員会になるように、委員長の補佐をできるように頑張ってまいりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"土井委員","kind":"意見","question":"民主党区民連合の土井洋一です。よろしくどうぞお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"日本共産党の南です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"中央防波堤が満タンになってしまったらどうするのかということが１点と、ごみの量と景気が比例するということをお伺いしていて、その後の。その対策ですね、この３点についてお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"いろいろ現状の埋立処分場の後の検討に具体的に入っておりますけれども、極端に言えば、その数十年あるいはそれがもっと予定よりも長くもたせる中で。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"このままの状態でいけば、わかればでいいんですけれども、何十年ぐらいもつんでしょうか。３０年、５０年だったら、すごく考えさせられるんですけれども。","respondent":"野本環境清掃事業部長","answer":"いわゆる焼却灰をセメント材料をつくるための材料に使いますよということで、焼却灰を埋立地に持っていかないというようなことも考えられています。事務所で一番問題になっているのは、むしろ大きな視点では問題なのかなというふうに考えております。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"それをどこがやるんですかということを民間のペイするかどうかわからないのに、民間は続けて研究なんかしませんから、学術的なものは別としてね。何か聞くところによると、少しずつここら辺には何が埋まっているらしいよというのは少しなっているようですから、掘り返すと言ってはおかしいけども。","respondent":"中山清掃リサイクル課長、野本環境清掃事業部長","answer":"後ほど東京二十三区清掃一部事務組合との役割等のご説明をする予定でおりましたんですけども、まず、収集運搬に関しては各特別区がやっていると。後ほどもまた、一部事務組合の説明で申し上げるつもりでおりましたけど… どう対応するかは、そちらのほうに一時的にはどう考えるかが、主体的にそちらが考えるような形にならざるを得ないのかなという気がします。非常に明確な答えにならずに申し訳ないんですけれども、以上です。","id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"やっていかなきゃならんということがあるんだということを、我々やっぱり意識していかなきゃいかんだろうなと思います。感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"どういう効果をその後まとめられたのかなというのをちょっと伺いたかったのが一つと、それも３カ月のモデル実施なんでしょうか、そこのあたりをまず伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"５月の清掃リサイクル特別委員会で１２年度の実績の部分についてご説明をしたところですけれども、住民の協力の度合いは非常に高かった。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"２倍までは行きませんけれども……２倍ぐらいなのか、3,８９５キロが7,７４７キロですから、２倍ぐらいになるんでしょうかね。小さなペットボトル５００ミリとか、どういうふうに区としては受けとめていらっしゃるのか、この数字の見方を伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"認識ですけども、生産量の増から見ると、行政回収して資源化している量の増が正直言って追いついていないという認識があります。逆にこれが今後の大きな検討課題と先ほど申し上げたんですけども、膨大な、これは課題といいながらも。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ちょっとその辺、改めて伺います。量が、一遍に全部グッと１台のトラックで積むわけじゃないわけですから、非常にコストが高いというところは非常に問題だと私も思うんですよね。","respondent":"中山清掃リサイクル課長","answer":"今年度の実施につきましても、より一層意見を十分把握しながら、フィードバックについても心掛けていきたいと考えています。","id":"exchange-010"},{"speaker":"北野委員","kind":"質問・要望","question":"私も確認したらば、町会のほうでは継続して紙パックのリサイクルを進めていきたいという話を伺ったんですけど、そういうのはあるんでしょうか。すみません、ここで確認させていただいていいか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"この考え方は区においても同様ですという説明は当委員会でも差し上げました。基本的にはライフスタイルの変更あるいは意識づけというところになりますので、少し地道な部分を周知していくような流れになっております。","id":"exchange-011"},{"speaker":"北野委員","kind":"質問・要望","question":"それが一歩進んだ形で同じようなやり方をされていくのかどうか、後で報告があるのかわからないんですが、お伺いしたい。それから、それはどういうふうな形で配布されたのか、ちょっとお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"やはり透明のビニール袋というものが中の異物の確認だとか、そういったものを含めてやりやすいということで、これは同じやり方でやる予定です。１００袋程度、１００キロ分ぐらいをお配りしたかと考えています。","id":"exchange-012"},{"speaker":"北野委員","kind":"質問・要望","question":"それが、区の中に広がっていくことによって、リサイクルの部分でも効果が出ると思いますので、よろしくお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須藤委員","kind":"提案","question":"祝日がこうだったということのないようにお願いしたいなという確認と、５２ページ、モデル地区ができてやっています。１２０人という数的なものは絶対必要な状況になっているのか、考えられるかというようなことがどういうふうに考えていらっしゃるか、その点をとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"考え方として、事業者も生産者責任を果たしていくという考え方は、同一に認識しています。今年度もそうでありますけども、昨年同様に、工夫できるものをやっていきたいと考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成８年から１２年度のあたりまで見ると、平成１３年度はどういう目標でごみを減らしていくのか、お聞かせほしいと求めました。どうなのかなというふうに思いながら来たんですけど、どう対処できるのか、どう考えたらいいのかということについてお聞かせほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"１点目の生ごみ再資源化モデル事業における実績、予算が２５０万円でございまして、これは１００％国の補助ということで実施したものです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一番初めにお聞きした雇用対策というところでは、２５０万円、そういうものではないということなんですね。はい、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"「４区の公共下水道普及率は平成７年度からほぼ１００％に達しているが」と、どうなんですか、この辺の権利関係を含めた状況は。そこのところを確認させてください。","respondent":"中山清掃リサイクル課長","answer":"紙パック、アルミ缶の2,０００円というものは、途中から設置された考え方だというふうに認識しております。どうしてもそのために１台の車を持っていかなきゃいけないという意味では、これは建物の自然な更新を見ていかないといけないのかなと考えています。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"そうすると、要するに学校の３３校、小学校の２４校、中学校の９校については、生ごみ処理器の配置は今後どう、全然考えていないんですか。ここで言う３３校については、生ごみ処理器の配置は考えていないということで、今後ともこういう形で進めていくんですか、その辺のところね。","respondent":"中山清掃リサイクル課長","answer":"まとめて集めた後に機械式で堆肥化するのかという違いですけれども、この学校数については機械の設置は逆に言うと、新たにできないです。","id":"exchange-018"},{"speaker":"中島委員","kind":"質問・要望","question":"まちの美化推進委員などの点について。現在区内における不法投棄、どういった種類のものが、どういう形で投棄されているのか教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"ちょっとお答えにはありませんけども、一点相関関係があると考えていますけども、ちょっと申し訳ございません。むしろ数的には多いかと認識しております。","id":"exchange-019"},{"speaker":"中島委員","kind":"質問","question":"それから、かなり私も議会に来るようになって２年余りになるわけですけど、そのころからずっとあそこは常にごみが散乱しているという状況なんですね。あそこに対して、区としては何か対策をとっているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"なかなか根本的な対応ができないという悩みもありますけども、分散してまとめてごみを出す場所をなくしてしまうというふうなこともやってあります。なかなか完全に対応できませんけども、再度また管轄清掃事務所とも連携をとりながら、研究していきたいと思います。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"ですから、やはり、ああいうふうにほかにないほど極端なあそこは場所だと思うんですね。大きく係わる、そういう対策をとっていただきたいと、このように要望しておきます。","respondent":"後藤荏原清掃事務所長","answer":"いろいろ手をかえ、品をかえやってきたところなんですけども、やはりなかなか改善というところまでは至っておらないのが現状です。やはりそういう強力な対応を必要とするというふうなところにつきましては、また、何とか解決できる手を考えていきたいと考えています。","id":"exchange-021"},{"speaker":"中島委員","kind":"質問・要望","question":"それがはっきり投棄した人がわかった場合にどうなるのかといった点を区民の方にもお伝えしていただきたいなと思うんですが、その点、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"しょっちゅうやるわけにはいかないかと思いますが、目に余る例があれば、例えばそういったものを写真入りでこういったことになっていますというきつい調子での広報というものも考えていきたいと思ってはおります。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点だけ。４３ページの事業用の大規模建築物に対して排出指導のところをお伺いしたいんですが、問題点というんですか、ぜひお聞かせてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"一遍にすべてはできませんけども、場合によっては紹介をするであるとか、そういったアドバイスをしています。氏名を公表したりというふうな手だてもとれるようになっておりますけど、基本的には協力、相談に乗りながらの指導をしていくということです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"専門班というお言葉が聞かれたので、両清掃事務所で何人ぐらいの方がこれに当たっていらっしゃるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"ふれあい指導というふうに東京都時代から呼んでいるんですけど、両清掃事務所、それぞれ８名の体制になっております。ですから、この事業だけの人数ということではございません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これからだとは思いますけど、特に発生抑制のところなど、力を入れてご指導いただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"５２ページの家庭用生ごみ処理器というんですか、前に意識を持っている方ですから、この辺はどうなっているのか。前もちょっとお聞きしたんですが、低公害車はどのぐらいの台数ですか、区として。","respondent":"中山清掃リサイクル課長","answer":"こういったものもございまして、いろいろ雇い上げの業者のほうもかなり環境に配慮した車を確保しなければいけないという認識は持っております。","id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"それも大体同じようなバランスということですか。予算がかかるから、簡単には言えないと思うんだけど、ちょっとその辺を要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問","question":"平成１８年の３月を目途にこれを解散をすると、そっちのほうに、横を向いているところとがどうもあるということだったと思うんですよ。そして今、やっぱり、状況を目指しての作業にほんとうになっているのかというところについてはいかがなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"この点についての各区の認識、現実の検討というのは、実際に検討の段階に入っているのが今年度になってからです。どういう地域処理の体制が望ましいのかというのがまさに検討の緒についたところですので、地域処理に向けての課題の洗い出しに入っているところです。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問・要望","question":"私どもが、まさしくこの委員会がそれを出さなきゃいけないところなものですから、いろいろと情報を聞かせていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"簡単にちょっと伺いたいと思います。改めて、成分的には全く１００％純粋なものというふうにとらえていいんでしょうか、よくわからないんで教えていただきたいなというふうに思います。","respondent":"中山清掃リサイクル課長","answer":"今現在の予定としては、平成１４年１２月を目途に現在の工場を停止して、具体的な建て替えの工事に入ると。いわゆる条例に基づく環境アセスメントの手続には既に入ってございまして、住民説明会あるいは説明会後の公聴会等も改正されたです。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"４月だったかしら、聞いたものですから、公聴会も含めて教えていただきたいというふうに思います。ですから、その辺の意見を東京都なりに、あるいは必要なところに上げていただける用意があるかどうかをちょっと伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"大井工場のプラント更新の住民説明会につきましては、それから２６日に日産スポーツプラザ東品川でということで、２回開かれました。今の工場よりもはるかに排ガスへ配慮したものに建て替えていくんですよという説明を東京二十三区清掃一部事務組合のほうがしておったところです。","id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"私も、あったという話を聞いたものですから、改めてちょっと確認をしたいと思って伺ったところです。ほんとうに大丈夫なのかどうかを、ちょっとそのあたりの確認だけでいいんですけれども、お願いしたいと思います。","respondent":"金井環境課長、中山清掃リサイクル課長","answer":"説明会の開催もまたされるという形になってまいります。さらにそうした説明会の開催、審査意見書の作成をされまして、評価書の作成という形になります。 先ほど申し上げた区と東京二十三区清掃一部事務組合との連絡会議との場面でも、臭素系ダイオキシンへの影響あるいは対策ということについては確認していきたいと思います。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"今の答弁で、確認していただくということなんで、改めてよろしくお願いしたいというふうに思います。ダイオキシンというのは猛毒ですし、それから、必要な意見も区のほうからもぜひ上げていただきたいということをちょっと強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"須藤委員","kind":"質問","question":"だから、ダイオキシン対策でそんなことをやるんだよということを最初にきちんと言えば質問にはあがらないんだよ。三菱だかどこかへ、いわゆる大井なり何なりというところで上がってきた電力を全部そういう形にしますよというシステムをつくり上げてきたんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"したがって、これは東京電力の提供先が売電している工場について、基本的にはそこに売却するという契約になるかと思います。したがって、売電している工場がすべてそれにかかってくるんではというふうに認識しています。","id":"exchange-034"},{"speaker":"須藤委員","kind":"質問・要望","question":"大井工場とか幾つの工場が、どの程度そういうシステムで行っているのか、ちょっと見ておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"２６ページ以降に売電が出ているんですけど、売電収入額３２億円と出ているんですが、これはどこへ入ってくるのかがわからなかったので。ちょっと自分もそれをお聞きしようと思ったんで、そこだけ説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"これは東京二十三区清掃一部事務組合の歳入として歳入されるものです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"伺いますが、モデル実施予定地区の南品川二・三丁目、あと二葉二丁目と、何でここに決まったのか。","respondent":"中山清掃リサイクル課長","answer":"とはいえ、約3,０００世帯ぐらいが実験検証のエリアになるのかなというところで、今後の検証にならないということが一つございました。適度に収集車が回り、なおかつ路地も一定あるというふうな、ある種標準的な場所を世帯で選んだです。","id":"exchange-037"},{"speaker":"北野委員","kind":"質問","question":"それは同じ内容ですか。まるっきり同じやり方をしていくのか、北品川地区とか八潮地区の検証の上に立って、先ほども伺ったように進めていくんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"平成１２年度に実施した生ごみの再資源化モデル事業というものと、それで、一定世帯で行うというものとは別の地域です。住民説明につきましては、戸別の説明に当たりたいというふうに思っております。","id":"exchange-038"},{"speaker":"北野委員","kind":"質問","question":"そういうところは、前進した考え方というのはあるんですか。その点についてもう一回お伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"他の区で何かで取り組んでいる高齢者や障害者への戸別の収集というものも、区としても検討しております。前者の高齢者等への収集については、別の施策として検討していますので、品川なりの工夫をして実施はしたいというふうに考えているところです。","id":"exchange-039"},{"speaker":"北野委員","kind":"質問・要望","question":"前にお伺いしたようなことと同じなんですけども、やはり、こういうときにごみ減量推進委員の方とかが協力をしながらとか、また、ひとつのなんというか地域に影響が分かれるんじゃないかと思いますので、そういうところも検討の余地に入れていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"中島委員","kind":"質問","question":"たまたま今わかって、私はちょうど二葉二丁目地区で、うれしいとかというのはあれですが、これは例えばアパートなんかだと、そこのうちで１軒という形をとるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"基本的には建物単位ですので、アパートの中までとりに行くことは現実に不可能ですので、そういうことはいたしません。建物ごとに収集をするという考えです。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"そうした場合は、容器なんかは、そのアパートによっては、世帯数の多いところとか、少ないところとかあると思うのですが、容器は、区のほうで用意するんですか、それとも、自分で用意するんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"基本的に容器収集ということではなく、戸別にとれないかということの検証ですので、逆に袋出しが基本になるというふうに考えてあります。その期間、その袋で期間中お出しくださいということを袋を持って各戸に説明しながらお願いに参りたいというふうに考えております。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"わかりました。ちょうどいいチャンスだと思いますので、いろんな角度から見させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の周知なんですが、いつごろから、９月実施でしたけど、いつごろから周知していくんでしょうか。その辺を説明を求めました。","respondent":"中山清掃リサイクル課長、山口品川清掃事務所長、後藤荏原清掃事務所長","answer":"まだ、町会長等を含めて地域の人には全くこの件はご説明してございません。きょうの委員会がご説明を差し上げる最初の場面ですので… 前のところはこういう形で３カ月間モデルで実施します、この辺の説明も対岸のほうの、通りを隔てた反対側のほうの住民の説明にも入りたいと。荏原清掃事務所、今ご説明いたしましたとおり、二葉二丁目のほうで、このモデル事業を行いたいと考えています。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年で２年目ですけれども、さらに区民の皆さんの意識改革を進めるということで、ぜひテーマの話し合いの時間を持ってほしいと求めました。視察にもぜひ行かせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"須藤委員","kind":"意見","question":"そういう考え方なんだというものをベースにしていくと、また、向こうでの発言というような考え方を持っていきやすいと思うんですね。品川区委員会としてはどういう方向性をつくれるのかというのを１年間やって、後で整理の上、参考にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"ごっそりご協力をいただいて、機械化してやっているところが結構あるみたいなんですよね、いろいろ見てみると。ですから、お届けしたいと思っていますので、検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/301337?Template=document&Id=5640#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":61128,"voices":145}},{"id":"h13-20010606-16","meetingId":"h13-cm06","date":"2001年6月6日","dateIso":"2001-06-06","committee":"街づくり特別委員会","time":"午後 １時０４分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路副委員長","kind":"意見","question":"同じく副委員長の公明党の山路良成です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"６１ページの大崎駅東口第３地区の金陽社とかの工事ですね。たしか、三井建設が入っていたと思うんですけれども、その辺の経過を詳しく聞いていなかったものですからお聞かせほしいと求めました。","respondent":"南雲都市開発課長","answer":"大崎駅東口第３地区の状況についてご説明させていただきたいと思います。６１ページの下の表にありますように、平成１４年５月の都市計画決定を目指しまして、計画の見直し作業を行っているという状況です。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"まだ都市計画決定前だから、保留床がどのぐらいあるかとか、大林組、日本舗道がどのぐらい割合を持つとか、そのようなものは決まっていないですか、決まっていたら教えてもらいたいと思うんですけれども。","respondent":"南雲都市開発課長","answer":"大きな考え方としましては、この地区の場合は業務棟１棟、住宅棟２棟ということを計画しております。保留床分については全部大林組が取得するという計画でして、住宅棟２棟のうち１棟については都市基盤整備公団が取得する予定になっております。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"再開発事業で第１地区、Ｄ１地区と幾つかあるんですけれども、その後の動きはどういうなっているのか。一本橋地区も平成４年に一本橋周辺２地区整備構想までなって、その後どうなっているのか、その後の経過をお聞かせてくださいとの意見を述べました。","respondent":"南雲都市開発課長","answer":"この土地については臨海高速鉄道としては、将来にわたって所有はできないということで、何らかの開発を考えているです。一本橋地区ですが、地元では特に面開発による開発は希望はないということで、ここについては特に現在動きはない状況です。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、計画が途中で途切れているんですけれども、そういうことであれば白黒はっきりさせる時期じゃないのかなと思うんです。Ｄ２地区も、そういうところは白黒はっきりさせないで、途中経過の形でなっているというのは何か意味がありますかとの意見を述べました。","respondent":"南雲都市開発課長","answer":"経済の動向も変動して推移するということで、一時活動が止まっていたものが情勢の変化によりまして、また動き出すということもあります。再度区としても支援していこうということで、休会状態といいますか、もう少し状況を見守るというのが状況になっております。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問・要望","question":"それから、品川区でどういうふうに関与しているのか、準備組合の会等の連絡会が、１３９号線の道路の問題でありますね。それらも含めて、どういうふうに関与しているのか、もう１回聞かせていただきたい。","respondent":"南雲都市開発課長","answer":"現在の予定としましては、一番奥にあります西口中地区の整備計画を定めるという都市計画の決定を考えております。３番目が西口南地区、最後がソニー地区というような順番で段階的に整備をしていくという予定になっております。","id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"４地区総合整備計画を検討している間に、どんなものをどういうふうにしたいとかという話は出ているんですか、伺います。４地区総合的な中でどのぐらいの規模のものが交通広場あるいは公園なのかということは、都市計画決定の検討段階で具体的に出ていますね。","respondent":"南雲都市開発課長","answer":"現状では、明電舎地区につきましては、業務を中心に一部商業、住宅ということで、総合的な機能の開発を明電舎としては考えているです。現在東京都と協議をしておりまして、最終的に何平米というのは協議をしておりまして、それが決まりますと正式に容積が決まってくるです。","id":"exchange-007"},{"speaker":"川西委員","kind":"意見","question":"こういう駅前開発のときに、必ず商業施設の規模等も検討されていると思うんですが、ニューシティだとかというものの兼ね合いの中では、どんな協議がされていますか、西口のほうの商業スペースについてとの意見を述べました。","respondent":"南雲都市開発課長","answer":"この地区については道路の地盤が弱いということで、地元ほうでも考えておりませんし、行政としても望ましいことであるとは考えておりません。この地区内で働いている人、規模としてもそう大きくないということで、大規模なキーテナントを演出するようなことは考えておりません。","id":"exchange-008"},{"speaker":"川西委員","kind":"意見","question":"２６号線が一部開通されたり、大井町がどうなっていくんだろうかと、大井町については微妙に住民の中にあるんです。そういう点で、夢のように期待されるこの構想について、一番よくわかっている方が説明をしてくださいとの意見を述べました。","respondent":"南雲都市開発課長","answer":"ただ、行政として構想を持っているということは重要なことであると思います。将来に向けてこの地区についても将来構想として持っているということで、何かあったときにすぐに対応できるのではないかというふうに考えております。","id":"exchange-009"},{"speaker":"川西委員","kind":"質問","question":"昭和６２年以後、こっちはレジャー施設みたいな感じもするんだけれども、これは説明できますか。載せたからには聞かれたら困るじゃないですか、そうでなければ載せないほうがいいと思うんです。","respondent":"南雲都市開発課長、中谷まちづくり事業部長","answer":"これについては基本的には公園などのオープンスペースを見出したいということを表した図面であるというふうにご理解いただきたいと思います。一応図面を載せておりますが… 都市開発課長が申しましたとおり、オープンスペースは一定程度確保しようという考えは、絵を見てもおわかりだと思います。","id":"exchange-010"},{"speaker":"川西委員","kind":"質問・要望","question":"それをどういうふうにしていくかということが、やはりこれから少し力を入れて検討していただきたい。あるいはさまざまな生活層の人が利用するということになると、中心として考えるときの検討材料になってもいいんじゃないかというのは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"どんどん情報をいただいて、当委員会ではどうしていこうかという、区の理事者に意見を与えられるような……。一つの特別委員会ですから、運動体として我々どこで運動できるのかなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"本田委員","kind":"質問","question":"個別になぞっているだけにしか取れなかったものものですから、品川区民にとって、その辺のお話が報告の中では全然入っていなかったものですから。その辺は今後の委員会の中でやらせていただけるのか、何か議題に上げていただけるのか、あわせてお尋ねしたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問・要望","question":"品川区に経済効果がどういうふうに来たのか、そういうような計画時点とは違って実績もつくってきているわけですから、お話を聞きたいなと思うんです。今日、細かくは答弁は無理だと思いますので、今後の進め方の中で、できればそういうものも出していただきたいなと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"上山委員","kind":"質問","question":"川西委員から質問が出ていたところなんですが、特に５７ページの地図で、その辺はどうなんでしょうか。補助１６３号も含めて開発などに伴って、当初の計画からしても大丈夫なのかなと思うんですが、その辺はどんな感じなんか尋ねました。","respondent":"南雲都市開発課長","answer":"この地区では特にソニーは自社の研究開発部門などを中心になるという開発を予定しているということで、発生集中の台数が少ないということがあります。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"ですから、その辺の全体像の中で、この委員会の意見が行政に伝わって、行政がそこに言っていればいいんだけれども、そういう場じゃないよね。ぽんと絵ができてきちゃうわけですから、そこに議会としての、また我々が言ったことが向こうに伝わるという道がないわけだよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"容積率で１００％使えない、そういうことを一つひとつ議題として何が今そこに求められているのか、そうすれば促進ができるのか。そういうところをどうやって考えるかという議論を突き詰めていくことによって、そういう議論を詰める委員会にしていったほうが私はいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"築舘委員","kind":"質問","question":"ですから、両面ちょうどいい題材が出てきたんじゃないかなと思うんです。我々はそれを参考にしながら、ただそれは抽象的な部分が書かれているものですから、我々の意見を反映できるんじゃないかというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"ですから、まだ報告するほどでもないということもありまして、そういう目がまた出てきたようなところがあるのかなというふうに思うんです。売りさばく、その方式が一番簡単なものですから、品川のまちづくりは新しい段階に差しかかっているんだというとらえ方をしているものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"藤田委員","kind":"意見","question":"そこに我々議会が「こうしよう」とか、「こうしてほしい」とか、なかなか言えない部分があるんじゃないかと思うんです。各委員のおっしゃることは、当然だというふうに思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問・要望","question":"ですから、そこには情報が来ているわけです。こういう要望が来ているとかいろいろあるわけだから、それをつぶさに言ってもらって、そこから我々が意見が言えるんだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"藤田委員","kind":"質問","question":"ですから、区のほうで連絡調整をやっていますが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"やっぱり議会ですから、まずいろいろな調べたいこと、聞きたいことはきちっと聞く、調べるということが大事だというふうに思うんです。今後の計画のところは、本当にどういう中身でやっていくのかというところも、ぜひ知りたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"上山委員","kind":"質問","question":"本当に今後の区のお金を使い道の問題にも係わってくるわけですから、そういう視点からしても、非常に大事になってきているかなと思っているんです。ですから、品川全体規模である程度しませんけれども、大事なところになっていると思うんです。","respondent":"沢田委員長","answer":"ずっと意見が出てきたので、川西委員あるいは本間委員ありますか。では、川西委員、進め方についてご意見ありますか。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"１年間の特別委員会ですから、区民の意見を我々委員としてどれだけこの中に入れていくかというような、積極的な委員会運営にできればと思います。たったったと半年ぐらいすぐ経っちゃうような気がします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"本間委員","kind":"質問","question":"やはり今朝の新聞でしょうか、２日前でしょうか、新しくつくる家の上部に屋根の緑化の件で条例を何とかというのが出ていました。今年１年間の部分については成果がどうであったかというようなことを、そういうものをとらえていきたいというふうに、私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"川西委員","kind":"質問・要望","question":"平成１４年のりんかい線の開業に伴って東品川四丁目の開発、新しいまちというのはできるわけでしょう。古いまちとの調和の問題というのが、やはりまさにまちづくりの問題だといつも思っているので、どこかの委員会運営の中で入れていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"それから法改正の要望をしていくとか、条例改正の要望をしていくとか、それだけで終わっていたはずなんです。それは月２回できるんでしょうけれども、現実問題無理でしょうから、そういうふうな議論をしていったほうがいいような気はします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問","question":"ある程度限界はあると思いますが、１年後には反映できるというのが前提条件になった調査項目を選んでいくことが大事じゃないかなと思うんです。そういう方向のことを、密集住宅市街地においても１年間細かくあったけれども、やっぱり指定されたところがなくてもやっているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"横山委員","kind":"意見","question":"そういうところは、向こうは応える権利があるです。中に参加している、そういった開発に対して入っていければなと、私は感じを持っているんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"横山委員","kind":"意見","question":"だから、保留床を取るとか、大崎のところでも区の施設を権利変換してやるでしょう。だから、そういった部分だったら集中的に絞ってできるのかなと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"上山委員","kind":"質問","question":"それもある程度ないといけないんですが、品川区が権利変換云々かんぬんというか、ここのところを実際動き出しているのは大崎のあたりだと思うんです。そういう点で言えばいよいよ開発が始まる前ですから、すぐ計画という点で言えば、そういうところが強くなるかなという感じはしておりますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"横山委員","kind":"意見","question":"でも、どこかで実を出したいというか、答えを出していきたいと思う。そうすれば、ほかのことは報告を受けて、１年間流れてもいいしとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"意見","question":"おそらく、時間的な問題もあるから、今後の計画はどうなのかというところで見ていくほうがいいのかなというふうに思ったんですけれども。やっぱり、評価をしてからのほうがいいかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"石田委員","kind":"質問","question":"５回でやるのか、６回でやるのか別として、委員会としては進んでいるわけです。それが６回なのか７回なのか、それはやっていく中でわかってくることでしょうから、そのほうが効率よく委員会が運べるんじゃないかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"本田委員","kind":"確認","question":"どういう改善策が打たれているのか、進んでいるのか、ネックになっているのは何なのかということなどを掌握しなければいけないなと。都や国に対して議会側で言えることがもしあれば、住民の皆さん方の意向なども確認しながら対応して、このニュースを聞いたときに思ったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"横山委員","kind":"意見","question":"ここに何百坪を買ったから区分けして、皆さんどうぞそこに関係する人は入ってくださいよという宣伝だとか、そういう運動を全然していないんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"藤田委員","kind":"意見","question":"もう１年がかりで、そのまま空地になっているわけですね。そういうものを視察して……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"石田委員","kind":"質問","question":"先ほども出たんですけれども、借地があるじゃないですか。そういうところまで突っ込んでやるかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/506587?Template=document&Id=6208#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":42899,"voices":118}},{"id":"h13-20010607-14","meetingId":"h13-cm06","date":"2001年6月7日","dateIso":"2001-06-07","committee":"行財政改革特別委員会","time":"午後１時０８分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菅家委員","kind":"質問","question":"肉声で若干聞きたいと思うので質問をするんだけれども、この中間のまとめの見解、今説明がありましたでしょう。違う時点で、ここはもう済みましたよというようなことであれば踏み込んではいけないというのが大分出てくるわけですから、委員長に聞くのか。","respondent":"塚本委員長、中尾根企画部長、桑村政策担当課長","answer":"ちょっとお待ちください。菅家委員のご発言は意味が深いと思いますので、とりあえずマイクを使わないで、理事者のほう、お答え願えればと思います。それから図書館の見直しにしても、これで行政側ももういいんだと、しばらく１０年も見直しをしなくていいんだという前提に立ってはございません。ですから… 今、部長が申したとおりですが、委員会と今の検討課題についての関係です。","id":"exchange-001"},{"speaker":"菅家委員","kind":"質問・要望","question":"説明はよくわかりました。これから行われるそういう問題にも抵触してくるので改めて確認をさせていただいたわけですけれども、もしあれば聞かせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"菅家委員","kind":"質問・要望","question":"もう１件。できるだけひとつマイクを使わないで、この部屋で済むことならば、肉声でやりとりをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"実際に、今、職員の数でいきますと１,０５６名ですか、定数削減されたと。評価というんですか、この指摘に立って、どういうふうに行政としては行革を見ているのかというのを率直に聞きたいなというふうに思っております。","respondent":"桑村政策担当課長","answer":"その意味で、私どものつくってあります行革委員会のいわゆる大綱につきましても、そういう意味で積極的な行政需要にこたえるということが第一義です。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問・要望","question":"住民の側というんでしょうか、実際に事業を推進してきた職員の意識というんでしょうか、一つ一つどうだったのかという。ですから、どういうふうに思って、教えてほしいと求めました。","respondent":"桑村政策担当課長","answer":"今、保育園等につきましても、そういう意味で区民の評価というふうなことを、区民の皆さん、あるいは利用者の方に聞きながら評価をしています。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"実際に保育園についても２４％ぐらいの削減になるし、２０％近いんでしょうか、学童に至っては２３％ぐらいの職員定数の削減なんですね。それから、出張所の関係で言えば大体３名から５名でしょうか、３３名の全体の削減になっていますよね。","respondent":"中尾根企画部長","answer":"要は区民の生活をどう行政が考えて、よりよいサービスをどうしていけばいいのかということのために行政改革があるというふうに私は認識しております。今後の行政の取り組みについては、そのようにもっと明確にしていきたいですので、ご理解いただければと思います。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"今後のといいますか、当面の行革をしていく上での目標値というんでしょうか、そのようなものをお持ちなのかどうかというのをお伺いしたいんです。その場その場での、言葉は非常に悪いんですが、場当たり的な形で進められてきたものなのかという部分をちょっとお伺いしたいなと思います。","respondent":"中尾根企画部長","answer":"今まで総合実施計画というものがございまして、その中に事業をどれだけやるのか、どこまで進めるのかというのを明らかにしてきました。実施計画を進める上での目標を持っており、結果的に行革のそういう数字が出てくる、このように進めてきたところです。","id":"exchange-007"},{"speaker":"鶴委員","kind":"意見","question":"みずからが行政の役割として行政のそれぞれの責任者というものが、行革特別委員会なんていうことも必要ない。どういうことを、その段階になったら、また申し上げたいというふうに思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"そしてまたその中で、何一つ欠点がないというんですか、喜ばれている面が多い。これからの新規採用の計画というんですか、そのバランスがどうなっていくのか、お願いします。","respondent":"古川人事課長","answer":"職員の配置、これについては今後精力的に検討してまいりたい、このように考えております。その定数として考えているということについては、今の時点でまだ検討している、こういうことでご理解いただきたいと思います。","id":"exchange-009"},{"speaker":"辻副委員長","kind":"質問・要望","question":"この資料６で、この付則の１３年度だったら１４４という、これは一般職という形なんですかね。その辺はちょっと確認していただきたい。","respondent":"古川人事課長","answer":"そういう今後の退職見込み、動向ですけれども、職員の年齢構成をとらえますと、全職種で４４歳、今年の４月１日の時点で４４歳です。しかしながら年金制度の改正にその部分をどうとらえていくか、この二つの課題に対して今後検討を進めてまいりたい、このように考えてあります。","id":"exchange-010"},{"speaker":"辻副委員長","kind":"質問","question":"今言った団塊の世代が今後どういう動きになってきて、どっと減ってきたときにそれをどうかわすかということを、配置すべき配置をする。これは採用すべきだという、この辺をどう評価するかということも当然考えていった上で、長い目の中で考えていかなきゃいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"ちょっと関連で聞いておきたいんですけれども、例えば再雇用職員を採用しますと、その賃金というのと新規採用した場合の初任給ですね、どのくらい違うのか尋ねました。","respondent":"古川人事課長","answer":"再雇用職員は、これは報酬ということで、すべてのものをひっくるめまして、これも標準的で２１万５,０００円。このようになっております。","id":"exchange-012"},{"speaker":"鶴委員","kind":"提案","question":"どちらをどうすることが内実としてはいいことなのかという判断を、これからよく検討を加える必要があるんじゃないかというふうに思いますね。ここは新しい技能を求められている技術に、やっぱり大学生、また今後いろいろと考えさせていただきたいなと言う提案にしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問・要望","question":"１７７人の退職者の職種を教えていただきたいのと、かなりこれから１００人前後いるのではないかと、それから４０人から１３０人と幾つか波がある。ですから、そういう点では、職員のそうした配置の問題と事業展開というのはイコールなわけですから。","respondent":"古川人事課長","answer":"この間とってまいりましたのは、先ほど技術の継続、技能の継続あるいはそういう継続をどう図っていくかというお話がありましたけれども。の採用、これは今後とも十二分にその辺について精査して対応してまいりたい、そのように考えてあります。","id":"exchange-014"},{"speaker":"桜井委員","kind":"質問","question":"福祉職であればどういうふうな分野を考えているのか、それと先ほどの質問で、今後１００人前後の退職が見込まれている。そのあたりの職種も教えてほしいと求めました。","respondent":"古川人事課長","answer":"そしてこれからの一定の推移を見渡した上での考え方でございまして、区の基本的な考え方は、第１回定例会で区長が述べました。福祉の分野の中での子育て支援というものをとらえて、必要な職種の採用を検討してまいりたい、これが現時点で区の基本的な考え方です。","id":"exchange-015"},{"speaker":"佐藤委員","kind":"質問","question":"ちょっと簡単にお尋ねしたいんですけれども、再任用、再雇用の際、品川区内居住者とそうでない職員の皆さんがおいでになるんですが、そういう際は、この何かやはり品川区内居住者を優先して採用して、品川区の雇用の安定に役立てるとか、そういう特別な基準はあるんでしょうか、ないんか尋ねました。","respondent":"古川人事課長","answer":"採用に当たっての優劣をつけるというのは、これは困難というか、できないことです。それにつきましても区内、区外という分け方が極めて合理的な選考の方法なのかどうかということについては十分に検討する必要があろうかです。","id":"exchange-016"},{"speaker":"鶴委員","kind":"意見","question":"それはなぜかといいますと、例えば退職する人たちとの関連もあるので申し上げたわけです。それをどうしたいいのか、Ｃという学校はどういうふうに対応していこうかというようなこともあるから、あえて申し上げました次第ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"住民、納税者側での目線の見方というんでしょうか、その辺も重視していかなければいけないと思うんです。反比例というんでしょうか、その辺の財政面というんでしょうか、よりわかりやすい成果といったものを含めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"桜井委員","kind":"質問・要望","question":"みずからがどうだったのかという、行政のあり方論というのが私は今の時点ではとらえていく必要があるのではないかというふうに思うんですね。その提供を受けている区民がどういうふうにまた行政に要望し、そしてそれぞれの意識というんですか、こういう一つのテーマから行政を見るというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"佐藤委員","kind":"意見","question":"突然の委員長の指名で。先ほどお話になりましたが、そういうものに沿って進めていくような形をとっていただいたほうがよろしいのではないかなというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"それに伴う第１次行革というんでしょうか、そのときには、私たちは身をもって４８から４４にということで定数削減をしてきました。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"金高委員","kind":"質問・要望","question":"当然どういう形で１年間進んでいくかということなんですが、これから先々行くにしても何にしても、すべて必要だと考えています。なぜかというと、これは時代が絶えず先に動いているわけですから、常に取り残されてしまうという考え方を自分自身に持っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"意見","question":"非常に議運マターになってしまうかもしれませんけれども、定数が４２人いる中で、いわゆる役職者というのは２６名いらっしゃるんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"鶴委員","kind":"質問","question":"質問というよりも、見事であるということを、まず称賛の言葉を送っておきたいというふうに思います。そして新たなる２１世紀の安定飛行へと行けるのかどうかという、質問ではありません、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"桜井委員","kind":"提案","question":"その素案と決定の違いというんですか、１４ページに事業部経営会議というのが、前回の素案のときとはちょっと内容が違っていますよね。私はこの前もちょっと提案したのは、この満足度なんですねとの意見を述べました。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"それから、こういう基準があれば、もっとこの事務事業の見直しに前向きな答えができるとかという部分が入ってくる可能性があると考えております。２００程度の事業につきましても、定型事務とか… 先ほど来ご説明をしておりますとおり、区の執行機関における最高の決定機関ということで、この４月から設けたものです。","id":"exchange-025"},{"speaker":"桜井委員","kind":"質問・要望","question":"どういうふうに全体の評価をしていく上で、あるいはまた秋口ですか、この評価をしていくということに内容にも既に入っていくのかどうか。もう少しちょっと詳しく教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"それは検討をしていきたいと考えていますけれども、今のところは、今のところはその基準の中には入れておりません。１６ページのほうにも書いてありますけれども、それ以外のメディアでもある程度公表できるような形での工夫を今後検討していきたいと考えています。","id":"exchange-026"},{"speaker":"桜井委員","kind":"質問","question":"それで、事業部経営会議も公開の対象になっているのかどうか。情報提供の部分ももう一度説明を求めました。","respondent":"中尾根企画部長、市岡企画財政課長","answer":"ですから、道路の場合も、要するに今までの実施計画上のやり方で、舗装をするということの舗装率何％、ここをやれば、それが達成かという。したがって、その満足度はどうだということについての設定というものは… 内容に変更はございませんで、その基準に従って公開できる、こういうことです。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"追求するというんでしょうか、目標に置くところというのが、やっぱり私は満足度だと思っているんですよ。私自身もまたそこは研究していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鶴委員","kind":"質問","question":"だから、別途にこの評価制度というのがあれば、区民が見てどう評価するかという制度は別に構築すべきだ。間違っていますか尋ねました。","respondent":"中尾根企画部長","answer":"私が先ほど言わなかった部分をフォローしていただいたと考えていますけれども、言ってみれば、こういう数字の関係しか立てられない。そういうことで、先ほど説明したつもりですので、ぜひよろしくお願いいたします。","id":"exchange-029"},{"speaker":"本多委員","kind":"確認","question":"それについて、もう都区制度改革から１５カ月も過ぎていますので、当然この辺は既存事業という対象として見ていくんだと思うんですね。対象になっているのか、もう一緒くたになっているよというので、その辺の確認だけちょっとしたいんですけれども。","respondent":"榎本行財政改革担当課長","answer":"今年とりあえず今実施しようとしているのは、当然移管されて１２年度の実績が出ておりますので、それも対象にして評価をかけていきたいと考えています。","id":"exchange-030"},{"speaker":"本多委員","kind":"確認","question":"職員の意識改革という部分でも、その辺ちょっと改めて伺いたいと思うんですけれども。都区制度改革での移管された事務事業に対する職員の意識というんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"それをどうするための事業なのかというのを考えながら進めていかないと、今までの事務事業が今後どうすればいいのかというのを考えていく形になりますので、意識改革の部分も図っていかれると考えています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"その点ご了承いただいた上で質問させていただきたいんですが、１４ページのこの全体の体制の中で、議会とのかかわりが出てくるものなんでしょうか。逆に言うと、それしか議会側とのかかわりはないというふうな理解でよろしいのか尋ねました。","respondent":"中尾根企画部長","answer":"議会との関係で、これを認定していただかないと次に進めないとか、そういう関係ではありません。ぜひとも議会の中ではそのことを十分に分析でも評価でもしていただいて、次のためのサジェスチョンはいただきたい、このように思ってあります。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"しない等の議論があったのかどうか、また将来的にどのような取得に向けて何かお考えがあるのかないのか、ちょっとお伺いしておきたいと思います。","respondent":"桑村政策担当課長","answer":"一つはＩＳＯ９０００シリーズということで今年取り組んでいるわけですけれども、こういう区の仕事のやり方、一つの考え方です。それはまた客観的な先ほど申し上げました指標というものをどういうときに見るかというものを明らかにしていきたいというのが考えです。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"委員長のほうから行政評価に関することということで、委員会の申し送りという３点がありましたけれども、それを文章化されたものは我々には示されないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"ですから、その中で、こういう方向でという話をさっき出しましたよね。そういうことは、文章化したものは出さないわけか尋ねました。","respondent":"事務局","answer":"議会運営委員会の議事録があるだけですけれども、こちらは非公開ですので、委員長からご説明があったとおりです。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"もいいんですけれども、今ちょっと思っているのは視察の関係で、私はぜひ川崎を希望しているんですね。できれば川崎も、また住民との関係では情報公開の問題もかなりやっている面があるので、希望として要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鶴委員","kind":"質問","question":"でも、皆さんにその意識を徹底する３項目について、それをこの行政評価に関することだとか、三つこうあった。それをメモ化して文章化することが脱法行為なんか尋ねました。","respondent":"福田区議会事務局長","answer":"議会運営委員会、ただいま書記が申しましたように、非公開ではあります。議会運営委員会を通して、委員長のご指示等があれば文章化をして、この委員会にお出しをすることはやぶさかではございません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503251?Template=document&Id=5686#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":53141,"voices":116}},{"id":"h13-20010702-6","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"区民委員会","time":"午前１０時０５分～午後２時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"地方税法改正に伴っての条例の改正ですから、ちょっと一つだけもしわかったら教えていただきたいのは、これは期間を３年間延長しますよね。この延長の理由というかな、どういうわけで３年間だけ、あるいは２年間延長をされてきたのか。","respondent":"松崎税務課長","answer":"大きな理由といたしましては、やはり経済状況がいま一つ上昇気流に乗れないというのがございまして、長期譲渡することによって税負担を軽減するということを目的としているのが一番大きな理由です。","id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"３年とか２年とか。大体こんな形のときは３年だよと、あるいは２年だよというんでしょうか、ほかの確たる理由があってそういう数字をちょっと出してきたのか。","respondent":"松崎税務課長","answer":"前者と後者、３と４では延長期間が２年と３年でちょっと違うんです。申し訳ございません。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと１点だけお聞きをしたいんですけれども、新設された先物取引のところでちょっとお聞きをしたいんですけれども、低くなるわけですよね。原委員の質問で、その辺の相当高額な収入がある方への税負担を軽くするかのような感じに受けちゃうんですけれども、その辺ではどうなんでしょう。","respondent":"松崎税務課長","answer":"これも経済の自由化政策の一つでございまして、これを実施することによって市場の活況をもたらすというのが一つの大きな理由になっているようです。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"実際に去年あたりですか、もちろん区でどうのこうのとできる問題ではないんですけれども、その辺のちょっと考え方があればお聞かせを願いたいと思います。","respondent":"松崎税務課長","answer":"今回は後者の部分、個人投資家に刺激を与えるという部分で、この税制を施行されているというふうに考えるものです。ただ、それとこの当方の税制上の優遇措置というのは、あまり関連がないのではないかというふうに思います。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問・要望","question":"お手元に資料があれば教えていただきたいんですが、税率が６％で区民税が４％となっている、今まであったのも税率は６％だったんですか。こういうのがどの程度の収入になるという感じは、それをちょっと参考までにお聞きしたい。","respondent":"松崎税務課長","answer":"それと、４番目ですが、これは逆に３０万ぐらい増収、差し引きで６７０万ぐらいの減収が見込まれるというようなシミュレーションはしております。今までは事業所得から雑所得の中に入っていて、それが株式所得か何の所得かが分離できないので、比較のしようがないんですね。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"それでも経済の活性化というんですか、それでもやらなきゃならないんでしょうか。品川区が税収が増えるような方法を考えていただいて、それはどうか尋ねました。","respondent":"松崎税務課長","answer":"基本的には、各２３区の独自性というようなところで、いろいろなことを考えていくのではないかというふうに考えているところです。自治体がどのように加工するかということは、ちょっと今回の地方税法の改正の視点というのは違うというふうに考えております。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"国の法律でも結構ですから、国がいろいろな手を打っていく、それはもう国政上当然のことだと思います。物の考え方としてどうなのかということをちょっとお聞きしたいなと思いますね。","respondent":"松崎税務課長","answer":"４,０００円均等割いただいているんですが、２３区の中で、検討しながらいろいろ進めていただくことになろうと思います。直接区民の方に負担をお願いするものですので、どうあるべきかというのは、慎重に検討していく必要があるというふうには考えております。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"自治体にとりまして、メリット、デメリットいろいろな問題があると思います。ご答弁いただきましたけれども、私はそういう立場で、ぜひ頑張っていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"し上げておりますので、どうぞ理解してください。 それでは、第６１号議案、品川区特別区税条例の一部を改正する条例については、原案のとおり決定いたしました。…","agenda":"し上げておりますので、どうぞ理解してください。 それでは、第６１号議案、品川区特別区税条例の一部を改正する条例については、原案のとおり決定いたしました。…","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"平成１１年１０月に、ゲートシティ側で芳水小学校で測定をした測定結果がわかれば教えていただけますか。","respondent":"金井環境課長","answer":"芳水小学校は２８基全部を無線で連絡し合いまして、そのときの低周波音の変動を調べたけれども、全く変動がないというふうに聞いております。","id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"確認になっちゃうんですけれども、平成１０年度４４件というのは、これは国レベルですよね。品川区内においてはどうなんですかという質問をさせていただこうと思いましたら、品川区内においては請願者しか陳情等はないわけですよね。","respondent":"金井環境課長","answer":"請願者ともう１件、区に対しては陳情があります。同じようなところからこういった苦情があるかと、イーストタワー周辺からあるかというと、それはございませんでしたです。","id":"exchange-010"},{"speaker":"藤原委員","kind":"意見","question":"個人的なものといいますか、課長が先ほどおっしゃったように、この委員会室の中でも低周波というのは出ているわけですよね。このゲートシティの周りの中では、今のところで陳情、請願を持ってこられたのは請願者しか現実にはいないですよねとの意見を述べました。","respondent":"金井環境課長","answer":"年齢も２０から７０歳ぐらいまでの人、その結果から見ても、ある程度のレベル以下ではほとんどあらわれないという研究データがあります。最初にご説明しました低周波音というのはどういうところから出ているか、やめておきなさいという、こういうこともあります。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"それを読んでいただけたかどうかわかりませんけれども、あるいは報告書の提出もないじゃないかとか、そういうことが書かれているわけですよね。しかも調査結果から見ると、ちょっとこれと違うなという部分があるんですが、その辺をどうお感じになっているのか、ちょっと伺いたい。","respondent":"金井環境課長","answer":"きちっと職員も対応して、その実験データも渡しまして、こういった資料もお見せしながらご説明をさせていただいて、実験データも出しております。私どもとしては苦情対応として、ここに書かれて言われていることは、すべてきちっと対応しています。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"もう１件ちょっと確認をさせていただきたいのは、あるいは何か感じているよとか、そういうことは一切なかったかどうかの確認が一つ。これは、行政としてはどういうような感じなのか、受け手の側としての様子を聞かせてほしいと求めました。","respondent":"金井環境課長","answer":"現状の私どもの測定あるいは対応、これ以上申し訳ありませんが何もできませんですので、それからお医者さんもいます。やはりそこできちっと主張されて、処理されるのが一番適切ではないか、区としてはこれ以上の対応は不可能だです。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"それはどうなんですか。民民の問題ですからね、低周波の問題では裁判も幾つも起きているんだから、そういうふうになっていくわけですよね。","respondent":"金井環境課長、野本環境清掃事業部長","answer":"こういう基準が何もないところに入っていってすることはまずできないということをご理解いただきたいと思います。そういたしますと、したがいまして、請願者の自宅よりも低い値がここでは測定されていることがお話しできるかと思います。 例えばゲートシティから出ているよということを行政側が対応するためには、あそこしかないはずだろうというようなことで行くことができる。こうせいというのは、権限もないですし、今の中では難しいだろう。","id":"exchange-014"},{"speaker":"本田委員","kind":"確認","question":"こういうふうになってきているわけですから。そちらで全部明らかにしたらどうですかというお話があったけれども、そういう行動ができるのか、それは今の仕組みの中ではどうなんか尋ねました。","respondent":"金井環境課長","answer":"審査会の中では、その苦情申し立ての内容と、もし区がかかっておれば、そういうデータを出して、専門家がそこで判断をします。明らかに、そうした対応を、今後区なりが提言に基づいて実施をしていくという形になろうかと思います。","id":"exchange-015"},{"speaker":"本田委員","kind":"質問","question":"うちは原因じゃないよと片方は言う、いやあんたのほうだと、こう言うというところで、話し合いにもならないという状況にもなるわけですか。ゲートシティとの関係は。","respondent":"金井環境課長","answer":"なかなか幾ら説明をしても、私どもも測定結果を説明していますけれども、あそこを信じていらっしゃるという動きが若干あるのかなと。そんな状況ではないかなというふうに思います。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問","question":"請願者は行政にお願いをして、いろいろと調べて原因をはっきりさせて解決したいと願っていても、なかなかそこのところはうまくかみ合わない。本人が直接被害を受けているという、そうすると、この問題の解決には法的な手段ということも今後考えられるというふうに理解してよろしいんか尋ねました。","respondent":"野本環境清掃事業部長","answer":"我々の耳なり体に来ていますから、あるそういうような状況の中で、ある特定のものだけをピックアップするというのは非常に難しいと思います。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問","question":"今いろいろお話を伺いまして、品川もそうですけれども、その辺は理解しておきます。以上、ちょっと状況だけ理解をさせていただきましたので、どうするかについては、また後ほど表明いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問・要望","question":"その辺がわかればちょっと教えていただきたいのと、これはどうしてまたご本人の、東電不動産管理(株)がやった調査方法とはまた違いますよね。この辺でのデータとしてお手元にあるのかどうか、とりあえずその辺を。","respondent":"金井環境課長","answer":"音圧だけが高いということで、どの辺からきちっとわかるかという、そういった断言することはできない。東京都のほうの委託をしているような、それは専門のやり方があろうかと思いますので、それで十分判断ができるというふうに聞いております。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"周波数そのものを分析していく、周波数分析機みたいなもので計算をしていけば、一定程度わかるんだというのは私は聞いているんですけれども。ちょっと今の課長の説明との意見を述べました。","respondent":"野本環境清掃事業部長","answer":"２８基全部動かした場合、はっきり見えるはずですから、それを探そうとしたというのが中間地点を選んだという理由です。私はちょっと勉強不足で、そういう技術があるということをちょっと承知してございませんけれども、かなり難しいのかなという予測をしています。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"なかなか実際に人体にどういう影響があるかまだまだわからないんだよということであれば、もちろん事前に区がどうこうしてくれと言ったわけではないということですから、きめの細かさというのはどうしても必要ではないかと思うんですね。","respondent":"野本環境清掃事業部長","answer":"まだまだ区レベルで単独でどうのこうのというのは、今非常に難しい状態だということで、ご理解をいただければありがたいと思います。","id":"exchange-021"},{"speaker":"金高委員","kind":"質問","question":"このご本人のお宅から１.１キロのところの円周を描いたときに、ビルというんですか、大学があります。その辺を含めて、半径を描いたときの、そういう測定というのは別にしていないんか尋ねました。","respondent":"金井環境課長","answer":"私どもは、自宅で行っただけですので、周辺の地域等は一切やってございません。ゲートシティと同じような施設が設置してあるかという調査もやってございませんので、大体上にそういう機器が設置、調査をしておりませんので。","id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"現状の中では。東京都のほうですか、審査会ですか、今日結論を出していただきたいというふうに私は思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問","question":"その報告を６月３日ですか、平成１１年１０月、中間地点にある芳水小学校で測定を実施された。私は全くどう考えても難しい、るるこの請願項目３点についても、こういうふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"原委員","kind":"確認","question":"低周波そのものについては、今後の中でまた確認はされていくと思いますけれども、短時間にはなかなかいく課題ではないと思います。その意味からいっても、一応その願意には沿いがたいのではないかなということで、不採択ということで、私はそう思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"菊地委員","kind":"意見","question":"私のほうは、これは採択をすべきものだと思います。全国で２万人ぐらいの方が、今ほんとうに持っている、もう一度全体が納得できるような体制づくりも必要ではないかというふうに思いますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"金高委員","kind":"質問","question":"しっかりと区のほうでも３年間ですか、その実績があるわけですから、やはり上のほうでしっかりとやっていただくということがなされて。ここで一つの起点として、その辺も踏まえた上での先々の方向づけをまたとっていただければということは、意見として添えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"本田委員","kind":"質問・要望","question":"したがって、私は１番、２番、３番、いずれにおきましても、その趣旨においては採択すべきだと。特に１番の問題については、本人の請願の趣旨が達成できるようにご協力いただきたいな、私は採択をすべきではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"本田委員","kind":"質問","question":"できれば趣旨採択のほうがいいんですよ。一番のところができないというのがわかっているわけですから、採択か不採択かという結論を出せというのであれば、採択というふうにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"原委員","kind":"質問","question":"いいですか、一つ。防犯協会とか、それから警察の協力の会とか、その辺の状況をちょっともしあれでしたらお話しほしいと求めました。","respondent":"長田地域活動課長","answer":"区の動きですけれども、これも前回ご説明を申し上げましたけれども、この陳情が出されたのは３月１日です。一連の警察署の不祥事が問題になったというようなこともありまして、国民の相談に適切に対応するため、この協議会を立ち上げたということのようです。","id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"そのいろいろ内容については、もう一つ資料にしたいのは、逆に行政のほうにさっきご報告ありました７項目の陳情書が出てまいりましたですよね。それから、それに対する対応は、一応区の段階ではどういう形にされているのかというのがわかれば説明を求めました。","respondent":"長田地域活動課長","answer":"当然条例が設置を制定されるということになれば、当然その目的に沿ったしかるべき対応が必要となってこようということで思っているところです。昨今の経済情勢の中で、なかなか新しい補助金の設置あるいは増額というのは難しいところがあるのかな、こんな気がしています。","id":"exchange-031"},{"speaker":"原委員","kind":"質問","question":"それから、例えば７項目の中で、ほかの項目に該当するような条例等々が現状の場合に考えられるのはありますでしょうか。ほかにはないか尋ねました。","respondent":"長田地域活動課長","answer":"それぞれ施設の設置条例等に基づいて、条例に基づく規則で使用料等が決まっている、こういうことがあると思います。おそらくこのくらいだと思います。","id":"exchange-032"},{"speaker":"金高委員","kind":"質問","question":"そういうものが出ているわけですから、そういうものを全部含めての条例制定ということでこれを出てきたというふうに解釈すればよろしいんですかね。ちょっとこの辺の条例制定するということで。","respondent":"長田地域活動課長","answer":"これにつきましては、あくまでも陳情趣意説明という形で７項目についてはお願いをしたいよ、こういう内容で出てきたものです。あるいは今回これを通じて、将来的には補助金の増額をお願いしたいというようなことは、ちらっと耳には入ってきてあります。","id":"exchange-033"},{"speaker":"金高委員","kind":"質問","question":"こちらのほうに、代表ということでもって品川防犯協会がありますけれども、それぞれそれ以外の各警察部門の防犯協会があります。これを防犯協会のほうから条例制定をしてほしいというふうになりましても、ですから、これは今日これは決めるわけか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"金高委員","kind":"質問","question":"一応継続審議ということですから、いずれにしても今日決める形になるんじゃないかという気がいたしますので、私は意見をちょっといいですか。今回新しくこの委員会のほうにまた出てきたわけですから、結論を出すのであれば、趣旨採択でいいんではないかという気がいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"菊地委員","kind":"意見","question":"今２３区でいうとほかの４区が制定をしているということですが、でき得れば資料として、その４区のどんな中身を持ったものなのかというのが。〔「ついていないです」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"この中身だけですとどうこう言うことができないんですけれども、この中身で制定しようとしたときには、ちょっと聞きようのない話なんですけれども。質問のしようがないものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"原委員","kind":"確認","question":"課長のほうからお話が出たものですから、精神的な考え方の中でどうするかという、そういうような考え方になるんじゃないかと思うんですね。先ほどちょっと私も確認をしましたけれども、現状の中での条例、考えていかなきゃならない課題だなと思うんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"本田委員","kind":"質問","question":"ですから、都は何か何もやっていない、都に向けては何もやっていないとたしか報告があったと思うんですね。そういう状況ですから、趣旨はよくわかりますので、何とかこれは区民の安全というものにこたえなくちゃいけないと思ってはいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"原委員","kind":"意見","question":"広い考えで何とかこの趣旨も酌み取ってほしいという意味合いも含まれていると思うんで、僕は、趣旨だけでもとりたいなというふうな気持ちはあります。これはまた皆さんのご判断でしょうけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"菊地委員","kind":"意見","question":"どうしても条例をつくるかつくらないかという兼ね合いになっちゃうと思うんですけれども、じゃあ条例制定にまつわる問題になるのかなというような。その辺がちょっとよくわからないんですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"菊地委員","kind":"質問","question":"原委員が言われたその趣旨を採択することが、議会としてこれが一つの項目ですよね、要は条例をつくってほしいという項目ですから。それがちょっとよくわからないんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"我々がとっているのは、この議会に上がってきているものですから、その中の項目にも条例についての件であるわけです。ですから、即これを趣旨採択したから、即条例を制定しなきゃいけないということではないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤原委員","kind":"意見","question":"私としては、ほんとうに趣旨はよくわかりますので、趣旨を採択したいという意味で趣旨採択であります。意見表明ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"堺委員","kind":"意見","question":"説明ございましたけれども、基本的には、東京都の形という意味でご説明もさっきございましたように。だから、趣旨採択という扱いのほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"本田委員","kind":"意見","question":"そういう何といいますか国がやること、これはちょっと違うというのが、私のこの陳情の受け止めなんですよね。中に言っていることはどうも混在しておりますので、今日やられても、それは私はいいというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、本来でしたら継続という形をぜひとっていただきたいなと思うんですけれども、どうしてもできないんだよね。そういう意味では不採択、陳情ですから、不採択という言い方でいいのかどうかわからないのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"本田委員","kind":"質問","question":"参考送付で来たことですから、当委員会として、議題にして意見をまとめるようなことができないのかどうかなというふうに思っているんですよね。それから４月に国会の参議院、批准を行うべきという可決をした経緯から見て、委員長のほうでその辺の取り計らいをお願いしたいと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"本田委員","kind":"質問・要望","question":"前にちょっとすみません。それは過ぎたことですから、当委員会に来たわけですから、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"原委員","kind":"質問","question":"ですから、その理由に、今アメリカにも日本の政府は働きかけているわけですよ。これが私の考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"堺委員","kind":"意見","question":"やはり議長のほうで参考送付という扱いをされた経緯から考えますと、やはり原委員のおっしゃられたような手順を踏まれたほうが、我々としては扱いやすいかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"本田委員","kind":"意見","question":"参議院選挙を目前に控えて、私は小泉さんの訪米、訪欧、いろいろ仲介役、問題があります。皆さんが、できるだけ早い時期に正式に議論をして、ひとつその辺は取り計らいをよろしくお願いしたいというふうに思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2298#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":50511,"voices":137}},{"id":"h13-20010702-7","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"厚生委員会","time":"午前１０時１０分～午後 ２時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"第６２号議案、品川区手数料条例の一部を改正する条例","agenda":"第６２号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"船波委員","kind":"質問","question":"それから、手数料の３,２００円というのは、何を根拠に決められたんでしょうか。この手数料は品川区独自で決めたものなのか、何を根拠に決めたのか、お伺いします。","respondent":"田中健康課長","answer":"開設者が変更されることに伴って、実質的には何ら変更が生じないと認められるような場合、オーケーだという内容です。運搬費というものを積み上げまして、３,２１５円という積算をしてございまして、切り捨てて３,２００円というものです。","id":"exchange-001"}]},{"id":"topic-02","title":"第６３号議案、品川区保健所運営協議会条例を廃止する条例","agenda":"第６３号議案、品川区保健所運営協議会条例を廃止する条例","exchanges":[{"speaker":"船波委員","kind":"質問","question":"そのかわりとして、健康づくり区民会議が設置された場合には、その報酬というのはまた新たに設定されるんでしょうか。それから、どういう方がメンバーになって、報酬が決定される場合は、そのレベルはどれぐらいになるのか、お伺いします。","respondent":"田中健康課長","answer":"今回、私どもが予定しております健康づくり区民会議のほうは、要綱で設置をさせていただこうかなと考えています。要綱のほうで、この報酬等については位置づけをしたいと考えています。","id":"exchange-002"},{"speaker":"船波委員","kind":"質問","question":"健康づくり区民会議のメンバーになるのは、どういう人たちを予定しているのか。要綱によって報酬を決めるということですけど、どの程度のレベルにするお考えがあるのか、お伺いします。","respondent":"田中健康課長","answer":"健康づくり区民会議のメンバーですけども、現在、いろいろな形で、どのように皆さんにご参加いただくかを検討している最中です。それから、報酬等につきましては、今後、定め方によって決まりますので、そのときにまたご報告をさせていただきたいと考えています。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"意見","question":"重ならないように聞くんですけども、健康づくり区民会議の皆様が、では具体的に何をどういうふうにして計画を進めていくのか。保健所運営協議会の仕事をどういうふうに引き継いでいくのかという説明の部分がちょっと薄かったような気がしますので、改めてお願いいたしますとの意見を述べました。","respondent":"田中健康課長","answer":"健康づくりということを大きな流れとして受けていくということで、私ども、区民会議というものを立ち上げていくと考えています。健康づくりプラン２１の策定ですが、そういうことをご審議いただきながら進めていただく団体として、考えておるところです。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"プラン２１を策定、それから先をこれからどういうふうに考えていくかというところは、まだこれから議論をしていくんでしょうか。それから、区民会議の中で、今、将来的な構想をどういうふうに考えているのかということを、最後にお伺いいたします。","respondent":"田中健康課長","answer":"これを区民会議にて策定をお願いし、推進に対するいろいろな仕掛けをお考えいただいて、それを推進に結びつけていきたいです。これからは、新しい組織協議会をお願いするという中身と、私どもは考えてあります。","id":"exchange-005"},{"speaker":"須藤委員","kind":"意見","question":"それからいま一つは、品川区で、任意になったんで廃止をしますということの意義というのは、どういうことなのか。その辺をまず最初に説明を求めました。","respondent":"田中健康課長","answer":"住民の方みずからが活動していただけるような形でのプランづくり、推進の体制ということで、新たに組織したいという考え方が基本です。そのような考え方の中で、一連の流れをつくってまいったつもりです。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、保健所自体が、今言ったような生活習慣病であるとかという方向性に変えていく。基本的に、保健所自体のありようということまでは、どういうふうにお考えになっているんか尋ねました。","respondent":"田中健康課長","answer":"参加をしていくべきだと、これからは、そういう施策の内容の重点を少しずつ増やしていく。今もやってありますけども、その点は、やはり大きな視点という流れで、保健所のほうも機能していくべきだろうと考えています。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"健康づくりばかりに目が行くんじゃなくて、本当の区民の健全な公衆衛生というものがやはりベースにあると思うんで、そこをしっかり見ていただく。区の方針としては、保健所本来のありようというものはしっかりつかんでおいてほしいと求めましたが、その辺はいかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"もう１点は、もろもろの地域の公衆衛生向上のために果たしている役割についても、連携を十分にとっていくべきだ。より緊密な連携を、今後の我々のスタンスですので、ご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"健康づくり区民会議の地域の意見を聞いていくということで、実践している団体と言われましたけど、例えばどういう団体があるのか教えてください。協議会というのは、例えば具体的にどういうものがあるのかについて、教えてほしいと求めました。","respondent":"田中健康課長","answer":"それから、栄養士会の皆さん、この辺はひとつそういう団体での候補になろうかなとは考えてあります。いろいろな分野で、ご協議をする場を、従来から設けているです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"協議会というのは、住民の方もメンバーに入っているんでしょうか。ちょっとそこら辺のところがわからないので、説明を求めました。","respondent":"田中健康課長","answer":"食品の関係の二つの協議会制度も、そういう意味では、地域の方にご参加いただいております。そういう形のほうが強いわけですけども、一般的なかかりつけ医の調整の関係でも、社会福祉施設等々にお願いをしています。","id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"ある程度もうできている団体ばかりなので、これからの保健所に対する希望とかがあるところに関しては、区としては、どういうものをお考えでしょうか。お聞かせをほしいと求めました。","respondent":"田中健康課長","answer":"若い層の参加をということで、今回、私どもも、その辺の視点も考えてあります。そういう方よりは、協議会のほうで、実践できる方をこれからもお願いしていきたいとは思ってあります。","id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味では、若い世代のそういう人たちがもっともっと気軽に相談ができるような保健所にしてもらえたらと考えています。それについて、もしお考えがありましたら、教えてほしいと求めました。","respondent":"田中健康課長","answer":"生活習慣病、それからそれ以降の健康維持ということですので、どうしても中高年の方が中心のターゲットというふうになってまいるかと思います。その中で、区民の皆さんのご意見をいただく場といいますか、そういうチャンスはできる限りこれからもつくっていきたいと考えています。","id":"exchange-012"},{"speaker":"鶴副委員長","kind":"確認","question":"あるいは推進を目的とした区民会議となるわけですから、年１回あたりでは、いい声というのは出てこないということは想像に難くないですね。どういう手法で、こういう委員会とか、協議会というのは設けられているわけか尋ねました。","respondent":"田中健康課長","answer":"そのときどきの論議といいますか、集まっていただきたい人の時間帯ですとか、そういうものを考えて運営すべきです。あくまでいろいろな目的、それから運営の実態等を含めて、これからそういうご参加をいただきたい時間を工夫をさせていただきたいと思ってあります。","id":"exchange-013"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"私も２２年間議員をやらせていただいているけども、事前に役所の人たちから、「ご都合はいかがでしょうか」なんて聞かれたためしがない。課長が別の審議会に行くのに、役所を休まなきゃいけないじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-03","title":"第６４号議案、品川区興行場に関する条例の一部を改正する条例","agenda":"第６４号議案、品川区興行場に関する条例の一部を改正する条例","exchanges":[{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと教えてほしいんですけど、こういった施設の会社分割というのは、具体的にはどういうことが想定されますか。","respondent":"田中健康課長","answer":"「会社は、昨年改正された、商法等の一部を改正する法律によりまして定められた内容です。それに連動する形で、今回、条例を改正するです。","id":"exchange-015"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"どういうメリットがあるのかなということもございましたし、どういう場合に、分割の手続だとかをとられるのか。そこがちょっと不勉強でわからなかったものですから、お尋ねをさせていただきましたが、課長に答弁を求めるつもりはありませんので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"そういうことは、区内だけじゃなくて、この辺はどういうふうになるのかなという疑問があるんです。遅滞した場合の罰則みたいなのはあるのか、どうかとの意見を述べました。","respondent":"田中健康課長","answer":"今回は、分割が届出で済みますよという内容になるわけです。保健所等を中心に今まで指導していた内容では、１カ月ぐらいを一定のめどに、遅滞なく届出をするように指導を行っておったところです。","id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"大体３０日だというが一つの目安だろうと思うんですけど、厳重注意じゃないけど、マークを出しなさいというようなことを言うのか。いわゆる申請しなきゃわからないのだから、その辺のところはどうなっているのかなという思いだけですとの意見を述べました。","respondent":"青山品川区保健センター所長","answer":"おおむね１カ月ぐらいを目途にいたしておりますが、罰則規定は特にございません。ただ、おくれて届出があったようなときには、厳重注意というような形で注意をし、今後について、注意、喚起をするという形で対処しています。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"確認と、それから質問をしますが、それに対する条例を整備するという判断でよろしいんでしょうかということが一つ。厚生委員会所管、それからそのほかのいろいろな各常任委員会等の所管に係わりも出てくるでしょうから、わかりましたら説明を求めました。","respondent":"田中健康課長","answer":"それに基づきまして、私ども、現在、この条例も含めて、関連の条例規則の改正作業に入っているという内容です。他のところにつきましては、ちょっと私ども、今把握をしてございません。","id":"exchange-019"}]},{"id":"topic-04","title":"議員提出第５号議案、品川区乳幼児の医療費の助成に関する条例の一部を改正する条例","agenda":"議員提出第５号議案、品川区乳幼児の医療費の助成に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"品川区を除く５区のうち３区が、今年度、年齢拡大について区から提案を行っているという状況です。今回の条例提案は、品川区でも、ぜひとも所得制限の撤廃をしてほしいと求めるものですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"船波委員","kind":"質問","question":"品川区では、それでもやはり所得制限をしている、その根拠はなんなんでしょうか。どういう考え方でもって、所得制限を設けているのか尋ねました。","respondent":"谷田部児童課長","answer":"乳幼児医療費助成制度は、通常３割と言われてありますけども、保険診療にかかわります自己負担相当分をそれぞれ区が助成するという内容です。効果の低い方には、この制度については対象にしないというような考え方から、品川区では所得制限を設けているです。","id":"exchange-021"},{"speaker":"船波委員","kind":"質問","question":"これから先も所得制限をするとか、しないとか、何歳までするとか、しないとか、ほかの区も、自治体も、以前していたのがしないようになるとか、そういう変化もあるみたいですけれども、品川区では、今のような考え方で、これから先も制限を撤廃するつもりはないということなんか尋ねました。","respondent":"谷田部児童課長","answer":"今年の１０月から実施ですので、従来、６歳未満だったのが、６歳に達した日以降最初の３月３１日まで対象になるという条例案です。この１０月から１０ポイント引き上げ、８５％に拡大していくということで、これから実施していくわけです。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"いただいている資料によりますと、扶養の親族によって所得制限の額が違うようですが、品川区だと、補助をいただける対象が８５％の所帯になるレベルに設定されているということか尋ねました。","respondent":"谷田部児童課長","answer":"３３万円ずつ加算していくわけです。お子さんの８５％の数のまとまりの扶養義務者の総所得金額が幾らになるかを電算上で計算しまして、８５％のお子さんが対象になるというものです。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"確認","question":"何点か、まとめて確認と、ご説明をお願いしたいんです。それから理論を詰めた上で提出してこられたと考えていますので、そのことについてのご説明を、鈴木委員からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"３月５日の厚生委員会の中で、すべての子どもを対象にするとどうなるかということで、２,０００人が新たに対象になるということです。その手当てをどうするのかというご質問ですけれども、私たちの提案では、１,０７０万円程度になるということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"年額６,４００万円増えるということですから、６月、新たにつくっていく必要があるわけですね。そのことがなぜ出てきたのかという素直な疑問があるんですけれども、６,４００万円の財源の手当てをどうしていくのかということを説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"毎年、毎年ずっと組んでいく恒久的な財源ということだと思うんですけれども、６,４００万円というのは、一般会計に占める割合はほんとうにごくわずかということですので、政策的に議会が必要と判断すれば、当初予算で十分組める金額だと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"厚生委員会に条例を提出されているわけですから、当然、まずその数字の詰めから始めていかないといけないんじゃないでしょうか。まず厚生委員会で条例に入る前の段階で詰めておかないと、この内容に入っていけないと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６,４００万円という金額ですが、今年の３月５日の厚生委員会の議事録の中で、北野委員の質問に課長が答えています。大体どのぐらいになるのか」と質問したのに対して、「この数字で計算したものですけれども、当初予算で５億４,１３０万円ほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"提案","question":"６,４００万円の数字と、私たちが調べた１億４,０００万円の数字が違っているわけですから、そのことの確認を課長にまずお願いしたい。課長から、数字の違いの確認をお願いいたしますとの意見を述べました。","respondent":"谷田部児童課長","answer":"平成１３年度の１０月実施での試算ですので、そちらのほうの答えは、私どもはしてございません。そのときに、１０月実施を前提にしてのご質問と承ったんで、平成１３年度の予算でどう変化するかという内容です。","id":"exchange-030"},{"speaker":"鶴副委員長","kind":"提案","question":"どういうふうになっていますかね。伊藤委員の質問との絡みもありますけれども、提案者はルールを守る政党だとおっしゃっているから、改めて聞きたいんですとの意見を述べました。","respondent":"谷田部児童課長","answer":"「普通地方公共団体の長は、必要な予算上の措置が適確に講ぜられる見込みが得られるまでの間は、これを議会に提出してはならない」。それから、「その案件に伴って必要な予算上の措置が具体的に明瞭に取られる見込みのあることを言う」となっています。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"確認","question":"確認させていただきましたんですけど、提出するという通告みたいなものですね。でも、財源確保についてどうするかという協議はなかったと理解していいか尋ねました。","respondent":"小沼福祉事業部長","answer":"私はその場に同席しておりましたが、具体的な予算数値がどう、予算がどうという話については、私の知る限りでは、ございません。","id":"exchange-032"},{"speaker":"鶴副委員長","kind":"確認","question":"恒常的な予算ですから、どういうふうにやっていけばいいのかということまで、やっぱり責任ある政党としては詰めるべきだと、私は思うんです。だから、詰められたんですか、理事者と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"こういう条例を議員が提案できるというのは、それは条例提案権があるわけですから、当然。来年度の予算ですから、来年度の予算が提案をされているわけではありませんので、そのことに対して修正をするという時期ではないと考えましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"鶴副委員長","kind":"提案","question":"議員提出の条例の提案権があったとしても、予算を伴うものなんですよ、それについてはどうされたんですかということです。そうじゃないか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ですから、政策的にこれがほんとうに区民にとって大事だと、区民の願いにこたえるものだと、この委員会の中で皆さんのご賛同を得て、議会の中で判断をされれば、これは十分に来年度の予算の中で組んでいただける額と考えたということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鶴副委員長","kind":"質問","question":"理事者、そういうものですか、ものの考え方というのは。","respondent":"小沼福祉事業部長","answer":"見込みであるとか、私どもがそれについて対応するとか、私のほうでは考えてあります。","id":"exchange-037"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"今年度の予算に対する要望の中におきましては、当局から１０月実施の一部条例の改正がありまして、このときも全会一致で可決となりました。予算を伴う条例は提出されるべきではなかったのですかという入口論、そこに何らか瑕疵があったかなかったということについてお尋ねしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何ゆえ所得制限の撤廃をしないのでしょうか』との疑問や、『所得制限を撤廃してほしい』との強い要望が、私たちにも寄せられています。ちょっと理事者の方にお伺いしますけれども、例えば厚生委員会の中で、それを実施することはできないんか尋ねました。","respondent":"谷田部児童課長","answer":"その辺の一定の財源の手当て等を検討した上で、また議会のほうに戻すような手続が、たしか地方自治法の規定にあったと思います。これはやはり当然、バランスを欠くことができない部分ですので、その辺は十分執行機関としても考えなきゃならないと考えています。","id":"exchange-039"},{"speaker":"鶴副委員長","kind":"提案","question":"私は、鈴木ひろ子委員に、提案者に質問したのです。だから、やったのですか、やらなかったのですかって、私はさっから聞いているんですよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"質問に答えていただきたい。確認しているんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鶴副委員長","kind":"意見","question":"私ども、はるかに１億円を超える、１億５,０００万円近くになるのではないかと見ておりますけども。ご説明をいただけませんかとの意見を述べました。","respondent":"谷田部児童課長","answer":"それが、１０月の実施以降、１万１,５３６人になりまして、増加するお子さんの数は２,１１５人です。５億４,１３０万円ほどですので、お子さん全員を対象にした場合に、差し引き１億９,０００万円ほどが増えるです。","id":"exchange-042"},{"speaker":"鶴副委員長","kind":"質問","question":"１億円を超える財源となりますと、容易なことではない。５８年からずっと見直しておりますけれども、１億円を超える財源なんて見つかりっこないと思いますが、いかがか尋ねました。","respondent":"谷田部児童課長","answer":"行財政改革を進めながら、学童保育クラブでも人を見直しつつ、サービスの拡大をしているわけです。６５％で始まったものが７５％、８５％と、ひとつご理解のほどをお願いいたします。","id":"exchange-043"},{"speaker":"嶋委員","kind":"意見","question":"７５％、８５％と緩和していただいて、ほんとうに努力をされているということに対しては大変評価をしていきたいと思います。そういう意味で、あとの２,０３６人の方たちが一日も早くなっていかれるように努力をしていきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"須藤委員","kind":"質問","question":"２３区で所得制限があるなしで来て、その中で出生率の差異が出てきたりとか、少子化云々ということがあるのかどうか。そういう乳幼児、小さなお子さんたちに対しての対応というのはどんなものがあるのか、お知らせ願いたいと思います。","respondent":"谷田部児童課長、青山品川区保健センター所長、小沼福祉事業部長","answer":"１点目の、出生率と乳幼児医療費助成制度との関係は、ちょっと私どもは把握はしてございません。その中で、あるいは個別にご相談があれば、その都度、医師、保健婦、栄養士等が対応しながら、できるだけのバックアップをしてきているところです。… ２点質問がございましたけど、いわゆる第２種手当とか、第１種手当ということで対応をさせていただいている制度があります。","id":"exchange-045"},{"speaker":"須藤委員","kind":"意見","question":"それについてもいろいろな限度があって、品川区はこういう形で、現在やっている。カバーするシステムというのはいろいろつくられてこようかと思うんで、その辺をまた我々も大きな問題があれば、議会として出していきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"伊藤委員","kind":"提案","question":"確認だけさせていただきたいんですが、共産党の提案だと、約１億９,０００万円ということですね。私ども議会で議決して出したとして、そのことについて、区長のほうでどういうふうに考えていくんでしょうかということの意見を述べました。","respondent":"谷田部児童課長","answer":"ただ、地方自治法第１７６条に、その送付を受けた日から１０日以内に理由を示してこれを再議に付することができる」となっています。議会と執行機関との間でそれぞれ考え方が異なった場合には、そのような法律上の手続もあるということで、ご紹介させていただきたいと思います。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"提案","question":"議員提案条例でも何でも、品川区議会の名前がついて出るわけですから、予算執行されることを目的として提出するわけです。そういう無責任な条例を、私は、区議会議員としては出せないと思いますので、これは意見として述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一番初めに平成６年度に所得制限を外したときには、ぜひ、こういう点からもご検討いただきたい。品川区以外の２２区のすべての区が、ぜひ、このことをご検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-05","title":"平成１３年請願第７号、乳幼児医療費助成制度の所得制限の撤廃を求める請願","agenda":"平成１３年請願第７号、乳幼児医療費助成制度の所得制限の撤廃を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医療費と事務経費があると思うんですけど、それぞれどういうふうな金額になっているのか、教えてほしいと求めました。すみません、それともう１点、年齢別に受けられる率がどのぐらいになっているのかというところがわかったら説明を求めました。","respondent":"谷田部児童課長","answer":"それぞれ扶養親族数に応じて設定したということは、私どもで午前中にもご説明申し上げました。この１０月に８５％に拡大するわけですし、たしか午前中にもこれからの実施を待ってと申し上げましたので、８５％でこの１０月から実施をするです。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民にとってどういう生活ができて、なぜ乳幼児医療費助成が必要なのかという点に関しては、どう考えられたのかということについてお聞かせください。８５％をさらに９０％、９５％という形で拡大するということもあり得るのかどうか、このことについてもお聞かせほしいと求めました。","respondent":"谷田部児童課長","answer":"お子さんが１人の扶養親族２人の場合のケースでいきますと、総所得金額が６８０万円になりまして、８８８万円です。所得制限撤廃と同じような効果になると考えていますし、７５％、一定程度の福祉施策の線ではないかと思ってあります。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"資料を探していただいている間にもう１点お伺いしたいんですが、虫歯ですとか、疾病構造というのも随分変わってきているんじゃないかと思うんです。歯科にかかる割合、これが就学前までで、どれぐらいの割合になっているかというところがわかりましたら説明を求めました。","respondent":"谷田部児童課長","answer":"歯科につきましては、虫歯で１,０００人中１７.３人と、この資料では出ております。今の国民衛生の動向といいますのは、旧厚生省の外郭団体で調査した資料です。","id":"exchange-052"},{"speaker":"鶴副委員長","kind":"質問","question":"私たちがショックを受ける場合に、どういうときにショックを受けますかね。ショックというのは、どういうときに受けるんか尋ねました。","respondent":"谷田部児童課長","answer":"私の個人的なレベルでのお話をしますと、予想もし得なかったことが現実的に目の前に差し迫ったときに、相当ショックを受けると、私は考えてあります。","id":"exchange-053"},{"speaker":"鶴副委員長","kind":"質問","question":"例えば今回、先ほど説明があったように、６１４万円、年収８８０万円ですか、区の職員よりも上回る年収の方の場合、ショックを受けるでしょうかね。福祉政策の一つとして位置されているわけですから、ショックを受けるんじゃないかと思うんですが、どういうときにショックを受けますか。","respondent":"谷田部児童課長","answer":"所得制限なしで医療費助成が受けられたけども、品川区では、所得制限にかかって受けられなかったとか。その一つとして乳幼児医療制度があるということで、私ども、先ほど来、申し上げているです。","id":"exchange-054"},{"speaker":"鶴副委員長","kind":"質問","question":"何とかを無料にしろだとか、よく宣伝であるじゃないですか。だれが負担するんですかね、聞こえはいいけど。","respondent":"谷田部児童課長","answer":"一番大きいのは区民税を負担されている部分の一般財源で、たしか３割ぐらいを占めるわけです。一定程度の施策効果があるところに重点的に配分するのが、財政運営上、一番適した方法だと考えています。","id":"exchange-055"},{"speaker":"鶴副委員長","kind":"質問","question":"品川区保健センター所長がいらっしゃるので、もう１点、お伺いしたいんですけど、アレルギー疾患は大変だそうですけれども、医療費、治療費というんでしょうか、医療費というのは、普通の国民健康保険に加入している世帯で、大体どのぐらいの自己負担になるんでしょうかね。","respondent":"青山品川区保健センター所長","answer":"小児ぜんそくのような場合には、東京都の大気汚染条例に基づく医療費の公費負担がありますので、こちらは特段所得制限がありません。ただ、アトピー性皮膚炎については、そのような制度がございませんので、確かに個人の対応ということになるんです。","id":"exchange-056"},{"speaker":"鶴副委員長","kind":"意見","question":"医療費をいくらやっても、結局その恩恵が受けられないということになるので、別な手立てで支援策を考えないといけないという視点がありますね。そのことが、よくわかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"質問","question":"すべての品川区のお子さんを持つ家庭に対して、なくしてくださいということですから、これは相当議論が必要であろうと思います。ですから、また別な次元で議論していかなければいけないと思います。","respondent":"谷田部児童課長","answer":"４歳で７６％、５歳で７６％というふうに、小さい子どものほうが対象者の数が多い比率が高いです。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そのことがわかったら、教えていただきたいと思ったんですけれども、それはなかなか難しいですか。所得制限を撤廃するということが、品川区の若い人の年齢を増やすことになるんじゃないかなと思うんですけど、その点に関してはいかがか尋ねました。","respondent":"谷田部児童課長","answer":"最初に、いわゆる扶養者の年齢別の対象の数というのは、私どもちょっとデータを取っていませんので、お答えできません。決してそれだけではないですので、ご理解いただきたいと思います。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もしデータがわかれば出してほしいと求めましたけど、何千万円も所得があるという方はほんのごくわずかなんじゃないかと思うんです。品川区以外２２区がすべてやっているわけですから、そういう方向でぜひご検討ほしいと求めましたし、採択をしてほしいと求めました。","respondent":"小沼福祉事業部長","answer":"２２区がどうのこうのという前に、この乳幼児医療制度については取り組んでいるんだと、ひとつご理解をいただきたいと思います。それ相応の時代的な合理性があるものと考えていますので、所得制限を撤廃する考えは、今の段階ではございません。","id":"exchange-060"},{"speaker":"船波委員","kind":"質問・要望","question":"請願の趣旨や項目に直接的に関係はないんですけれども、ちょっとわからないところがあるので、教えていただきたいんです。初診料の支払いに関してのルールはどうなっているんか尋ねました。","respondent":"谷田部児童課長","answer":"同一疾病で同じところにかかれば、初診料は１回で済むはずです。ただ、診療科目が変わった場合、例えば同じ病院で、小児科にかかった後歯科に回るとかいう場合には、それ相当の初診料がかかります。","id":"exchange-061"},{"speaker":"船波委員","kind":"質問","question":"この１行に書いてある、同じ病院で診察を受けるんだけれども、違う症状で受けるときに取られるということなわけですね。別のところにかかれば、支払わなくても済むところもあるという違いが生じる問題ではないのではないかと思ったんですけど、どうなんか尋ねました。","respondent":"谷田部児童課長","answer":"今、考えているんですけども、同じ病院で診療科目が変わるたび初診料を取られるというのならわかるんですよ。ですから、ここで言っている、診療のたびというのは、診療科目が異なった場合に、それぞれ取られるという意味だったら、私ども、理解はできます。","id":"exchange-062"},{"speaker":"船波委員","kind":"質問","question":"でも、この請願を書いた方が、こういったことを書いてくるには何か理由があるのではないかと思うんです。料金を徴収する病院のほうで誤って徴収しているとか、そういうことがないかどうかチェックするとか、そういうことはないんか尋ねました。","respondent":"青山品川区保健センター所長","answer":"今申し上げましたようにいろいろ想像はできるのですけれども、健康保険の体系の中では、このようなことは、原則として起こり得ない。チェックがかかっているとお考えいただいてよいかと思います。","id":"exchange-063"},{"speaker":"嶋委員","kind":"質問","question":"鈴木委員がお聞きになっているいろいろな方の区民相談の中で、医療にかかれない経済状況があるんでしょうか、差別とおっしゃっている中には。ちょっとお聞きいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"もちろん、それは命にかかわることですので、病気がありながら、病院にかからないということはありませんけれども、ここに書いてあるように、かなり大変な中でそれを工面せざるを得ないという状況があるということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"嶋委員","kind":"意見","question":"私自身もいろいろな相談を受けて、個々に区に相談をするので、ぜひ、個々に区のほうに相談をと。その方が、ほんとうにちゃんと医療を受けられるようにしてあげるのが、私たち議員の務めだと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけなんですが、先ほど、たしか鈴木委員の発言の中で、所得制限をつけることで差別をしているというような発言がありました。そのことに対する明確な答弁をお願いいたします。","respondent":"谷田部児童課長","answer":"そう言いますと、社会保障制度は、すべて差別的なものの考え方に立って成り立っていると言わざるを得ないことになると思います。決して差別的な取り扱いを、残りの１５％のお子さんにしているというわけではないということは、はっきり申し上げておきます。","id":"exchange-067"},{"speaker":"須藤委員","kind":"質問・要望","question":"医療機関側がこれを見たら、非常に問題ありというような内容だろうと思うんで、初診料とは何ですかということを質問いたします。これから８５％の方がこういう状況になろうといったときに、そういう状況があるのかどうか、ちょっとお聞かせ願いたいと思います。","respondent":"青山品川区保健センター所長","answer":"３歳児検診なら３歳児検診、１歳６カ月検診なら１歳６カ月検診におけるその時点のアトピー性皮膚炎の有無を、たしか４％から６％ぐらいでした。","id":"exchange-068"},{"speaker":"須藤委員","kind":"質問","question":"初診料というものは、何で払うんですか。ですから、そういう状況であるということを、もう一度お願いします。","respondent":"青山品川区保健センター所長","answer":"一つの疾患についてかかっている限りは、その疾患が一応の決着を見るまでは、１回しか取られないものです。須藤委員、ご指摘のとおりです。","id":"exchange-069"},{"speaker":"須藤委員","kind":"質問・要望","question":"ちょっと委員会運営についてなんですけども、予定が、午後は請願の審査でしたよね。直接関係のない理事者は逆に行政に励んでいただきたいと、副委員長に、ぜひその辺もお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/723274?Template=document&Id=2990#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":45333,"voices":165}},{"id":"h13-20010702-8","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"建設委員会","time":"午前１０時１１分～午後１時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"随意契約にするための要件というんですか、もしその辺の背景がわかったら教えていただきたいということ。基礎杭というのはどうなんですか、コアの上に乗っかっているのかどうなのか、わかったら説明を求めました。","respondent":"岩田管理工事課長","answer":"路面覆工のリース材ですので、これは現場から鉄建公団でなければ工事ができないということで、随意契約ということにしています。通常の単独の施設のように杭を打ったり、そういうことをする必要がない構造で、俗に言う直接基礎構造というような構造の躯体になってあります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"７億円からの契約金額ですから、具体的にはどういう文言になっているのかなというのがわかったら教えてほしいというふうに考えたんですが。これとの延長なんですけれども、平成１４年１２月の開通に向けた工事の進捗状況がわかっていたら、うまくいっているかどうか教えてもらえますか。","respondent":"伊佐都市計画課長","answer":"この間の一般質問でもお答えしましたが、順調に進んでいるというふうに、りんかい線の対策会議の報告というものをもらいました。平成１４年１２月の開業に向けて、工事が最盛期を迎えておりますし、特に遅れていることがないように聞いております。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"りんかい線に係る区役所から大崎に行く間の夜間の通行止めというのは、相当長期間にわたっているんですけれども、あれはいつごろ終わるんか尋ねました。","respondent":"岩田管理工事課長","answer":"申し訳ございません。後ほど資料を取り寄せまして、委員のほうにご説明にまいりたいと思いますので、よろしくお願いします。","id":"exchange-003"},{"speaker":"辻委員","kind":"意見","question":"駐輪場の料金についてはどういう──これは多分鉄建公団に委託しているという形になろうかと思うんですけれども、自転車の料金とか。やっぱり、これからバイクも当然増えていきますので、この辺も配慮されているのかとの意見を述べました。","respondent":"岩田管理工事課長","answer":"まだ検討中ですが、先般駐輪場の条例を改正させていただきまして、２,５００円を超えない範囲内で料金設定はしてまいりたいということです。","id":"exchange-004"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、やはりバイクの需要というものをきちっとつかんでやってほしいと求めました。やっぱり自転車よりも若い人だったらバイクというのも、当然大きな流れかなと思いますけれども、その辺についてはいかがか尋ねました。","respondent":"岩田管理工事課長","answer":"ご説明をしますけれども、きちっと気持ちよく使っていただいて、それなりの応分のご負担をしていただくという有料化の考え方で今後は進めします。","id":"exchange-005"},{"speaker":"辻委員","kind":"意見","question":"最初、原付が結構並んでいると思っても、そのうち１台大きいのが入ると、次にはどおーとなる。需要予測というのをきちんとやっていかないといけないなと思いますので、その辺は調査してお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"築舘委員","kind":"意見","question":"自転車の駐輪場ということで、今度有料化するということで３００台ということですけれども、どういった形で現状があるのかと。今後２万人の乗降客が見込まれるということで、どういうふうな形で、今後の２万人のうち自転車を使って駅まで来る人の見込みをしていらっしゃるのかとの意見を述べました。","respondent":"岩田管理工事課長","answer":"それから、全線開業後の見込みですが、現在はこの資料のとおり、当面は３００台をきちっと収容できるような施設として見込んです。平置き部分をラック形態にして、もうちょっと高密度に詰められるようにして、将来は最大５００台まで収容可能な大きさの施設になってあります。","id":"exchange-007"},{"speaker":"築舘委員","kind":"質問","question":"やはり重要な駅の周辺ということですから、私も近くなものですからたまに通ったりしますけれども、ある程度自転車に対する整備というんか尋ねました。","respondent":"岩田管理工事課長","answer":"３ｍ以下の道路ついては、自転車は下りて押していきなさいという、法律上の規制にはなってあります。まだあそこは７割程度しか整備されておりませんが、今後の開発についても同じようにゆったりとした歩道空間の確保には努めてまいる所存です。","id":"exchange-008"},{"speaker":"横山副委員長","kind":"意見","question":"上がる人は、地方へ行くとそういった配慮がされているのを結構見るんだけれども、ここの場合はどういう想像をしたらいいのかな。その上、一方通行的な回り方を配慮してつくられている部分を見てきたんだけれども、ここの場合はどういう想像をしたらいいのかなとの意見を述べました。","respondent":"岩田管理工事課長","answer":"非常口という形で設置をする予定なんですが、ただ特に朝、一応Ｂ階段も午前中ぐらいは使えるような形で現在考えております。真ん中の欄が道路の縦断方向に切った断面図ですけれども、自転車を利用される方ですので、身障者対応というのはこの駐輪場は考えてございません。","id":"exchange-009"},{"speaker":"横山副委員長","kind":"質問","question":"そうすると、Ａ階段だけですか。要するに、下りる人はそのまま自転車に乗ったまま下りるかという、その辺のところも想像だけさせてください。","respondent":"岩田管理工事課長","answer":"したがって、下りる方は当然自転車を降りて、下りる方向に向かって右側のスロープをブレーキをかけながら階段で下りていただくという形になります。幅員ですけれども、階段部分の有効幅員が約２ｍで考えてあります。","id":"exchange-010"},{"speaker":"横山副委員長","kind":"質問","question":"下りる人は自転車から降りて下りられるようですから、車を持ち上げていくモーターのほうは、左右に欲しいという部分がある。さっきも言うように、そういった配慮をされて設備されているところはあちこちで見てきましたので、参考までにということで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"上山委員","kind":"質問","question":"どのぐらいになるような予定なんですか。平成１４年に公園工事が１４年４月ぐらいから始まるようになっていますけれども、その辺がどれぐらいになるのかということを伺えますか。","respondent":"北村下水道河川課長","answer":"こちらの工事の中で、その１、その２、その３という三つの工事が調整池の工事と、それに導きます下水道管の工事です。公園復旧につきましては若干来年度にずれ込むかと思いますが、これらの工事が完成しますと、水を取り込めるようになるという状況です。","id":"exchange-012"},{"speaker":"上山委員","kind":"質問・要望","question":"いろいろな工事があるかと思いますので、住民の要望がいろいろありましたら聞いていただいて、対応していただければなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"５０ミリ降雨を想定して、ある程度呑み込めるというふうになっているのか、そういうことをもう少し教えてほしいと思います。これを見るとポンプ場みたいなのが──わからないんですけれども、どうなるのかというのを教えてもらえますか。","respondent":"北村下水道河川課長","answer":"降雨との関係ですけれども、一般的に５０ミリ対応ということがいろいろ言われるわけですが、貯留の場合には若干違った概念になってまいります。戸越幹線の流域というのは５０ミリ対応ということで、５０ミリ対応と言いながら、なかなか実際に５０ミリの雨が降りますと。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"それの流出係数８０％というと、０.８掛けると約４,０００m3、この場合には２,４００ですから、約半分ぐらいと。平成１１年１１月２７日の３２ミリですか、余裕があるのかどうなのか、もう少しその辺の考えを教えてほしいのが一つ。","respondent":"北村下水道河川課長","answer":"計画上の降雨の考え方ですが、平成１１年１０月２７日の降雨は１時間にならしますと、確かに３２ミリという雨でございました。そういう短時間の雨であれば、それほど大きな容量でなくても一時的に貯留池があれば、ある程度救えるかなというような考え方で対応しています。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"例えば、こういうピークが二つある雨に対して、最初のところで入れたら、あとは全然──その辺の判断はどこがどうやってやるんでしょうか。何か自動的に呑み込むをやっちゃうのかどうなのか、ちょっと教えてもらえますか。","respondent":"北村下水道河川課長","answer":"その辺は設計上の考え方で、既設の管がある程度のめなくなったら、調整池に流入するような格好であります。かといって、その辺でかなりぎりぎりのところでのみ込める格好で、堰の高さとか人孔の構造を工夫しまして調節するような形になってあります。","id":"exchange-016"},{"speaker":"築舘委員","kind":"質問","question":"この水域権利者という方と、港湾管理者というのは、具体的にはどういった方々なんか尋ねました。","respondent":"北村下水道河川課長","answer":"それからそのほかに屋形船等の営業をされている方々ということで、占用許可を取ってあの地域に係留している方々等が約４名ほどいらっしゃいます。港湾管理者といたしましては、東京都港湾局になります。","id":"exchange-017"},{"speaker":"築舘委員","kind":"質問","question":"移転が大体整ったということで、どこに移転されていくようなことなんか尋ねました。","respondent":"北村下水道河川課長","answer":"説明資料の裏をご覧いただきたいと思いますが、赤で囲っております領域が今回の工事範囲です。Ｆ桟橋、Ｅ桟橋等の表記が小さくあろうかと思いますが、ここの突き出した護岸のところに順次移転していただくという形です。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"私、忘れちゃんたんですけれども、埋め立てしたところにさっきの貯留池をつくって、鮫洲幹線だか何かの、そういう計画がありましたよね。その計画全体に及ぼす影響はどのぐらいあると予想されているわけか尋ねました。","respondent":"北村下水道河川課長","answer":"下水工事の関係ですが、全体的な雨水貯留池関係の工事、平成１０年台の後半を目途に完成させるという形で進んです。８カ月程度確かに埋立工事は遅れてありますが、具体的な稼働時期がこれで遅れるとか、そういう状況にはまだ至っていないと理解しております。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"９月１日から受付開始というふうに聞いたんですが、共用開始というのはいつでしたか、９月１日からですか、ちょっと聞き落としたので。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"菅家委員","kind":"意見","question":"今、２３区の場合はこれだけの大きなスペースの新しい公園用地を取得して造成するのは品川区以外にないと思うので、公園関連のことです。従前なかったような気がするので、あとは各委員の問題提起を一つ一つ取り上げながら、調査対象を絞っていったらいいんではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"辻委員","kind":"意見","question":"今日、暦を持ってないので一概に言えない。今、言ったように、自転車の駐輪場というのは地下方式か、地方でものすごく──滋賀県でしたか、非常にユニークにやっていたみたいに……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"辻委員","kind":"意見","question":"ただ、するっとしか通っていないから、中がどういうのか細かいことは聞いていないんですけれども……。時期的に三定の終わった後ぐらいか、もう少し時間的に余裕があるので、もう少しそれぞれが情報を入手してやればという感じですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"横山副委員長","kind":"質問","question":"ですから、これからどういう形で流れていくかしらないけれども、それを網羅したもので一つのルートの視察先ができればなと。ですから、また新しい見方というのもあるでしょうから、去年はそんな形で委員会の行政視察を決定した覚えがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"沢田委員","kind":"意見","question":"それぞれの地方自治体の住宅政策を、どういうところがいいかどうかわからないけれども、どうやって進めているのかというのを見たい。これはテーマだけですけれども、場所は何とも言えないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"築舘委員","kind":"意見","question":"その後の復興がかなりなされてきていると思うんですけれども、その辺のところを具体的に参考になることがあればという感じはあります。まだ先の話なので、これからテーマが固まれば、それに則した形で私たちはいろんな分野で興味を持っておりますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"上山委員","kind":"意見","question":"ある意味ではどういうまちというか住宅問題で言えば、そういうところを視察できたらいいなと思っているんですけれども。その辺が視察の見方というか、考えで行かれるほうがいいかなと、私自身はそう思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"菅家委員","kind":"質問・要望","question":"だから、その辺をよく協議しながら、大体日程の関連については２泊３日ぐらいでしょうから、そんなにとんでもないコースは考えられないわけですよ。そういう意味では、その辺の何か資料を取り寄せて、さらに目を通して視察場所を決めるというような手順だけは決めておいていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"横山副委員長","kind":"質問・要望","question":"あれだったものですから、もう少し絞ってもいいかなという、それは後からの部分ですけれども。これだけ大勢の委員ですから、もう入っちゃったなんていうような形だと困るので、その辺もあわせてやっていかなくちゃいけないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"沢田委員","kind":"意見","question":"それを勘案しながら、正副委員長でこんなものでどうかというもの出してもらえれば、そうみんながみんな全部やったらぐちゃぐちゃになっちゃうものね。どこかに絞ってやるしかないし、ある程度方向性は同じ方向にしないと、ある程度限定されることはしようがないですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/428096?Template=document&Id=3692#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":24571,"voices":84}},{"id":"h13-20010702-9","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"文教委員会","time":"午前１０時１０分～午後０時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"の(1)平成１３年度「通学区域の弾力化」に関するアンケート調査結果につきまして","agenda":"の(1)平成１３年度「通学区域の弾力化」に関するアンケート調査結果につきまして","exchanges":[{"speaker":"高星委員","kind":"質問","question":"私どもも地元のほうにも同じ内容だと伺っておりまして、丁寧に出していただきました。その辺のところはどういうふうに、１年経過して総括をされているのかということだけは一番気になるところですので、お聞きしたいと思います。","respondent":"久保田学務課長","answer":"３月にはプラン２１フォーラムということで発表会も行いましたけれども、持ち味をつくろうと思ってそれぞれ努力した結果が、いろんな生徒の反応。","id":"exchange-001"},{"speaker":"高星委員","kind":"質問","question":"プラン２１フォーラムについては、現場における校長を初め、主事の隅々まで，現場の方々の声をどう把握されているのかをお聞きしたいと思います。","respondent":"青木指導課長","answer":"それぞれの学校のプラン２１の取り組みにつきましては、校長先生方から私ども、それぞれの学校の取り組みについてはその都度お伺いをしております。","id":"exchange-002"},{"speaker":"川西委員","kind":"質問・要望","question":"１点だけ伺わせていただきます。１点だけ伺いますけれども、これは小学校はまだ登録制ですから、そのことを指して言っているんだと思います。","respondent":"久保田学務課長","answer":"安全性を考えると、一気に４０校全部選択してはどうかと言っても、１０校程度がいいだろうと４ブロックに分けたわけです。率直な区民の皆さんのお考えはということで、より区民の意向に沿った形で今後検討を重ねていきたい、こんなふうに今のところ考えております。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"小学校を選択するときは、本人じゃないですからね。１％ぐらいは、それでも学校は特色ある学校づくりのためには、学校間としても行き来できるのかどうかという面はどうか尋ねました。","respondent":"久保田学務課長","answer":"冒頭若干ご説明をさせていただきましたけれども、昨年のアンケートで一番学校の情報を得たということで高かったのは、トップは友人からの情報です。入学説明会もしかりですけれども、その上で、このアンケート結果に一定程度反映してきたのかなというふうには思っております。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"中学校によっては大きく影響というんでしょうか、選択制によって、これまで少しずつ減少ぎみの学校が多く出る。例えば学校への指導というんでしょうか、選択制のもたらした結果によっての多く変化を受けた学校への指導というのはどういうふうにされていますか。","respondent":"久保田学務課長","answer":"それぞれの学校が自分たちの今までの取り組みをそれぞれ毎回見直しをする中で、新たな課題なり、大きく学校もまた変わっていくだろう。そのための指導というか、私どもの支援というのも、今後ますます努力していきたい、こんなふうに今考えているところです。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"実際に親が学校に求めるものと、どこに親が学校に何を一番求めているのかというところの違いが、そこら辺をちょっとお聞かせほしいと求めました。どういうふうな影響を持っているかというのを、もうちょっと分析されていくのが必要だと思うんですけれども、いかがか尋ねました。","respondent":"久保田学務課長","answer":"少なくともアンケートの中を見てみますと、親自身は教育活動の内容とか、あるいは教職員の熱意とか何かに非常に高い関心を持っている。それは最大限評価して、そういうものに対する支援を続けていくというような立場だということです。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"そこをどう支援をしていくのかというのが、ある面では地域の親の期待に応えるものではないかというふうに思うんです。私はそういう視点を持っているわけですけれども、それについてのコメントをほしいと求めました。","respondent":"青木指導課長","answer":"ここにダイナミズムを感じて、それでどうしても小規模校より大規模校のほうがいいんだというような、そういう認識を持っていらっしゃる。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"もう１点は、参考のために、「あなたは、どのような方法で学校の情報を得ましたか」という質問の中で、その他とあります。小学校と中学校で多少違うみたいですけれども、どういうものがあるか教えていただけますか。","respondent":"久保田学務課長、青木指導課長","answer":"まだ新しい特色づくりの展開という形で検討をしていかなければならないところもあったのではないかなというふうに思っております。新たな課題として、三つほど作業部会を設けてまた検討をしていくというふうになってありますので… ある課題について改めて作業部会を設置して、その課題について検討をするというような形で、５月からスタートをさせた作業部会があります。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"３点の作業部会の話が出ましたけれども、この作業部会の内容は、全体に一律にこれから現場でやっていくということですか。２番目の期待感が薄くなってきた、人間対人間ということの深みのふれあいというんですか、その辺に対してはどういう指導をされているか。","respondent":"青木指導課長、久保田学務課長","answer":"見込みですが、この作業部会は来年度のプラン２１の推進に当たってのベースをつくっていくものですので、その予定で今進めているところです。その先生を慕って、先生方を求めてというのは… 生徒の５番目の質問のところの、その他ですけれども、私は答弁を漏らしているところがありました。","id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"どうしても行かなければいけないからと言っている子どももいると思うんです。人の情報提供がより一環教育にもつながっていきますけれども、そういう指導といいますか、そういうことに対する今後の考えはいかがか尋ねました。","respondent":"青木指導課長","answer":"中学校の先生の指導を小学校６年生が受けて、中学校への期待感というのをふくらませていくというような行事をやっております。そういう体験入学とか、そういう経験を通して子どもたちは中学校の選択というものを実際に体で感じながら行っていけるというふうに考えております。","id":"exchange-010"},{"speaker":"山路委員","kind":"意見","question":"体験入学で、いい先生だ、私はこれを目指そうという子どもは出てくると思うんです。それで結構なんですけれども、子どもの能力を引き出すということで、情報量をもっと豊かにということを、最後にお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そっちに受験を振り向けちゃって、中学校はそこまで考えていないよという意味でとっちゃっているんでしょうか。そこら辺がちょっと気になるんですけれども、その２点お伺いいたします。","respondent":"久保田学務課長、青木指導課長","answer":"去年の指定校変更の数は９６件あったんですけれども、今年は９２件ということで、大体同じような数になってあります。いわゆるこれがまさしく７０％ぐらいが堺目ですので… 選択する親御さんが少ない、親御さんは中学校の中で望んでいないのかということですけれども、もちろん大変関心はあるかと思います。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"４ブロックのままでいいのかなという感じもしました。ちょっとお聞きしたんですけれども、全く問題はないんですけれども、ちょっと気になったのでお聞きしたわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問・要望","question":"それは学校に求めるもの、そのときの状態で違うと思うんですけれども、２３％の子どもたちが部活動の状況を見て学校を選んでいる。もっとここに人を集めたり、教師を集めればいいと思うけれども、その辺どうか尋ねました。","respondent":"青木指導課長","answer":"こういうような問題を少しでも解消していきたいというふうに考えているところで、この部会でも同じような課題を追求しているところです。そういうものも配慮して、今までももちろんですけれども、これからも十分にその配慮をしていきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"今のお答えを伺って、現実的にプラン２１の中で、部活に行っていないんじゃないかという声もすごく多いんです。もっとそれを地域の人たちを取り入れるとか、先生ができないんだったら、地域の人々をどんどん入れるとか、そのような考えはどうなんか尋ねました。","respondent":"青木指導課長","answer":"外部指導員というような形で実際にそういう技術を持っている地域の方たちに部活動の応援をしていただいておるという現実はあります。そういうような形で、技術は外から指導をしていただくとか、そういうことは現実的に今進めているところです。","id":"exchange-015"},{"speaker":"川西委員","kind":"質問","question":"これらは文教委員会には参考資料としていただけないのでしょうか。もう一つは、警察署への各施設からの緊急通報装置の設置を開始したということですけれども、どんなものか。","respondent":"青木指導課長、鷹倉庶務課長","answer":"１点目の資料ですが、非常に細かい点なんですけれども、委員会として必要であるということであれば、ご準備します。私ども２９日付で東京都の教育庁から、こういう形でプレス発表をするのでという形で、大綱がまいっております。… こういうものにまとめられるわけです。","id":"exchange-016"},{"speaker":"川西委員","kind":"質問・要望","question":"２番目の通報システムについては、２９日、文教委員会にも係るので。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"我々も勘違いしていたのではないかという認識があるものですから、門を一つにするということは、私は結構だと思うんです。そういうことがなくならないというんでしょうか、中には教職員がやって、ＰＴＡはやっていないというところがあるんです。","respondent":"青木指導課長","answer":"それぞれの条件、実態に応じて対策委員会を通してそのローテーションとか、その具体的な対応とかを考えていただいておるところです。現在、学校は何人とかというような数字では今ここでできませんが、それから地域の方たちとの協力体制をつくりながら進めていることは事実です。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"こういう資料が出されているんですから、こういうふうにしましょうと、もうやっているわけですよ。教職員、ＰＴＡとかでやっていると思うので、その数字はどうですかというのは分かっていなくちゃおかしいです。","respondent":"青木指導課長","answer":"既にそれぞれの学校からの学校安全対策委員会の構成メンバーと、実際の活動内容、検討内容ということについては取りまとめてあります。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"ＰＴＡに任していたらどうですか。結構気にして聞いているので、その辺の考え方をお聞きしたいと思います。","respondent":"指田教育次長","answer":"学校にそんなに余裕があるわけでありませんから、その中で考え、なぜそんなＰＴＡばかりに任すんだという反対のご意見というのもあります。近々のうちに校長会がありますので、そこで再度徹底をしていきたい、このように考えております。","id":"exchange-020"},{"speaker":"桜井委員","kind":"質問","question":"こういう事態に至らないまでも、学校で危険まで至らなくても、侵入のケースというのはなかったんでしょうか。それで、まず教育委員会としては、こういう姿勢を示します、人的配置も一緒ですからね。","respondent":"鷹倉庶務課長","answer":"これから非常に注目して、従来の学校のあり方という基本的な流れは大きく変わっていない、このように認識しています。したがって、定数問題について凍結するという考えは持ってございません。","id":"exchange-021"},{"speaker":"桜井委員","kind":"質問","question":"いろんな形での、学校だけでなくて、児童へのそうした命を奪うみたいな事件というのは結構ここのところ頻繁にあるじゃないですか。そこのところはどうなんか尋ねました。","respondent":"指田教育次長","answer":"１点目の侵入の事件があったかないかというところですけれども、どこのところで尺度を持つかというのは非常に難しい。したがって、そういう報告がない以上、今のところは「ありません」というふうに答えるしかないというのが、１点目です。","id":"exchange-022"},{"speaker":"桜井委員","kind":"質問・要望","question":"トイレだってきれいに掃除することは、当然子どもたちにとって一緒ですからね。大事なことを、今までの方針上はあるけれども、そういうことを横に置いてでも、この期間大事な体制をとるということを強く求めて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"校長先生に聞いたところ、「動揺はないですよ」という話も伺っているんですけれども、本当に大丈夫なのかなというのが一つあると思います。それについてちょっとお聞きしたいと思います。","respondent":"青木指導課長","answer":"今委員のおっしゃるように、学校でいろいろな取り組みをしておりますけれども、子どもたちが動揺しているとか、不安に陥ったとかというような報告は教育委員会のほうにはございません。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１点は、ある程度薄めなければいけないのかなというところと、そこら辺はどういうふうに判断なさっているか。今後の緊急体制、先々のということで、その辺を教えてほしいと求めました。","respondent":"指田教育次長","answer":"いろんな対応が考えられるとは思います。それから出入り口を１カ所にしよう、便宜的な対応というのは、今の当面考えられる対応はしてきています。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今までの話の中で十分分かりますけれども、あくまで児童・生徒の安全性と同時に、精神的な面に影響のないような形に進めていただきたいなと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"高星委員","kind":"質問・要望","question":"その辺のところで施設開放の係の人はどういうふうな位置づけになっているのかということをお聞かせほしいと求めました。最初の質問は細かいところですが、後の質問は大きなところで、しっかりとした決意をお聞きしたいと思います。","respondent":"指田教育次長","answer":"こういうふうな願いの中でもって一応私どものほうではご説明をしていますけれども、直ちに、じわじわきいている部分もあるかと思います。","id":"exchange-027"},{"speaker":"高星委員","kind":"質問","question":"子どもたちが完全に萎縮しちゃって、もともと品川区が考えているプラン２１、そういったものに大きなマイナスになってしまうのが怖い。こうせえというものは現実的に出しにくい状況の中では、我々もこれから先協力しながら、我々も意識しながら目を向けていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"山路委員","kind":"確認","question":"意見が出ると思うんですが、そこを最大のフォローをしていくという、その確認をしたいと思います。こういう点はすべて協力してフォローしていくというものは当然あると思うんですけれども、それについてのお考えを説明を求めました。","respondent":"指田教育次長","answer":"東京都の施策も、あるいは国の施策も、この後まだ出てくるというふうに私どもは認識しております。総体として、ケース・バイ・ケースに応じながら対応していきたい、このように考えております。","id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"今までの答弁で何回も出ましたよね。現場での学校安全委員会、スピーディに、現場での学校安全委員会を最大にフォローしていっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった教育行政を要望したいという意見が一つあったのと、機械化、学校安全をよく知っていた現業職の役割は大きい。人的なもので足りているのかどうかというところで、この２人の方の見解に対して、どういうご意見をお持ちかということを伺ってみたいと思います。","respondent":"指田教育次長","answer":"やはりそこにあるのは、地域の中の学校だということを再認識してほしい。いろんなお考えをお持ちの方はいっぱいいると思いますけれども、私どものほうでは、直ちに人を付けるという考え方はないということです。","id":"exchange-031"},{"speaker":"飯沼副委員長","kind":"質問","question":"私は何人もの方から伺っているのは、自分が行けない分をほかのお母さんに頼んで役をやっていただいたり、やりたくてもやれない部分もある。総合的に考えていく必要があるのではないかなと思うんですけれども、その点、再度お伺いいたします。","respondent":"指田教育次長","answer":"そのぐらいの気持ちを持って今回の安全管理というものを考えるべきなんです。保護者会、万難を排して出てくるのが当たり前じゃないですかと、私は強く言いたい。","id":"exchange-032"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これからずっと求めていかなくちゃいけないといった意味では、長期的に安全が確保できる部分が必要だと思うんです。だから、私は、とにかく人為的なものもタブー視しないで、視野に入れて総合的に検討をしていただきたいなということを要望して、終わります。","respondent":"指田教育次長","answer":"ちょっと感情的になって申し訳ありません。都から出てくる意見等も参考にしながら、今日の委員会のお話というものを十分承ってまいりたいと、このように思ってあります。","id":"exchange-033"},{"speaker":"桜井委員","kind":"質問","question":"質問するのは明日ですよね。今日は通告だけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"高星委員","kind":"質問","question":"どういう中身でやるのかわからないけれども、我々は何の資料もなくて、蚊帳の外で聞いていてもつまらないような気がするんです。もしその部分で、我々が蚊帳の外に置いておかれないような資料はきちっと出してもらわないとというふうに思うんだけれども、いかがなものか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"川西委員","kind":"質問","question":"先ほどご答弁の中で出たので質問をしたいと思っていたんですが、施設開放で、シルバー人材センターに頼んでおりますけれども、体育館等の一般開放をしまして、その清掃はどこが担当しているのか。","respondent":"南生涯学習課長","answer":"校庭、体育館等の使用後の清掃ですが、基本的には使った方たちがマナーの範囲で片づけていただくということになっております。","id":"exchange-036"},{"speaker":"川西委員","kind":"意見","question":"教頭なのか、校長なのか。施設管理という教員がいらっしゃるのかどうかとの意見を述べました。","respondent":"南生涯学習課長","answer":"基本的に私ども校庭、体育館の開放を行っていますのは、スポーツが中心です。マナーの悪い団体等があれば、私どものほうに連絡をいただき、私どものほうで利用者の方にご注意申し上げるというような形をとっております。","id":"exchange-037"},{"speaker":"川西委員","kind":"質問・要望","question":"１点だけ要望いたします。来れば、運動ですから、ほこりが脇のほうへ踊る。","respondent":"南生涯学習課長","answer":"現在、学校の開放はスポーツ、レクリエーション推進委員会ということで、地域の体育指導員の方等を中心にした利用調整会議を設けておりますので、その利用調整会議の場でマナーの徹底ということを図ってまいりたいと思います。","id":"exchange-038"}]},{"id":"topic-02","title":"３番目の行政視察につきまして、これから皆さんで協議をしていきたいと思いますので、関係者の方、次長は協力いただいて…","agenda":"３番目の行政視察につきまして、これから皆さんで協議をしていきたいと思いますので、関係者の方、次長は協力いただいて…","exchanges":[{"speaker":"桜井委員","kind":"提案","question":"２点提案したいと思います。未来ある２１世紀、内容面と、ハード面との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"川西委員","kind":"意見","question":"そういうセンターをこれからの教育は学校教育だけではだめね。文化活動ができるような施設をと思っているので、行きたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"意見","question":"プラン２１はすごく重要な問題になってくるんですが、２１世紀に向けた校舎の改築という問題もありますので、具体的なものは今は持っていません。ではどういう実体があるのかと、何か勉強してみたいという、３点を自分は考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"松澤委員","kind":"意見","question":"鈴木委員も川西委員のも賛成です。それについてコメントを出していただいて、もしそうでしたら、もっと多人数学級と両方見ないといけないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"山路委員","kind":"意見","question":"特色の面でも、いいところがあったら、そこを。もう一つは、ＩＴ関連の学校の先進自治体を見てみたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"高星委員","kind":"意見","question":"ただ、桜井委員に歯向かうわけではないですけれども、少人数学級の関係について、プラン２１品川も先駆的にやっているところは尊重すべきだと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"山路委員","kind":"意見","question":"子どもも、大人も、障害者も、健康人も、みんなが動物とともにふれあうセンターがありますし、自然を生かした教育もあります。今出ませんでしたので、それを一つつけ加えておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"川西委員","kind":"意見","question":"いろんな問題を、その人たちが地域でどう学校と係わっているのか。調査項目にお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/605950?Template=document&Id=4408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":38237,"voices":105}},{"id":"h13-20010702-5","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"総務委員会","time":"午前１０時０４分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"の第６５号議案、総合庁舎受変電設備改修工事請負契約","agenda":"の第６５号議案、総合庁舎受変電設備改修工事請負契約","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"設備を更新することによるメリットというのを何点か教えてほしいんですが、大分古いものですから、それが相当額減るのかということ。２点をお願いいたします。","respondent":"西島経理課長","answer":"かなりクラシカルな機械で、今度、そういう部分での人については若干減ることが想定できるのではなかろうかというふうに考えております。それ以外にいろいろなものが出てくるかと思いますが、それは今後の中でまた考えていきたいというふうに思ってあります。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういうものですから、ある一定以上古くなると、非常にメンテナンスにお金がかかり始めるわけです。それはいいんですけれども、人の部分はもう少し考えたほうがいいんじゃないか尋ねました。","respondent":"西島経理課長","answer":"次に平成１４年度の契約のときにはその辺も考慮して、その部分は削って契約するという形になろうかと思います。新しい機器になりますので、委員ご指摘のとおり、平成１４年度の契約のときにはその辺については考慮していきたいというふうに考えております。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"行政評価システムを取り入れているわけですから、２億9,０００万円のお金をかけるわけですから、今の答弁以上にいただきたかったなということを指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"外側のところで伺いたいんですけれども、もっと使えそうだということになれば、耐用年数が過ぎていても使うなどという場合もあろうかと思うんです。そういうところもちょっとお伺いできればと思います。","respondent":"岡田施設課長","answer":"これがが昼間の執務時間中にバタンときたときに、恐らく１日ぐらいではとても回復できないという状態が起きる可能性があります。このような状況です。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"ちなみに、今度新しく入れる機械は耐用年数はどのぐらいなんか尋ねました。","respondent":"岡田施設課長","answer":"やはり２５年から３０年というのが一つの目安かなと思います。ですから、部分的の更新は必要かと思います。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"どういうものをやるか、そういう総合計画といいますか、そういうものというのは何かあるんでしょうか。あったら、教えていただければなと思うんです。","respondent":"西島経理課長","answer":"ただ、状況を見ながらということで、例えば今年ですと、庁舎の外壁の修繕を３カ年計画で行うようになっております。あるいは鉄筋は５０年というふうに言われておりますけれども、あるいは電話交換機、このものを少し運営していきたいなというふうに考えてあります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"これだけのメリット、それから，社会的に理由がつく，そういうことを考えていくべきだと思うんだけど、なぜそんなことを執行部が許すのか。それの意識の部分を聞かしてほしいのと、どこかへ行くと、新しいコンピュータ等の機械で監視・操作できるとの意見を述べました。","respondent":"本間総務部長、岡田施設課長","answer":"そこの部分につきましては、当然新しい機械に合った、新しいものにふさわしいメリットを出すべくきちんと対応をさせていただきたいと思います。今ご指摘を受けました点を十分配慮しながら… ここが５億5,０００万円ぐらいが電気工事の契約金額ですが、このうちの大体１８％、約１億円ぐらいが受変電設備関係の費用になってあります。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"一つだけ確認をしておきますけれども、これがそういうものに当たるのかどうかわからないけれども、電話をかけるのも電気が必要だ。向こう３０年にかかってくるものだけれども、耐えられるということで理解しておいていいのかどうか、聞かせてください。","respondent":"岡田施設課長","answer":"向こう３０年ですけれども、恐らくこの古いのも、３０年経った今でもまあまあ持ちこたえているわけです。容量はたっぷり持っておりますけれども、その年々の使った量によって契約できる、こういう方式です。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の改修でいろいろなメリットがあるというふうに伺ったんですが、スペース的な面でのメリットというのはないんでしょうか。容量的な部分は対応を考えていらっしゃるということを伺ったんですが、設備的なものが対応できているのかどうか、お聞かせほしいと求めました。","respondent":"岡田施設課長","answer":"３０秒なり４５秒で電気が立ち上がる、こういう部分は受け持っております。個々の機械、あるいは情報処理課で扱っております大型のＯＡ機器については、それぞれが瞬間的に停電を防ぐ装置が組み込まれております。","id":"exchange-009"},{"speaker":"北野委員","kind":"質問","question":"非常用としてなると思うんですけれども、全然わからないんですけれども、今は重油じゃないという動きがあるんでしょうか。それから、４０００ｌというのは、既に溝があるところに新たにつくるんか尋ねました。","respondent":"岡田施設課長","answer":"この４０００ｌを使って２５時間ぐらい、丸１日ぐらいは動く。４０００ｌで、丸１日間ぐらい動くと、このようになっております。","id":"exchange-010"},{"speaker":"土井副委員長","kind":"意見","question":"さらに、もう一つ言えば、なぜ３カ所なのと。４カ所目ができて、渡り廊下ばかりがつながっているということになりかねないんですけれども、その辺のところはどう検討をされてきたのかとの意見を述べました。","respondent":"岡田施設課長","answer":"これをやった最初の時点でもいろいろ検討して、１カ所で送るよりも、そのほうがメリットがあると。現在も検討をしましたけれども、やはりそのほうがメリットがあると。","id":"exchange-011"},{"speaker":"土井副委員長","kind":"質問","question":"何カ所かになりますと、この変電室と向こうの変電室というものの性質の違いから、いろいろ途中がわからなくなるというのがよくあるんですね。統合的にうまく考えていっていただかないと危ない部分があるなと思ったものですから、メンテナンスも含めて起こるので、ご検討のときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"の第６６号議案、臨海副都心線天王洲アイル駅自転車駐車場設置工事委託契約","agenda":"の第６６号議案、臨海副都心線天王洲アイル駅自転車駐車場設置工事委託契約","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"どの部分にどれだけのお金がかかるということが、もう決まっているのかどうか、そこをまず教えてほしいということ。協定が８月で、品川区の負担ですよというふうに最初からなっているということで理解していいわけか尋ねました。","respondent":"岩田管理工事課長","answer":"私のほうからご説明申し上げます。区の費用ですけれども、残りの２分の１のうち、約４分の１程度が都市計画交付金として都からくる予定になっております。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"金額のことは後々見積もりをやって、後でこの部分は品川区の負担ですからお願いしますという話になっているのかなということを知りたかったのが一つ。それから、この部分は品川区の負担ですから、後ほど自転車駐車場として設備の部分は後ほどまたお金がかかってくるのかということを聞かせてください。","respondent":"岩田管理工事課長","answer":"妥当な金額であるということで、現在は覚書を締結いたしまして、この金額について了承しているです。７億5,０００万円の中には、それと、駐輪施設用のラック等の機械設備もこの中に入っておるわけです。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"駐輪場に関してはもうお金は出ていかないというふうに理解していいんですね。結局お金を払うわけですから、これ以上高いこの見積もりはいかがなものかというやりとりは実質しているのかどうかということをお聞きします。","respondent":"岩田管理工事課長","answer":"その他の事業がいい加減ということはございませんけれども、当然のことながら、詳細につきましても十分第三者の目に耐えられるような積算内容になっているかどうかチェックした上で契約を結ぶことになってあります。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"３００台というのは、大体全部収容可能なのかどうかなのかという、そこら辺の見通しはどうかなと思うんです。いい駐輪場をつくっても、全部使えるかどうかとなると、そこら辺の見通しというのはどんな感じか尋ねました。","respondent":"岩田管理工事課長","answer":"通常、こういった場所で有料駐輪場を設置いたしますと、約７割から８掛けになります。将来、利用車が増えるときには、ラック等を増設いたしまして、最大５００台まで収容可能な空間の建物に計画をしています。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"平成１２年７月、８月あたりから駐輪場についての協議をしてきているんだけど、今どういうふうになっているのかということ。どういうあれだかわからないんですけれども、総合的に、三者でというのはなかったか尋ねました。","respondent":"岩田管理工事課長","answer":"自治体のほとんど１００％負担でこういった駐輪場を建設、運営をせざるを得ないというのが現状です。ただし、例外的に品川区内では東急線の中延駅で東急用地で東急自らが有料駐輪場として経営しているところがあるです。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"お金を出してほしい、そうしますと、３００億円からの金を出した経緯がありますよね。ちなみに、３００台の自転車駐輪場をつくるとしているが、今品川区で有料駐輪場で一番台数の多いところの費用は幾らぐらいかかっているんか尋ねました。","respondent":"岩田管理工事課長","answer":"大井町の旧イトーヨーカドーのところの北側の区有地のところで区が民間に土地を貸しまして、そこが１００％民間の有料駐輪場としてやっております。ですから、品川区がお金をかけて有料駐輪場というのは今のところございません。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"品川区で比べられなければ、民間と比べるという、今はそういう時代なんですよ。大井町の駅前で、民間では、どれぐらいの建物数で、何台入っているんか尋ねました。","respondent":"岩田管理工事課長","answer":"今手元に資料がございませんので、調べまして、後ほどお答え申し上げます。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"もちろん駐輪しやすい利用料はそういう値段を設定していくんでしょうから、おそらく永久にペイはできないというふうに考える金額ですよね。そういう話し方をしていって、鉄道利用料というのが入っていくわけですから、そういうことはやっていくべきだと思うんです。","respondent":"岩田管理工事課長","answer":"復旧を約１年以上待って、こういったものは臨海鉄道のほうで負担をしていただくということで、それなりの協力はしていただいております。この辺が対ＪＲ関係とは違うところでございまして、今回はかなりの協力をいただけたです。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"確認","question":"さっきの建設費というか、それと合わせて、ちなみにどのぐらいの収入が上がるのか、見込みだけでも結構ですから、それを。新しい駅はできないと思ったけど、灯台もと暗しで、一番近いところに新しい駅ができるので、確認しておきます。","respondent":"岩田管理工事課長","answer":"１０月１日から区が有料化をしていこうという大井町と大崎につきましては、現在施行規則の改定作業を進めておりまして、現在検討中です。そういう中では、東急とりんかい線の乗り入れ等も考えましても、大井町については十分持ちこたえられるという計算を現在しております。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ここにつくったらどうですかという要望もしていくぐらい、相手のあることで、姿勢だけは強く持っておいてほしいと求めました。さっきの数字は後で教えてくだされば結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"土井副委員長","kind":"質問","question":"ちょっとお伺いしたいんですけれども、自転車を置くときは平場に置くのが一番簡単で、上でも下でも、動くと置きにくいんですよね。ここは何でこんなに深いんか尋ねました。","respondent":"岩田管理工事課長","answer":"したがいまして、道路下空間をある一定区間構造物の設置はできませんので、それで下がっております。これは道路空間として埋設物等が駐輪場の上の空間にいっぱい入っておりますので、やむを得ずここの位置になったです。","id":"exchange-023"},{"speaker":"土井副委員長","kind":"質問","question":"ここだけじゃなしに、いろんなところのときに埋設物は今まで入っていたものはそのままよと。動くのはいやだよというようなことであるならば、また改めなければいけない部分もあるのかなと思いますので、そんな問題ではないんか尋ねました。","respondent":"岩田管理工事課長","answer":"長さが４５ｍにわたって構造物ができるわけですので、ある一定空間はそういった構造物はそれより下に設置しなさいということで従来も、こうせざるを得なかったです。","id":"exchange-024"},{"speaker":"土井副委員長","kind":"質問","question":"共同溝的な発想というのは、そういうときには起こらないものなんですか。話はちょっと違いますけど。","respondent":"岩田管理工事課長","answer":"ここの道路の場合は共同溝という話は、私どものほうにはきておりません。この横の海岸通りのほうが国道が設置します共同溝の計画、歩道側にミニ共同溝のようなものか、ライフラインの共同溝という話はございません。","id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"これはいいねという話になって、こういうようなものをつけたほうがいいんじゃないかという話になったんですけれども、そういう形というのはどうなったんか尋ねました。","respondent":"岩田管理工事課長","answer":"地図が小さくて申し訳ないんですが、基本的にはメインの出入り口はＡ階段のほうをご利用いただく予定です。それの反対側が下り用のスロープです。","id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"確かにそういうお話があったなということが、今お話を伺っていて、そういうようになったということで安心しました。よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"の第６７号議案、中継作業用コンテナの買入れ","agenda":"の第６７号議案、中継作業用コンテナの買入れ","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"金額は２億9,１９０万円と書いてあるんだけど、こっちの９ページのほうの表の中の見積もり価格は２２億7,８００万円と書いてあるが、１台単価というのは出てこなくていいわけか尋ねました。","respondent":"西島経理課長","answer":"１０ページに購入価格とございまして、５５６万円掛ける５０台掛けるというふうに記載しています。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"１台５５６万円もするんですか。言葉がないんだけど、こんなに高いものなんか尋ねました。","respondent":"西島経理課長","answer":"私も聞いてびっくりしたんですけれども、定価が６９０万円。平成６年度、平成７年度に買入れをしたときに、消費税は別ですけれども、東京都は５７０万円ぐらいの金額で購入をしたということがあります。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"独占企業なんですか、そんなに特殊性があるとは思えませんけれども、その辺をちょっと説明していただけますか。","respondent":"中山清掃リサイクル課長","answer":"それと、先ほど来ご説明もあったような、万が一の臭気、あるいは液状の漏れがあっても海洋汚染、あるいは近隣の環境も害してはいけないと。こういったものが価格に反映されているのではないかというふうに認識しています。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"意見","question":"３０分だというんだから、車が走るのと比較して、たいして変わらないで大田区に行ける。完全に違うんだろうけれども、平成１８年にはこういうものは廃止して、車で運送をするんだという考え方ができるかどうかだけ聞かせてほしいとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"現地でもご説明がありましたけれども、最近では６割ぐらいが希望が丘中継所、世田谷区から直接大田工場に持っていく。ロシア船２隻であれだけのものを運べるですので、一番ベストな選択だということで、船の構造が決められたのではないかと認識しております。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"意見","question":"船は１０往復増やせばいいというふうになれば、果たして効率はどうかな。これから先の問題なので、我々も検討を加えていきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"三上委員","kind":"質問","question":"ちょっと教えてもらいたいんですが、先ほどのコンテナの特許という部分で、コンパクターで圧縮する設備そのものも特許の部分が入っているんですか。そこのところを教えてくれますか。","respondent":"中山清掃リサイクル課長","answer":"いずれにしましても、今後こういったものの価格、維持管理も含めて、合理的にしていく必要性というのは認識しています。そういったものを十分見極めながら、区としてはより合理的な維持管理の方法というのを探っていきたいというふうに認識しております。","id":"exchange-033"},{"speaker":"三上委員","kind":"質問・要望","question":"今後は共有性というんでしょうか、ある意味では、どうしても排除せざるを得ないという形になってしまいます。逆にこちら側がまたこれを処分しなければならないということになるのか、そこらあたりはどうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"１台当たり約３万円の処分料がかかるという見積もりがございましたので、結論から申しますと、処分費用はかからないことになります。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"２点お伺いしますけれども、東品川作業所のところは、品川区だけでなくて、幾つかくるわけですよね。そこのところをまずお願いしたいと思います。","respondent":"市岡企画財政課長","answer":"今日説明があったかと思うんですが、品川区のほかに目黒区、世田谷区、渋谷区が持ち込んでおります。利用する他区が品川区に使用料を払うという方法も考えられて、検討をしてみたんですが、ごみ量の変化に対して非常に精密な調整作業が必要である。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"もう使用に耐えないということで１００台になっているのか、例えば１００台にすると、おまけで安くしてくれるとかというのがあるのか。そこら辺のところはどうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"先ほど経理課長からの説明もありましたように、平成６年度および平成７年度に東京都清掃局において購入したコンテナです。したがって、現段階で約１００台のコンテナで不燃ごみの中継所の処理が可能であるという認識をしております。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"例えば今回は５０台、来年度が５０台という考え方ですけれども、そうすると、修理が可能かどうかとか、そういうところで精査していくと、今年度は買うにしても、来年度はまた変化する可能性はあるということか尋ねました。","respondent":"市岡企画財政課長","answer":"まだ形状のいいものについては、予備とか、ごみ量の変化に対応する分としてとっておく。このパターンが実は一番安く上がるという計算をいたしまして、それで当面こういう２年間という案をしたわけです。","id":"exchange-037"},{"speaker":"土井副委員長","kind":"質問","question":"船で、いわゆる腐食の面のことを考えると、例えばあの箱を何年ごとに塗り替えているんですかという問題が起こるわけですね。腐食をできるだけ最低限に止めるようにこれからやっていただければもうちょっともつんじゃないかなという気もしたんですが、いかがなものか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"確かに潮風への影響という部分では一定効果があると考えられますが、先ほど企画財政課長が説明したように、かなり内部からの腐食も進んでおります。今のご提案というのは、今後の認識していく中で、腐食の中にそういう両面があるというふうな事実が見られるということがあります。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"それが人件費にはね返ってくるし、あれは迷惑対策だけでつくったのか、あるいは別な合理性があったのかどうか。その合理性については検証されているのかどうかということを教えてほしいと思います。","respondent":"中山清掃リサイクル課長","answer":"こういったものを比較した上で今後の検討材料にしていきたいと思いますけれども、それに伴う、現場に戻って来る時間が長くなる。こういった作業上の効率というものも併せて考えなければいけませんので、いずれにしても、両面で十分分析していきたいと考えています。","id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"やはりそういうことが根底にある程度計算されていないと、契約の交渉を結ぶときの力にならないという時代にきていると思います。新明和工業のほとんど独占状態だと思いますけれども、いずれにしろ、そういうもとのある種の計算が必要だということを指摘したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"大分飛躍してしまう質問かもしれないんですが、場所の土地利用も含めた何かお考えといいますか、計画というものはあるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"移管時に、基本的に清掃関連施設として２０年間使用していくということを条件に都から区に移管されたというものがあります。したがって、こういったものを幅広く考えながら、将来的な東品川清掃作業所の必要性というものは幅広く考えていくべきだという認識は持ってあります。","id":"exchange-041"},{"speaker":"田中委員","kind":"意見","question":"作業効率の面も追求していかなければいけないと思います。２０年間という制約もありつつも、複合施設であれば可能なのかどうかも含めまして、より効果的な利用がされるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問","question":"一般財源のほうなんですけれども、繰り越しをされたときは、実際にはお金は出ていない。そうすると、この呼び方ですると、未支出一般財源という呼び方をしなければおかしくないか尋ねました。","respondent":"市岡企画財政課長","answer":"１回打ち切って、そうすると、仕事を最初からやり直さなければいけません。それで、このような表記をするんですが、意味は委員がおっしゃられるとおりです。","id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問","question":"もうちょっと話を広げてしまって申し訳ないんだけれども、そうすると、今言われている単年度会計というのから脱却する方法というのはなきにしもあらずというふうに考えていいか尋ねました。","respondent":"市岡企画財政課長","answer":"歳入と歳出の関係をきちんと対応するようにすることが財政の主義だと、これを厳格にやりますと、やはり不都合が出てきます。これをまた新しい年度の平成１３年度の予算で仕事をしてしまいますと、全体としてはこのようなやり方が合理的なやり方として認められているです。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問","question":"会計検査のことでお伺いしたいんですが、これはやはり打ち切りますというようなことが都として言えるものなのかどうなのか、その辺のことをお伺いします。","respondent":"市岡企画財政課長","answer":"都と区に置き替えてご説明しますと、国のほうは平成１２年度にぜひこの補助事業をやりたいということで、補正予算という形で予算化をしたものです。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"意見","question":"１０月の集中される時期にまた戻るという結果が生じてくるかもしれないんですけれども、６日は用事で９分９厘埋まりそうだというのが、今の状況です。皆さんの議論は議論として進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"三上委員","kind":"質問","question":"議長の言われたことを考えてみますと、９月１０日が質問通告日ということになるので、直前だったら難しいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"土井副委員長","kind":"質問","question":"同じ時期に各委員会がごそっとみんな行ってしまうわけですから。それから、私自身は、せっかく課題が絞られてきているわけですから、わざわざゆっくり後のほうまでとっておく必要もないんじゃないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"土井副委員長","kind":"質問","question":"３日に議運が入っているようですから、そこを避けなければいけないですね。","respondent":"本多委員長","answer":"やはり通告期限の前としますと、７日には議案説明会が入っておりますので、４日、５日、６日というのが一つの案です。議長からも先ほどお話ししていただきましたが、９月でしたらば、このあたりしか。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"通告の前後というのは、うちのほうも議員団として質問をみんなで検討したりするので、ちょっとそこのところを避けていただきたいというのが一つ。やっぱり１０月の第３回定例会が終わったあたりになるかななどというふうに、私個人としてはそんなところで予定を立てていたんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問","question":"去年は８月２２日、２３日、２４日あたりだったんじゃないですか。〔「お盆のときはだめですね」呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"今のところ、１０月２２日の週ということでいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/517525?Template=document&Id=1550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":36916,"voices":136}},{"id":"h13-20010703-6","meetingId":"h13-cm07","date":"2001年7月3日","dateIso":"2001-07-03","committee":"区民委員会","time":"午前１０時０５分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田副委員長","kind":"質問・要望","question":"私からちょっとよくわからないので教えていただきたいんですが、１６日に変えたというお話なんだけれども、あそこは。よく考えれば、人が多いほうが啓発活動にはつながると思うんだけれども、何でこれをわざわざ月曜日まで延ばす必要があるのか教えてほしい。","respondent":"長田地域活動課長","answer":"そういった意味で、ＰＲの面から考えれば、そのほうがよろしいのかなという気もしないではありません。パルムの入口という条件を考えてみますと、実施をする側の対応といいますか、月曜日に設定をするものです。","id":"exchange-001"},{"speaker":"石田副委員長","kind":"質問・要望","question":"行政評価も始まるわけですから、どこまでお考えかというのをやっていけば、そこら辺のことを含んでもう一回やっていただきたいなと思います。要望にしておきます、これは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"今、ちょっと石田委員からもお話があったんですが、まず、協力のあれで、何で荏原警察署が入っているのか、これは交通安全の面で入っているんか尋ねました。","respondent":"長田地域活動課長","answer":"先ほど申し上げましたとおり、協力要請をしているところに荏原警察署も入ってあります。セレモニー等を行いますので、できるだけ広範な人々にこの趣旨をご理解いただくというようなことから、荏原警察署にも協力を要請したところです。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"〔「ない」と呼ぶ者あり〕ないですか。そうすると、次の質問につながらないんで、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"つけるような指導とか、そういう条件をつけて各町会に配られたんでしょうかね、どうなんでしょうね。日常の中では、どういう区としての対応をされているのか、ちょっと聞かせてほしいと求めました。","respondent":"長田地域活動課長","answer":"町会関係の日常の対応ですけれども、１３地区、さまざまな地域の実情に合った事業を展開しています。ただ、一部の方がまだまだポイ捨てをする現状はありますので、あらゆる機会をとらえてＰＲをしたいと、このように考えているところです。","id":"exchange-005"},{"speaker":"原委員","kind":"質問・要望","question":"そういったところのつけ方というか、のぼりも結局使い古しちゃうと汚くなってしまう部分もありますでしょう。美化になるような形でつけていっていただきたいなと、その辺だけ、ちょっと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"丸５年たって、この条例が恐る恐るに罰則規定がなくて、精神条例だけで効力を発するかどうかという議論が尽くされたと思うんです。施行の記念行事ですから、解決しなければならない問題というのは、どういうふうに認識されているんか尋ねました。","respondent":"長田地域活動課長","answer":"それからあと、罰則をつくるかつくらないかの議論の中で説明をさせていただいたと思いますけれども、やはり地域をきれいにしていこうという運動の中。言ってみれば、スピード違反と同じようなところがあるのかなというような気持ちが私自身もあることはたしかです。","id":"exchange-007"},{"speaker":"本田委員","kind":"確認","question":"１年分のポイ捨てされた缶がワンサと出てくるということで、一切敷地には入ってはならんということで、管理がされていない。安全確認ぐらいはＪＲで出して、おわかりなんだけれども、こういうのはどうやって解決するんか尋ねました。","respondent":"長田地域活動課長","answer":"私どもが進んで対応はしますけれども、そういうような頻度ではとても対応できない、その辺はご理解をいただきたいというようなことでした。そういった部分の対応、あるいは草が茂って状況がひどくなった場合については、個別に対応していただけますねという確認はしています。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"一生懸命やっているわけですから、そういうことを協力し合って、この条例が生かされていきますように要望しておきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認を含めて教えていただきたいんですが、今課長からお話しございましたように、先般の委員会でも指摘したような職員の人ですね。時間の制約の中で、こういうふうに絞られてきたのかどうかわかりませんけれども、その辺の考え方はどうなんか尋ねました。","respondent":"長田地域活動課長、松崎税務課長","answer":"なかなか全区的にという取り組みの難しさ等がございまして、地域を決めて重点的に実施をさせていただいていると、こういう状況です。こういったものも提供いただいて、一緒に啓発活動を実施していただくと… ３０億円からの税収に貢献していただいているというところで、大変私ども品川区にとりましては、重要な組合であるです。エリア的には、すべての品川区をカバーしているというふうに、お考えいただけたらと思います。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問","question":"そうすると、中央のほうですか、港区と品川の一部、そこから、例えば第１回目を大井町でやりましたね。東京中央ですか、品川地区のエリアというんですか、それはどうなんか尋ねました。","respondent":"小栗区民生活事業部長","answer":"地域振興部と区民部のほうも、大井町で街頭キャンペーンのときには両方が第１回目でしたので、参加して合同でやった。それぞれのたばこの関係の団体が主体になって、キャンペーンに参加していただける、こういうような内容です。","id":"exchange-011"},{"speaker":"金高委員","kind":"質問","question":"街のお祭りですから、ですから、そういう面でボランティアにとられてしまうと。その辺の費用的な形でもってせっかくやっていただく方についてどのような形で費用の配布という、その辺を含めてちょっとお知らせ願いたいんですけど。","respondent":"長田地域活動課長","answer":"大崎第一地区みたいに、２日間にわたりまして大崎第一地区の中をさらに四つに分けまして実施をしているところもあります。ですから、合計８日間の実施というところもあります。","id":"exchange-012"},{"speaker":"金高委員","kind":"質問","question":"今年は特に１３地区全部でやるということですから、年に１回のイベントであるし、極力できる限りの手伝いをしていただければというような気がいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"原委員","kind":"意見","question":"例えば、大崎第一地区みたいに、毎週土・日、土・日、土・日、土・日という形で大変じゃないかなと思う。ほかの地域センターの職員さんも総出なんじゃないかなと思うんだけど、その辺のところ、何か反応というか、どう……聞いていらっしゃいますかとの意見を述べました。","respondent":"長田地域活動課長","answer":"前日までの準備と、それから後片づけの期間を含めて、職員も大変この事業に精力的に取り組んでいるのは確かです。その週のうちに消化をしていただくということが原則になってありますので、基本的には、振り替え休暇で対応しています。","id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"職員も相当努力されていて大変なんじゃないかなと思うんですけれども、地域の職員だけじゃなくて、応援に行く部分があるんですか。こちらの本庁のほうから、何人か手を出しますよと、貸しますよというようなことは、ここに書かないんだけど、やっていますか。","respondent":"長田地域活動課長","answer":"私ども応援体制を組んで実施をしていますし、やぐらを組んだり、こういったことも本課の中から応援を出しています。私を含めて１５人ですので、大勢でワッとというわけにはいきませんけれども、必要に応じてお手伝いはさせていただいているところです。","id":"exchange-015"},{"speaker":"原委員","kind":"提案","question":"副委員長のほうからご提案があるんじゃないかと思うんだけれども、震災絡み、商店街づくりの事例という形で行かれていますよね。環境問題はメインの課題とかがあるわけですから、そういったところを調査できるようなものが出てくればいいなというふうには思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"金高委員","kind":"質問","question":"そういったものについては、ちょっといろんな面でもって聞いてみたい、それから見てみたいというのが１点。実際のそれ以外の産業が出ていないということですから、私たちもどういうふうにそれが違うか、一応述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"今日出されたものづくり自慢ですか、ですから、いろんな視察を持っているところへぜひ見に行ってみたいという希望があります。墨田区に限らずで、全各地にいろんな施策を、そういうところをぜひマスタープランとの関係で見に行きたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"東大阪市はちょっと人口が品川区より多くて、５１万人ぐらいの都市になっちゃいますけれども。東大阪市、希望で言えば、東大阪市へ行ってみたいというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"（笑）次、ちょっと控えているものですから。今の相川収入役が商工課長だったんですかね、商業・工業のかなり進んでいるところで、日本の発電所の第１号も京都ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"〔「煮詰めていただいて」と呼ぶ者あり〕それで、それは我々も何も言いませんので、決めていただけばいいなと。結局どこというのはなかなか指示できないですから、そうしようという話になると思います、逆に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"視察先とテーマと振り分けて、この次の委員会で、皆様にお示しできるように整理をしておきたいと思います。２泊３日で実施しておりましたけれども、２泊３日でいいかどうかについても、ちょっと日程的なものもご意見として伺いたいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"堺委員","kind":"提案","question":"幾つか正副でご提示いただいた案を次の委員会にご提案いただけると思うんですが、それによって、どこへ行くか。ご提案いただければ、今の宿駅で京都ですか、ちょっと無理があるからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田副委員長","kind":"意見","question":"今どういう形まで突っ込んで市民が、それはそういう受け入れをしていないところでも、行き方はいろいろあると思います。それも含めて考えていきたいと思いますとの意見を述べました。","respondent":"南委員長","answer":"ちょっとそこのところもいつの時期かも含めて検討させていただいて、次回に提示させていただけるようにいたしますので。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2300#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":20945,"voices":63}}]);
